(window.GIM_TS=window.GIM_TS||{})["Beitzah.0"]={"from":0,"a":[["\u0003ביצה שנולדה ביום טוב, בית שמאי אומרים: תאכל\u0004 אף בו ביום, \u0003ובית הלל אומרים: לא תאכל,\u0004 כפי שיבואר הדבר בגמרא באריכות. כיון שהזכרנו מקרה יוצא דופן שדעת בית שמאי להקל ודעת בית הלל להחמיר, מביאים עוד מהלכות יום טוב אשר אף בהן קיימת תופעה יוצאת דופן זו. \u0003בית שמאי אומרים: שאור,\u0004 שהוא בצק שהחמיץ מאד, שאין עושים ממנו עוד מאכל אלא מחמיצים בו את העיסה, איסורו לענין ביעור חמץ בפסח הוא \u0003ב\u0004שיעור של \u0003כזית,\u0004 אבל \u0003חמץ\u0004 אחר הראוי לאכילה, שיעורו גדול יותר, והוא \u0003בככותבת\u0004 כגודל של פרי התמר. \u0003ובית הלל אומרים: זה וזה\u0004 שיעורן \u0003בכזית.\u0004","ועוד, \u0003השוחט חיה\u0004 או \u0003עוף ביום טוב,\u0004 שמצוה מן התורה לכסות את דמם לאחר שחיטתם (ויקרא יז, יג), \u0003בית שמאי אומרים: יחפור\u0004 מלכתחילה בעפר \u0003ב\u0004אמצעות \u0003דקר\u0004 (מין את חפירה) \u0003ויכסה\u0004 באותו עפר את דם השחיטה. \u0003ובית הלל אומרים: לא ישחוט\u0004 לכתחילה \u0003אלא אם כן היה לו עפר מוכן מבעוד יום\u0004 לצורך זה. אולם \u0003מודים\u0004 גם בית הלל \u0003שאם שחט\u0004 כבר, אף על פי שאסור לו לעשות כן מלכתחילה, \u0003שיחפור בדקר ויכסה.\u0004 ועוד הסכימו \u0003שאפר כירה מוכן הוא\u0004 לכסות בו את הדם. וכאשר יבואר הדבר בגמרא.","מתחילה מבררים: \u0003במאי עסקינן\u0004 \u0005[במה,\u0006 באיזה אופן \u0005עוסקים אנו]\u0006 במשנה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שכאן מדובר \u0003בתרנגולת העומדת לאכילה,\u0004 כלומר, שהיא מן התרנגולות שהתכוונו לשחטן ולאכלן, ואותה תרנגולת הטילה ביצה, אם כן \u0003מאי טעמייהו\u0004 \u0005[מה טעמם]\u0006 של \u0003בית הלל\u0004 האוסרים את הביצה? הלא \u0003אוכלא דאפרת\u0004 \u0005[אוכל שנפרד]\u0006 \u0003הוא,\u0004 שהרי כל התרנגולת נחשבת כדבר מאכל, והביצה הלא היא חלק מן התרנגולת שנפרד ממנה עכשיו, וכשם שאפשר לאכול בחג את התרנגולת עצמה, אף ביצה זו צריכה להיות ראויה לאכילה!","\u0003אלא,\u0004 חייבים אנו לומר כי מדובר כאן \u0003בתרנגולת העומדת לגדל ביצים\u0004 ותרנגולת כזו מאחר והחליטו עליה בעליה שלא להשתמש בה ביום טוב, הריהי מוקצה, והרי ידוע לנו שמוקצה אסור אפילו בטלטול. וכיון שהתרנגולת עצמה מוקצה — אף ביצתה מוקצה.","ואם כן, יש לשאול: \u0003מאי טעמייהו\u0004 \u0005[מה טעמם]\u0006 של \u0003בית שמאי?\u0004 הלא \u0003מוקצה היא!\u0004 על השאלה הזו תוהים: \u0003ומאי קושיא\u0004 \u0005[ומה הקושיה]\u0006 שבדבר? \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003בית שמאי לית להו\u0004 \u0005[אין להם,\u0006 אינם סוברים\u0005]\u0006 דין \u0003מוקצה?\u0004 שהרי יודעים אנו כי קיימות דעות שונות בדבר תוקפו של איסור מוקצה, ויתכן שבית שמאי סבורים (כפי שקיימת דעה כזו בין התנאים) שאין איסור במוקצה כזה, ושמא בכך נחלקו עם בית הלל ואין מקום עוד לשאלה.","כהקדמה לפתרונות שמציעים לבעיה זו מעירים: \u0003קא סלקא דעתין\u0004 \u0005[עלה על דעתנו]\u0006 לומר, כלומר: הנחת היסוד היתה, כי \u0003אפילו מאן דשרי\u0004 \u0005[מי שמתיר]\u0006 \u0003במוקצה,\u0004 שסבור שדבר שהקצוהו בעליו מלהשתמש בו, בכל זאת אין איסור לטלטלו בחג או בשבת, אבל \u0003בנולד\u0004 אף הוא \u0003אסר,\u0004 שדבר שלא היה קיים מבעוד יום אלא שנולד (או התהווה) בחג או בשבת הרי זה אסור לדעתו בטלטול, כיון שבודאי לא העלו על הדעת שיהיה ראוי להשתמש בו. ומעתה, הלא ביצה זו היא נולד גמור, ואם כן \u0003מאי טעמייהו\u0004 \u0005[מה טעמם]\u0006 של \u0003בית שמאי?\u0004","\u0003אמר רב נחמן,\u0004 אפשר לומר כך: \u0003לעולם\u0004 מדובר כאן \u0003בתרנגולת העומדת לגדל ביצים,\u0004 אולם ההנחה שהנחנו לא היתה נכונה, אלא מי \u0003דאית ליה\u0004 \u0005[שיש לו,\u0006 שמקבל בכלל\u0005]\u0006 דיני \u0003מוקצה, אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 גם את האיסור ב\u0003נולד,\u0004 אבל מי \u0003דלית ליה\u0004 \u0005[שאין לו,\u0006 אינו מקבל\u0005]\u0006 דיני \u0003מוקצה, לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 אף דיני \u0003נולד.\u0004 ולפי זה, סיכום הדברים במחלוקת זו הוא ש\u0003בית שמאי כ\u0004דעת \u0003ר' שמעון\u0004 סבורים הם, שלדעתו אין איסור מוקצה, \u0003ובית הלל כ\u0004דעת \u0003ר' יהודה\u0004 סבורים הם, שלדעתו יש איסור מוקצה.","על סברה זו תוהים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב נחמן הכי\u0004 \u0005[כך]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003בית שמאי אומרים: מגביהין\u0004 (מרימים, מסירים) \u0003מעל השלחן עצמות וקליפין\u0004 (קליפות) שנשארו אחרי הסעודה, ואף שאינם ראויים לאכילה והם בבחינת מוקצה, מכל מקום מותר לטלטלם, \u0003ובית הלל אומרים:\u0004 אסור לעשות כן, אלא \u0003מסלק את הטבלא כולה,\u0004 כלומר: את כל החלק העליון של השולחן שניתן לטלטל אותו \u0003ומנערה\u0004 כולה יחד, שאגב טילטול השולחן עצמו שהוא כלי ואינו מוקצה — מטלטלים ומנערים גם את העצמות והקליפות, אבל לטלטל אותן לבד אסור.","\u0003ואמר רב נחמן\u0004 באותו ענין: משנה זו אין גירסתה כהלכה, ויש לתקן את נוסחה, ולהחליף את השיטות כי \u0003אנו אין לנו אלא\u0004 (אנו יודעים כי) \u0003בית שמאי\u0004 סבורים \u0003כ\u0004שיטת \u0003ר' יהודה\u0004 הסבור שיש דין מוקצה, \u0003ובית הלל\u0004 סבורים \u0003כ\u0004שיטת \u0003ר' שמעון\u0004 שאינו סובר דין מוקצה! וכיון שלדעת רב נחמן בית הלל סבורים כר' שמעון שאין דין מוקצה, מדוע מפרש הוא את דעת בית הלל במשנתנו שזאת משום שכדעת ר' יהודה סבורים הם?","ומשיבים: \u0003אמר לך\u0004 \u0005[היה אומר,\u0006 משיב \u0005לך]\u0006 \u0003רב נחמן\u0004 כך: \u0003גבי שבת\u0004 ש\u0003סתם לן\u0004 \u0005[לנו]\u0006 ה\u0003תנא,\u0004 שסתם משנה שלא פורש שם אומרה (והוא סימן שכן היא ההלכה העיקרית) היא \u0003כ\u0004שיטת \u0003ר' שמעון, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במסכת שבת: \u0003מחתכין את הדלועין לפני הבהמה\u0004 כדי שתוכל לאוכלן בקלות, וכן מחתכין \u0003את הנבלה\u0004 ואפילו זו שמתה בשבת \u0003לפני הכלבים\u0004 כדי שיוכלו לאכול אותה, שאף שנבילה זו מוקצה היא, מכל מקום מותר לטלטלה ולהתעסק בה בשבת.","הרי סתם משנה כדעת ר' שמעון, וכיון שסתם משנה במסכת שבת כדעת ר' שמעון, לכן \u0003מוקים לה\u0004 \u0005[מעמיד,\u0006 מסביר, \u0005אותה]\u0006 רב נחמן באופן ש\u0003בית הלל\u0004 יסברו \u0003כ\u0004דעת \u0003ר' שמעון\u0004 שנראה שהלכה כמותו, כדי שיתאים הדבר עם הכלל שהלכה תמיד כבית הלל. \u0003אבל\u0004"],["\u0003גבי יום טוב\u0004 ש\u0003סתם לן\u0004 \u0005[לנו]\u0006 ה\u0003תנא\u0004 בסתם משנה כדעת \u0003ר' יהודה, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במסכת ביצה: \u0003אין מבקעין\u0004 ביום טוב \u0003עצים מן הקורות\u0004 שהכינו לצורך בנין \u0003ולא\u0004 מבקעים עצי הסקה \u0003מן הקורה שנשברה ביום טוב,\u0004 וכל זה מפני שלא היו עשויים לכך בשעת כניסת החג ולכך נעשו מוקצה. אם כן משמע שסתם משנה אוסרת מוקצה ביום טוב, לכן \u0003מוקים לה\u0004 \u0005[מעמיד,\u0006 מסביר \u0005אותה]\u0006 רב נחמן את שיטת \u0003בית הלל כר' יהודה\u0004 האוסר מוקצה בטלטול והעמידה במקרה שהתרנגולת עומדת לגדל ביצים ולכן היא מוקצה\u0003.\u0004 עד כאן להסברת שינוי השיטה בדברי רב נחמן.","אולם יש לשאול על עיקר הדברים: \u0003מכדי\u0004 \u0005[והרי],\u0006 \u0003מאן סתמיה למתניתין\u0004 \u0005[מי הוא זה שסתם את המשניות],\u0006 שכתב וניסח אותן — הלא \u0003רבי\u0004 (ר' יהודה הנשיא) הוא, וכיון שאדם אחד ניסח את הדברים בשתי המסכתות, יש לשאול: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003ב\u0004דיני \u0003שבת\u0004 ש\u0003סתם\u0004 ופסק \u0003לן\u0004 \u0005[לנו]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון, ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003ב\u0004דיני \u0003יום טוב\u0004 ש\u0003סתם\u0004 ופסק \u0003לן\u0004 \u0005[לנו]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה?\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 להשיב: יש טעם לדבר; \u0003שבת דחמירא\u0004 \u0005[שהיא חמורה]\u0006 בעונשיה ובדיניה \u0003ולא אתי לזלזולי\u0004 \u0005[באים לזלזל]\u0006 \u0003בה\u0004 — \u0003סתם לן\u0004 \u0005[לנו]\u0006 במשנה \u0003כ\u0004דעת \u0003ר' שמעון דמיקל\u0004 \u0005[ש\u0006הוא \u0005מיקל],\u0006 ואילו \u0003יום טוב דקיל\u0004 \u0005[ש\u0006הוא \u0005קל],\u0006 משום שמותר לעשות בו מקצת מלאכות, \u0003ואתי לזלזולי ביה\u0004 \u0005[ובאים לזלזל בו]\u0006 בשל כך יותר, לכן \u0003סתם לן\u0004 \u0005[לנו]\u0006 במשנה \u0003כ\u0004שיטת \u0003ר' יהודה דמחמיר\u0004 \u0005[ש\u0006הוא \u0005מחמיר].\u0006 עד כאן לישוב דבריו של רב נחמן.","ומעתה ממשיכים לדון בדבריו כשלעצמם: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת]\u0006 את המשנה בסופו של דבר — \u0003בתרנגולת העומדת לגדל בצים,\u0004 והאיסור הוא \u0003משום מוקצה. אי הכי\u0004 \u0005[אם כך]\u0006 אם בזה המחלוקת, \u0003אדמפלגי\u0004 \u0005[עד ש\u0006הם \u0005חלוקים]\u0006 \u0003ב\u0004ענין \u0003ביצה\u0004 שנולדה ביום טוב, \u0003לפלגו\u0004 \u0005[שיחלקו]\u0006 \u0003בתרנגולת\u0004 עצמה! שידונו אם מותר לשחוט תרנגולת כזו ביום טוב, ומדוע דנים בפרט המשני של הביצה?","ומשיבים: לאמיתו של דבר חולקים הם גם כן בתרנגולת, אלא ניסחו את הדברים באופן זה כדי \u0003להודיעך כחן\u0004 (תוקף דעתם) של \u0003בית שמאי,\u0004 כלומר: להדגיש את קיצוניות שיטתם של בית שמאי שמפליגים בהיתר, שאפילו בביצה שאינה מוקצה רגיל, אלא \u0003נולד\u0004 שהוא חמור ממוקצה, גם כן \u0003שרי\u0004 \u0005[התירו]\u0006 בית שמאי. ולכן כשחולקים בביצה מודגשת דעתם ביתר שאת.","על כך מקשים: \u0003ולפלוגי\u0004 \u0005[ושיחלקו]\u0006 לא בביצה כי אם \u0003בתרנגולת\u0004 ו\u0003להודיעך\u0004 על ידי כך \u0003כחן\u0004 של \u0003בית הלל\u0004 שאפילו \u0003במוקצה\u0004 הקל מנולד \u0003אסרי\u0004 \u0005[\u0006הם \u0005אוסרים]!\u0006 \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ותרצה להסביר שעדיף לשנות את המחלוקת כמות שהיא, בצורה זו, משום שעל ידי כך מתבררת יותר שיטת המתירים, כי \u0003כח דהתירא\u0004 \u0005[ההיתר]\u0006 \u0003עדיף\u0004 להשמיענו. כי כרגיל ראוי יותר להדגיש ולהראות את שיטת המתירים, לפי שפשוט יותר להחמיר מפני גזירה וחשש, מאשר להתיר. ומשום כך העדיף התנא לשנות בדרך זו. אולם הרי יש אפשרות אחרת: \u0003ונפלוג בתרוייהו\u0004 \u0005[ושיחלקו בשניהם]\u0006 ויאמרו כך:","\u0003תרנגולת העומדת לגדל ביצים, היא וביצתה, בית שמאי אומרים: תאכל, ובית הלל אומרים: לא תאכל,\u0004 ועל ידי כך נדע בלא להאריך יותר מדי את כל צדדי המחלוקת. ואם כן אין פירושו של רב נחמן מסביר לגמרי את המשנה.","\u0003אלא, אמר רבה: לעולם\u0004 יש לדחות את מה שאמרנו, ולומר כי מדובר כאן \u0003בתרנגולת העומדת לאכילה,\u0004 ובמקרה מסויים זה שנולדה הביצה \u0003ביום טוב שחל להיות אחר השבת עסקינן\u0004 \u0005[עוסקים אנו],\u0006 והבעיה כאן אינה משום איסור מוקצה, אלא \u0003משום\u0004 איסור \u0003הכנה\u0004 משבת ליום טוב.","\u0003וקסבר\u0004 \u0005[וסבר]\u0006 \u0003רבה\u0004 בענין זה, כי \u0003כל ביצה דמתילדא האידנא\u0004 \u0005[שנולדה עכשיו] — כבר\u0006 \u0003מאתמול גמרה לה\u0004 \u0005[נגמרה\u0006 להיווצר\u0005],\u0006 ורק יציאתה לחוץ היתה היום. ומשום כך הביצה שנולדה ביום טוב שלאחר השבת לא תאכל, משום שהיא הוכנה ביום השבת, ונמצא שנהנים מדבר שהוכן בשבת לצורך יום טוב (אף שלא הוכנה בידי אדם אלא בידי שמים), שלא כדין.","ומעירים: \u0003ורבה\u0004 האוסר להנות אפילו מדבר שלא הוכן בידי אדם, הולך בענין זה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר רבה: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 בענין המן: \u0003\"והיה ביום הששי והכינו את אשר יביאו\"\u0004 (שמות טז, ה) — יש ללמוד לדבריו מדיוק המילים כי יום \u0003חול\u0004 (\"ביום השישי\") \u0003מכין לשבת, ו\u0004יום \u0003חול מכין ליום טוב,\u0004 אבל \u0003אין יום טוב\u0004 (שאף הוא מוגדר כ\"שבת\" לענין זה) \u0003מכין לשבת, ואין שבת מכינה ליום טוב.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה,\u0004 שהחשש הוא רק משום הכנה, אם כן ביצה שנולדה ב\u0003יום טוב בעלמא\u0004 \u0005[סתם]\u0006 שאינו אחר השבת \u0003תשתרי\u0004 \u0005[תהיה מותרת]!\u0006 השיב לו: אכן, אינה אסורה מעיקר הדין, אלא בשל \u0003גזרה, משום יום טוב\u0004 החל \u0003אחר השבת.\u0004 ומוסיפים לשאול: \u0003שבת דעלמא\u0004 \u0005[סתם]\u0006 שאינה אחר יום טוב, \u0003תשתרי\u0004 \u0005[תהיה מותרת]\u0006 לאכול בה (בלא בישול, כמובן) ביצה שנולדה בו ביום! השיב רבה: \u0003גזרה משום שבת\u0004 ש\u0003אחר יום טוב.\u0004","ושואלים: \u0003ומי גזרינן\u0004 \u0005[והאם גוזרים אנו]\u0006 גזירה מעין זו? \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003השוחט את התרנגולת\u0004 ביום טוב ופקע את בטנה \u0003ומצא בה ביצים גמורות\u0004 בקליפתן, אלא שעדיין לא הוטלו — \u0003מותרות לאכלן ביום טוב. ואם איתא\u0004 \u0005[יש]\u0006 מקום לגזור — אם כן \u0003ליגזר\u0004 \u0005[שיגזור]\u0006 \u0003משום הנך דמתילדן ביומיהן\u0004 \u0005[אלה שנולדות ביומן,\u0006 בו ביום\u0005]\u0006 ויאסרו אף ביצים אלה שבתוך התרנגולת!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: מכאן אין להקשות, כי \u0003ביצים גמורות\u0004 ממש הנמצאות \u0003במעי אמן מילתא דלא שכיחא היא\u0004 \u0005[דבר שאינו מצוי הוא],\u0006 \u0003ומילתא דלא שכיחא\u0004 \u0005[ודבר שאינו שכיח]\u0006 \u0003לא גזרו בה רבנן\u0004 \u0005[חכמים],\u0006 שאין גזירותיהם אלא בדברים המצויים, שאנשים עשויים לטעות בהם, אבל במקרה נדיר לא גזרו. עד כאן הסברו של רבה, אולם היו גם הסברים אחרים.","\u0003רב יוסף אמר:\u0004 ביצה זו שנולדה ביום טוב לתרנגולת העומדת לאכילה, אסורה מטעם אחר: \u0003גזרה משום פירות הנושרין.\u0004 כי, כשם שהפירות הנושרים מן העץ בשבת וביום טוב אסורים באכילה — כך גם הביצים היוצאות (\"הנופלות\") מן התרנגולת דומות לפירות אלה. ומשום כך נאסרו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: פירות הנושרין טעמא מאי\u0004 \u0005[מה הטעם]\u0006 בעצם שאסרו אותם חכמים,"],["\u0003הלא כל זה גזרה\u0004 היא \u0003שמא יעלה\u0004 באילן \u0003ויתלוש\u0004 ויעבור על איסור מן התורה (\"קצירה\", שבכללה כל קטיפת פרי) ואם כן \u0003היא גופא\u0004 \u0005[עצמה],\u0006 איסור אכילת הפירות, הוא משום \u0003גזרה\u0004 בלבד, \u0003ואנן ניקום\u0004 \u0005[ואנחנו נעמוד]\u0006 \u0003ונגזור גזרה\u0004 על \u0003גזרה? כולה חדא גזרה\u0004 \u0005[גזירה אחת]\u0006 \u0003היא,\u0004 כלומר: שמתחילה בכלל גזירתם היו גם הפירות וגם הביצה, שיש להם בענין זה דמיון מסויים.","\u0003ר' יצחק אמר\u0004 טעם אחר: ביצה שנולדה ביום טוב אסורה \u0003גזרה משום משקין שזבו\u0004 (נזלו ויצאו) מתוך פירות, שאסורים לבו ביום, וכשם שמשקים אלה אסורים באכילה ביום טוב כך אסור לאכול ביצה שנולדה ביום טוב, שהיא כמשקה שיצא מן הפרי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: משקין שזבו טעמא מאי\u0004 \u0005[מה טעם]\u0006 אסרו אותם מעיקרם — \u0003גזרה שמא יסחוט\u0004 את הפירות בכוונה (ונמצא עובר משום איסור תורה של \"דש\") אולם \u0003היא גופא\u0004 \u0005[עצמה]\u0006 איסור משקים אלה משום \u0003גזרה\u0004 היא, \u0003ואנן ניקום\u0004 \u0005[ואנחנו נעמוד]\u0006 \u0003ונגזור גזרה\u0004 על \u0003גזרה?\u0004 והשיב ר' יצחק: \u0003כולה חדא גזרה\u0004 \u0005[גזירה אחת]\u0006 \u0003היא,\u0004 כלומר: באותה שעה שאסרו משקים שזבו, אסרו גם בביצה ומאותו טעם, שכל הדברים הללו עלולים להביא לידי איסור. כיון שניתנו למשנתנו ביאורים שונים, באים להסביר מה גרם לחכמים שלא הסתפקו בהסבר של אחד מהם ובאו להציע שיטות נוספות.","ואומרים: \u0003כולהו\u0004 \u0005[כולם]\u0006 רבה, רב יוסף ור' יצחק \u0003כ\u0004שיטת \u0003רב נחמן לא אמרי\u0004 \u0005[אמרו]\u0006 — \u0003כי קושיין\u0004 \u0005[כמו קושייתנו]\u0006 שהקשינו והראינו שדבריו דחוקים קצת. \u0003כ\u0004שיטת \u0003רבה נמי לא אמרי\u0004 \u0005[גם כן לא אמרו]\u0006 האחרים — כי איסור \u0003הכנה לית להו\u0004 \u0005[אין להם],\u0006 כלומר: אינם סבורים שיש בכך איסור מן התורה.","\u0003אלא\u0004 יש לשאול: \u0003רב יוסף מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כר' יצחק,\u0004 שהרי לכאורה הדברים דומים, ומדוע לא פירש כדעת ר' יצחק? ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה רב יוסף \u0005לומר לך]:\u0006 \u0003ביצה\u0004 הלא \u0003אוכלא\u0004 \u0005[\u0006דבר \u0005מאכל]\u0006 היא \u0003ופירות אוכלא\u0004 \u0005[מאכל]\u0006 הם ולכן אפשר לדמות את הביצה לפירות שנשרו, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003משקין דלאו אוכלא\u0004 \u0005[שאינם מאכל]\u0006 אלא משקה, ואין הדברים דומים כלל.","ושואלים מצד שני: \u0003ור' יצחק מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כר' יוסף?\u0004 ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך];\u0006 לדעתו יש דמיון גדול יותר בין משקים שזבו לביצה, כיצד — \u0003ביצה\u0004 לפני שנולדה \u0003בלועה\u0004 (נסתרת) היא בתוך התרנגולת, וכן \u0003המשקין בלועין\u0004 הם בתוך הפירות, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 מ\u0003פירות\u0004 אילן שנשרו \u0003דמגלו וקיימו\u0004 \u0005[שהם גלויים ועומדים]\u0006 על העץ, ולכן אין ההשוואה לפירות שנפלו טובה כהשוואה למשקים שזבו.","ומעירים: \u0003ואף ר' יוחנן סבר\u0004 שאיסור אכילת ביצה שנולדה ביום טוב \u0003גזרה\u0004 היא \u0003משום משקין שזבו.\u0004 וכיצד יודעים אנו זאת — ש\u0003ר' יוחנן רמי\u0004 \u0005[היה משליך,\u0006 מראה סתירה\u0005]\u0006 מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה\u0004 במקום אחר, \u0003ומשני\u0004 \u0005[ומתרץ],\u0006 ומתוך דבריו למדים דבר זה.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין סוחטין את הפירות להוציא מהן משקין\u0004 בשבת, \u0003ואם יצאו\u0004 המשקים \u0003מעצמן\u0004 — \u0003אסורין\u0004 בשתיה בו ביום, גזירה שמא יסחוט בכוונה. \u0003ר' יהודה אומר: אם לאוכלין,\u0004 כלומר: אם פירות אלה מיועדים בעיקר לצורך אכילה (כגון תפוחים), הרי המשקים \u0003היוצאין מהן מותרין,\u0004 שכן אין חשש שיבוא לסוחטם ואין סיבה לגזירה. אולם \u0003אם\u0004 הפירות הללו מיועדים \u0003למשקין\u0004 (כגון ענבי יין) ויש חשש שיבוא לסחוט, הרי המשקים \u0003היוצאין מהן אסורין.\u0004","\u0003אלמא\u0004 \u0005[מכאן]\u0006 ממה שאמר כי משקים שיצאו מפירות המיועדים לאוכלים מותרים, אפשר להסיק כי \u0003כל אוכלין\u0004 היוצאים מאוכל אחר, לדעת \u0003ר' יהודה אוכלא דאפרת\u0004 \u0005[אוכל שנפרד]\u0006 \u0003הוא,\u0004 והאוכל שנפרד איננו נחשב כמאכל חדש, אלא כחלק ממה שהיה קודם.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממקום אחר; \u0003ועוד אמר ר' יהודה:\u0004 בדין פירות שאינם מעושרים שאינו רשאי לתקנם ולהפריש מהם תרומות ומעשרות ביום טוב, אבל אם רצה לאוכלם — \u0003מתנה אדם\u0004 מראש \u0003על כלכלה\u0004 (סל) \u0003של פירות\u0004 טבל שהיו בידו, \u0003ביום טוב ראשון\u0004 של ראש השנה ואומר: אם היום הוא יום החג האמיתי, הרי היום השני של החג יום חול הוא — והפירות הללו מותרים בו כביום חול אחר לאחר שיתקנם בו. ולהיפך, אם היום הזה הוא באמת יום חול ומחר הוא יום החג הריני מפריש מהם היום.","וכן למחרת יחזור ויאמר: אם היום חול ואתמול קודש, הריני מפריש עכשיו ומתקן את הפירות, ואם היום קודש ואתמול היה חול, אם כן די במה שהפרשתי אתמול ודי בכך ו\u0003אוכלה ב\u0004יום טוב ה\u0003שני,\u0004 שבכל אופן אין בכך איסור, \u0003וכן ביצה שנולדה ב\u0004יום טוב \u0003ראשון תאכל ב\u0004יום טוב \u0003שני\u0004 מכל מקום.","ומדבריו אלה למדנו ש\u0003בשני\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מותר לאכול את הביצה, אולם ביצה שנולדה \u0003בראשון\u0004 עצמו \u0003לא\u0004 תאכל. ואם כן יש סתירה בדברי ר' יהודה, שהרי אמר שמשקים היוצאין מדבר המוכן לאכילה נחשבים כדבר אוכל עצמו, ואין זה אלא כהפרדת שני אוכלים האחד מהשני! \u0003ומשני\u0004 \u0005[ומתרץ]\u0006 \u0003ר' יוחנן: מוחלפת השיטה,\u0004 כלומר: יש להחליף בסוגיית יום טוב שני את דיעות החולקים כדי להשוות את השיטה.","ולענייננו נלמד: \u0003ומדקא מרמי להו אהדדי\u0004 \u0005[וכיון שמקשה אותם\u0006 ר' יוחנן \u0005זה על זה]\u0006 \u0003שמע מינה חד טעמא הוא\u0004 \u0005[מכאן\u0006 תלמד \u0005שטעם אחד הוא]\u0006 שהביצה נאסרה ביום טוב משום גזירת משקים שזבו."],["\u0003רבינא אמר\u0004 לגופה של הסתירה הזו שהראה ר' יוחנן וכתוצאה מכך אמר כי יש להפוך את השיטות, אין צורך בפתרון זה דווקא: \u0003לעולם לא תיפוך\u0004 \u0005[אל תהפוך\u0006 את השיטות\u0005],\u0006 אלא בענין שני ימים של יום טוב אפשר לומר כי \u0003ר' יהודה לדבריהם דרבנן\u0004 \u0005[של חכמים]\u0006 \u0003קאמר להו\u0004 \u0005[אמר להם]\u0006 ולא לפי שיטתו שלו, וכך יש להבין את דבריו:","\u0003לדידי\u0004 \u0005[לשיטתי]\u0006 \u0003אפילו ב\u0004יום טוב ה\u0003ראשון נמי שריא\u0004 \u0005[גם כן מותרת]\u0006 הביצה, כיון \u0003דאוכלא דאפרת\u0004 \u0005[שאוכל שנפרד]\u0006 \u0003הוא, אלא לדידכו\u0004 \u0005[לשיטתכם]\u0006 שאתם אוסרים במשקה היוצא מאוכל — \u0003אודו לי מיהת דבשני שריא\u0004 \u0005[הודו לי על כל פנים\u0006 \u0005שב\u0006יום \u0005השני היא מותרת],\u0006 שהרי \u0003שתי קדושות הן.\u0004 כלומר: יום ראשון ושני של ראש השנה אינם המשך אחד, אלא נחשבים לשתי מהויות נפרדות, ויתכן כי הראשון קודש והשני חול, שהרי אין נוהגים בשניהם קדושה אלא מחמת הספק, ולכן מה שאסור בראשון אין לאוסרו בהכרח אף בשני. \u0003ואמרי ליה רבנן\u0004 \u0005[ואמרו לו חכמים]:\u0006 \u0003לא, קדושה אחת היא\u0004 בשני הימים, שרואים אותם כהמשך אחד, והספק נמשך בשניהם.","\u0003רבינא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב עולא אמר\u0004 תירוץ אחר לסתירה שהראה ר' יוחנן: \u0003הכא\u0004 \u0005[כאן]\u0006 בענין ביצה שנולדה ביום טוב שאסרה ר' יהודה באכילה, מדובר לא בתרנגולת העומדת לאכילה שהיא כשלעצמה אוכל, אלא \u0003בתרנגולת העומדת לגדל ביצים, ור' יהודה לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 \u0003דאית ליה\u0004 \u0005[שיש לו\u0006 שהוא סובר\u0005]\u0006 דין \u0003מוקצה,\u0004 ולכן הביצה היוצאת מן המוקצה היא בעצמה מוקצה, ואין כאן מקום לדין של אוכל שנפרד.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מן הברייתא, לברר את הנושא באופן אחר. שנינו שם: \u0003אחד ביצה שנולדה בשבת ואחד ביצה שנולדה ביום טוב\u0004 — הריהי מוקצה, ולכך \u0003אין מטלטלין אותה\u0004 לא לאכילה ולא לכל צורך אחר; \u0003לא לכסות בה את הכלי, ולא לסמוך בה כרעי המטה.\u0004","\u0003אבל\u0004 אם רוצה, \u0003כופה\u0004 (הופך) \u0003עליה\u0004 על הביצה \u0003את הכלי\u0004 מבלי לטלטלה, \u0003בשביל שלא תשבר\u0004 על ידי דריסת הרגל עליה בלא מתכוון. ואף שהיא עצמה אסורה בטלטול, מכל מקום הותר לטלטל כלי לצורכה. \u0003ו\u0004אף \u0003ספיקה\u0004 של ביצה זו \u0003אסורה.\u0004 שגם כשספק אם נולדה ביצה זו ביום טוב הריהי אסורה, \u0003ו\u0004אף \u0003אם נתערבה באלף\u0004 ביצים כשירות — \u0003כולן אסורות.\u0004","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רבה,\u0004 ש\u0003אמר\u0004 שהאיסור בביצה זו הוא \u0003משום הכנה,\u0004 אם כן \u0003הוי ספיקא דאורייתא\u0004 \u0005[הרי זה ספק מן התורה]\u0006 \u0003וכל ספיקא דאורייתא\u0004 \u0005[ספק מן התורה]\u0006 הריהו \u0003לחומרא\u0004 \u0005[להחמיר],\u0006 ולכן אף ספיקה של ביצה זו אסורה.","\u0003אלא ל\u0004שיטת \u0003רב יוסף ורב יצחק, דאמרי\u0004 \u0005[שהם אומרים]\u0006 \u0003משום גזרה,\u0004 ואם כן האיסור הוא רק מדברי סופרים, ואם כן \u0003ספיקא דרבנן היא\u0004 \u0005[ספק מדברי סופרים הוא]\u0006 והרי כלל הוא כי \u0003כל ספיקא דרבנן\u0004 \u0005[ספק מדברי סופרים]\u0006 הרי ידוע שנוהגים בו \u0003לקולא\u0004 \u0005[להקל]!\u0006","ומתרצים: \u0003סיפא אתאן\u0004 \u0005[בסופה\u0006 של הברייתא \u0005באנו]\u0006 לדון לא באיסור ביצה שנולדה ביום טוב אלא בביצה שנולדה מתרנגולת שהיא \u0003ספק טריפה\u0004 (שהוא איסור מן התורה), וכשם שהיא עצמה ספק כך גם ביצתה היא ספק טריפה.","על תירוץ זה מקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של אותה ברייתא, נאמר שם: \u0003נתערבה באלף\u0004 — \u0003כולן אסורות.\u0004 ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שביצה זו היא \u0003ספק\u0004 ביצה שנולדה ב\u0003יום טוב, ספק\u0004 נולדה ביום \u0003חול,\u0004 אם כן \u0003הוי\u0004 \u0005[הרי היא]\u0006 בגדר \u0003דבר שיש לו מתירין,\u0004 שהרי איסור זה שבביצה הוא רק לבו ביום, ולמחרת היא מותרת, וכלל בידינו: \u0003כל דבר שיש לו מתירין\u0004 (אופן מסויים של היתר) לאחר זמן — \u0003אפילו באלף לא בטיל\u0004 \u0005[אינו בטל],\u0006 שהרי איסורו יפקע ממילא, ואין צורך להזדקק לענין של ביטול האיסור.","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שביצה זו שעסקה בה הברייתא היא \u0003ספק טרפה,\u0004 אם כן \u0003דבר שאין לו מתירין היא\u0004 שהרי אין היתר לאיסור טריפה, \u0003ותבטל ברובא\u0004 \u0005[ברוב],\u0006 ואפילו בפחות מאלף!","ומוסיפים: \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003ביצה חשובה ולא בטלה,\u0004 שאין ביטול אלא בדברים שאין להם יחוד וחשיבות לעצמם, אבל דבר חשוב אינו בטל, \u0003הניחא למאן\u0004 \u0005[זה נוח\u0006 \u0005ל\u0006שיטת \u0005מי]\u0006 ש\u0003אמר\u0004 כי \u0003כל\u0004 דבר \u0003שדרכו לימנות,\u0004 כלומר: שלפעמים מוכרים אותו לפי מנין יחידות (ולא במשקל או במידה) \u0003שנינו\u0004 והחשבנוהו לדבר חשוב, ודבר חשוב כזה איננו בטל אפילו באלף, אם כן הוא הדין לביצה שהרי אף היא נמכרת לעתים על פי מנין,","\u0003אלא למאן\u0004 \u0005[ל\u0006דעת \u0005מי]\u0006 ש\u0003אמר\u0004 כי \u0003את שדרכו לימנות שנינו\u0004 שדבר חשוב הוא רק זה שתמיד מוכרים אותו במנין ולא באופן אחר, אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 לשיטתו, שהרי לעיתים מוכרים ביצים רבות בכלי אחד, לפי אומדן! על מנת להסביר היטב את ענין המחלוקת בדבר ש\"דרכו לימנות\" מביאים את המשנה המקורית.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שהיו לו חבילי תלתן\u0004 (מין קטניות) \u0003של כלאי הכרם,\u0004 כלומר: צמחי תלתן שגדלו בתוך כרם והם אסורים משום כך בהנאה מדין כלאים, הרי חבילות אלה — \u0003ידלקו\u0004 (ישרפו). \u0003נתערבו\u0004 חבילות אלה \u0003באחרות, ו\u0004אותן \u0003אחרות\u0004 נתערבו שוב \u0003באחרות\u0004 — \u0003כולן ידלקו,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: יעלו\u0004 (יתבטלו) \u0003באחת ומאתים\u0004 שכמותם. שאם האיסור הוא פחות מאחד במאתים מן ההיתר — הרי הוא בטל.","\u0003שהיה ר' מאיר אומר: את שדרכו למנות\u0004 — \u0003מקדש\u0004 (אוסר, פוסל). כלומר: כל דבר שמונים אותו הוא דבר חשוב, ולכן איננו מתבטל כלל, בכל רוב, ומשום כך גם אוסר את תערובתו ועליו להשרף. \u0003וחכמים אומרים:\u0004 אף פרי \u0003אינו מקדש\u0004 (אוסר) \u0003אלא ששה דברים בלבד\u0004 שהם חשובים ואינן בטלים, \u0003ר' עקיבא אומר שבעה\u0004 דברים הם. \u0003ואלו הן: אגוזי פרך\u0004 אגוזים מסוג משובח הבאים מהמקום פרך, \u0003ורמוני באדן\u0004 רמונים הבאים מן המקום באדן, \u0003וחביות\u0004 יין \u0003סתומות, וחלפי\u0004 (ענפי) \u0003תרדין, וקלחי כרוב, ודלעת יונית. ר' עקיבא מוסיף אף ככרות של בעל הבית.\u0004","שבעה דברים אלה ששנינו כאן אינם יכולים להיות כלולים במין אחד של איסורים אלא \u0003הראוי לערלה\u0004 — \u0003ערלה,\u0004 שיש מהם שהם מיני אילנות, ונזכרו משום שחל עליהם איסור ערלה שהוא איסור הנאה. \u0003הראוי לכלאי הכרם\u0004 שהם מיני ירקות וקטניות הנאסרים משום היותם כלאי הכרם — הרי הם \u0003כלאי הכרם. ואתמר עלה\u0004 \u0005[ונאמר\u0006 שנחלקו \u0005עליה],\u0006 בדבר נוסחה המדוייק של משנה זו, \u0003ר' יוחנן אמר: \"את שדרכו למנות\" שנינו\u0004 שגם ר' מאיר לא אמר שאין ביטול אלא בדברים שדרכם להימכר רק במנין. \u0003ור' שמעון בן לקיש אמר: \"כל שדרכו למנות\" שנינו.\u0004 כלומר: כל דבר שרק לפעמים נוהגים למכור אותו במנין — חשוב הוא ואינו בטל.","ולענייננו בדבר ביצה, \u0003הניחא\u0004 \u0005[דבר זה נוח]\u0006 \u0003ל\u0004דעת \u0003ר' שמעון בן לקיש, אלא לר' יוחנן מאי איכא למימר\u0004 שהרי ביצה אינה דבר הנמכר תמיד במנין, ולכן אינה חשובה, וביצה טריפה היתה צריכה להיבטל ברוב!","\u0003אמר רב פפא,\u0004 אפשר לתרץ: \u0003האי תנא\u0004 \u0005[תנא זה]\u0006 שאמר שביצה אינה בטילה הוא ה\u0003תנא\u0004 ששנה בענין \u0003ליטרא קציעות הוא,\u0004 ש\u0003אמר\u0004 (כלומר: מתוך דבריו נובע), כי \u0003כל דבר שבמנין, אפילו\u0004 בדבר שאיסורו רק \u0003בדרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003לא בטיל\u0004 \u0005[בטל],\u0006 \u0003כל שכן\u0004 אם היה זה בדבר שאיסורו \u0003בדאורייתא\u0004 \u0005[מן התורה],\u0006 כגון ביצה טריפה.","ומביאים את הדברים במקורם, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003ליטרא\u0004 של \u0003קציעות\u0004 תאנים שקוצצים את עוקציהן, מייבשים, ואחר כך כובשים אותן בכלים שונים ועושים מהם עיגולי דבילה. וליטרא זו שכח להפריש ממנה תרומות ומעשרות, והפרשת מעשר מפירות מדברי סופרים בלבד היא. אם זוכר אותו אדם שאותה ליטרא עשאה דבילה ו\u0003דרסה\u0004 (דחק אותה, בתהליך ייצורה) \u0003על פי עגול\u0004 בפיו של אחד מן העיגולים שנהוג לדרוס בהם את הקציעות, שיהפכו להיות לדבילה, אבל \u0003אינו יודע באיזה עגול דרסה,\u0004 אף על פי שזוכר בבירור כי דרסה על פיו, או שזוכר שדרסה \u0003על פי חבית ואינו יודע באיזו חבית דרסה,\u0004 או \u0003על פי כורת\u0004 (שאף היא כלי עגול, המשמש גם לדבורים) \u0003ואינו יודע באיזו כורת דרסה. ר' מאיר אומר\u0004 שבנושא זה נחלקו כבר תנאים בדור קודם, \u0003ר' אליעזר\u0004"],["\u0003אומר: רואין את העליונות\u0004 כלומר את כל ליטרות הקציעות העליונות \u0003כאילו הן פרודות\u0004 שאנו דנים אותן לא כיחידה אחת אלא כאילו היתה כל אחת מהן לבדה, \u0003והתחתונות\u0004 שנמצאות שם זה מכבר ובוודאי מעושרות הן, \u0003מעלות\u0004 (מבטלות) \u0003את העליונות\u0004 ברוב, שכן יש בתוך החבית או העיגול כמות מספקת כדי שיתבטל הכל.","ואילו \u0003ר' יהושע אומר: אם יש שם מאה פומין\u0004 (פיות שונים) של חביות או עיגולים הרי פי העיגול שנאסר על ידי הליטרא שלא הפרישו ממנה \u0003יעלו,\u0004 משום שפה זה בטל באחד ומאה, \u0003ואם לאו\u0004 — הרי כל \u0003הפומין\u0004 (הפיות של החביות או הכוורות) שברור שיש באחד מהם ליטרא אחת של איסור — כולם \u0003אסורין, והשולים\u0004 פנים הכלים — \u0003מותרין,\u0004 שהרי ברור שלשם לא נכנס האיסור. זו היתה גירסת ר' מאיר באותה מחלוקת.","\u0003ר' יהודה אומר\u0004 שכך נחלקו הראשונים, \u0003ר' אליעזר אומר: אם יש שם מאה פומין\u0004 של היתר חוץ מן האיסור — \u0003יעלו\u0004 במאה ואחת של ההיתר, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003הפומין אסורין והשולים מותרין. ר' יהושע אומר: אפילו יש שם שלש מאות פומין לא יעלו,\u0004 לפי שליטרא זו אין לה ביטול כלל. והוא שאמר רב פפא שיש תנא (ר' יהושע לשיטת ר' יהודה) הסבור שדבר שלפעמים מוכרים אותו במנין, כגון ליטרא של קציעות, גם הוא אינו בטל כלל.","נאמר עוד באותה משנה: אם \u0003דרסה בעגול ואינו יודע באיזה עגול דרסה\u0004 — \u0003דברי הכל יעלו\u0004 (יתבטלו) הקציעות האסורות. על פסקה זו תוהים: \u0003דברי הכל?! היינו פלוגתייהו\u0004 \u0005[הרי זו היא מחלוקתם]\u0006 אם בטלה הליטרא או אינה בטלה!","\u0003אמר רב פפא: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין: \u0003דרסה בעגול\u0004 אבל \u0003אינו יודע באיזה מקום\u0004 ב\u0003עגול,\u0004 כלומר: באיזה צד שלו \u0003דרסה, אי\u0004 \u0005[אם]\u0006 \u0003לצפונה אי\u0004 \u0005[אם]\u0006 \u0003לדרומה\u0004 ואז אין קביעות מקום מסויים לאיסור, ואף ליטרת האיסור אינה יכולה להיות עוד ניכרת לעצמה — הרי במקרה זה בודאי אינה עוד דבר חשוב, ול\u0003דברי הכל יעלו\u0004 \u0005[יתבטלו].\u0006 עד כאן להסבר הברייתא מדוע ביצה (שהיא כפי פירוש זה ביצת טריפה) אינה בטילה אפילו באלף.","אולם \u0003רב אשי אמר: לעולם\u0004 אפשר לפרש כפשוטה של הברייתא שמדובר כאן ב\u0003ספק יום טוב ספק חול,\u0004 ומה שהקשו שהרי לרוב הדיעות אין זה אלא איסור מדברי סופרים, ומדוע אין ספיקו מותר כשאר ספק שמדברי סופרים? יש לומר כי כיון ש\u0003הוי\u0004 \u0005[שהוא]\u0006 \u0003דבר שיש לו מתירין,\u0004 הרי ב\u0003כל דבר שיש לו מתירין אפילו בדרבנן\u0004 \u0005[בדברי סופרים]\u0006 \u0003לא בטיל\u0004 \u0005[איננו בטל],\u0006 ושוב אין מקום לקושיה.","\u0003תניא\u0004 \u0005[שנויה\u0006 תוספתא\u0005],\u0006 \u0003אחרים אומרים משום ר' אליעזר: ביצה\u0004 שנולדה ביום טוב — \u0003תאכל היא ואמה.\u0004 ותוהים: \u0003במאי עסקינן\u0004 \u0005[במה,\u0006 באיזה מקרה, \u0005אנו עוסקים]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי \u0003בתרנגולת העומדת לאכילה\u0004 עוסקים אנו — אם כן \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר ש\u0003היא ואמה שריא\u0004 \u0005[מותרות]!\u0006 \u0003אלא\u0004 אם תאמר כי עוסקים אנו \u0003בתרנגולת העומדת לגדל ביצים\u0004 — הלא \u0003היא ואמה אסורה! אמר ר' זירא,\u0004 כך יש להבין: \u0003תאכל\u0004 הביצה \u0003אגב אמה\u0004 שאם אמה (התרנגולת) נאכלת — אף היא תיאכל.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הדבר],\u0006 מתי צריך לסמוך על סימן זה? \u0003אמר אביי:\u0004 מדובר כאן \u0003כגון שלקחה\u0004 (קנאה) אדם לתרנגולת זו \u0003סתם,\u0004 שלא פירש מה כוונתו לעשות בה, אם לביצים או לבשר, ובאופן כזה, אם \u0003נשחטה\u0004 התרנגולת ביום טוב — \u0003הובררה\u0004 ש\u0003לאכילה\u0004 היא \u0003עומדת,\u0004 וכיון שכך — גם הביצים שהטילה מותרות, \u0003לא נשחטה\u0004 — הרי \u0003הובררה\u0004 ש\u0003לגדל ביצים\u0004 היא \u0003עומדת,\u0004 ולכן הביצה שהטילה אסורה.","\u0003רב מרי אמר:\u0004 לשון זו \"תיאכל היא ואמה\" אין להבינה כפשוטה, אלא כלשון \u0003גוזמא\u0004 \u0005[הפרזה\u0006 והדגשה\u0005]\u0006 \u0003קתני\u0004 \u0005[שנה].\u0006 וראיה לדבר ממה \u0003דתניא\u0004 \u0005[ששנינו\u0006 בתוספתא\u0005]\u0006 באותו ענין, \u0003אחרים אומרים משום ר' אליעזר: ביצה תאכל היא ואמה, ואפרוח וקליפתו.\u0004","ונברר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003קליפתו? אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה ל\u0003קליפה ממש,\u0004 וכי \u0003קליפה בת אכילה היא? אלא\u0004 עליך לומר שהכוונה היא לאכול \u0003אפרוח\u0004 בעודו \u0003בקליפתו,\u0004 ויש לתמוה ולהקשות על פירוש זה: \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי רבנן עליה\u0004 \u0005[חלוקים חכמים עליו]\u0006 על \u0003ר' אליעזר בן יעקב\u0004 והתירו אפרוח באכילה מיד כשנולד, \u0003אלא היכא\u0004 \u0005[היכן]\u0006 ש\u0003יצא\u0004 כבר \u0003לאויר העולם,\u0004 שלדעתם מיד כשנולד מותר לאוכלו ואין צורך להמתין לו עוד. \u0003אבל היכא\u0004 \u0005[היכן]\u0006 שעדיין \u0003לא יצא לאויר העולם\u0004 — \u0003לא פליגי\u0004 \u0005[אינם חלוקים]\u0006 ומודים שאפרוח כזה אסור באכילה, ואינו אלא כשרץ.","\u0003אלא\u0004 ודאי, הביטוי \u0003אפרוח וקליפתו,\u0004 אין להבינו כפשוטו אלא כלשון \u0003גוזמא\u0004 \u0005[הפרזה],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לשון זו שאמר \u0003\"תאכל היא ואמה\"\u0004 — לשון \u0003גוזמא\u0004 \u0005[הפרזה]\u0006 היא ואין הכוונה לומר כי תיאכל היא ואמה ממש, אלא רק להדגיש שהביצה מותרת בלי ספק.","\u0003אתמר\u0004 \u0005[נאמר],\u0006 אם היו \u0003שבת ויום טוב\u0004 סמוכים זה לזה, \u0003רב אמר:\u0004 ביצה ש\u0003נולדה בזה\u0004 — \u0003אסורה בזה, ור' יוחנן אמר: נולדה בזה\u0004 — \u0003מותרת בזה.\u0004 ושואלים: \u0003נימא קסבר\u0004 \u0005[\u0006האם \u0005לומר שסבר]\u0006 \u0003רב: קדושה אחת היא,\u0004 כלומר, שיום טוב ושבת הסמוכים זה לזה נחשבים כרצף אחד של קדושה וכיום אחד ארוך שאין לחלק ביניהם?","\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב: הלכה כארבעה זקנים\u0004 (חכמים) שאמרו \u0003אליבא\u0004 \u0005[על דעתו]\u0006 של \u0003ר' אליעזר,\u0004 ש\u0003אמר: שתי קדושות הן\u0004 ששבת ויום טוב אינם נחשבים כהמשך אחד, ולכך הותר לערב באחד מהם לצורך משנהו ואין צריך לעשות כן דווקא ביום חול. ואם כן, אי אפשר לפרש את המחלוקת על בסיס זה.","\u0003אלא הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004איסור \u0003הכנה\u0004 בידי שמים מיום קדוש אחד למשנהו, שלדעת \u0003רבה\u0004 אסורה, \u0003קמפלגי\u0004 \u0005[חלוקים הם].\u0006 \u0003רב אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 את איסור \u0003הכנה\u0004 של \u0003רבה ו\u0004אילו \u0003ר' יוחנן לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 איסור \u0003הכנה\u0004 של \u0003רבה.\u0004","ומעירים: \u0003כתנאי\u0004 \u0005[כתנאים]\u0006 שכבר נחלקו בבעיה זו: \u0003נולדה\u0004 הביצה \u0003בשבת\u0004 — \u0003תאכל ביום טוב,\u0004 נולדה \u0003ביום טוב\u0004 — \u0003תאכל בשבת. ר' יהודה אומר משום ר' אליעזר:\u0004 אין הדבר לדעת הכל, אלא \u0003עדיין היא מחלוקת, שבית שמאי אומרים: תאכל, ובית הלל אומרים: לא תאכל,\u0004 כשם שנחלקו בענין היתר אכילה לבו ביום.","מסופר: \u0003אושפיזכניה\u0004 \u0005[מארחו]\u0006 של \u0003רב אדא בר אהבה הוו ליה הנך\u0004 \u0005[היו לו אותם]\u0006 \u0003ביצים\u0004 שנולדו ביום טוב הסמוך לשבת ונסתפק למארח בענין היתר אכילתה \u0003מיום טוב לשבת\u0004 הסמוכה לו. \u0003אתא לקמיה\u0004 \u0005[בא לפניו]\u0006 לפני אורחו רב אדא, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי לאטווינהו האידנא\u0004 \u0005[האם מותר\u0006 לטלטל את הביצים הללו כדי \u0005לצלותן\u0006 \u0005עכשיו]\u0006 ביום טוב (אף כי לא יאכלו אותן, בשל איסור ביצה שנולדה) \u0003וניכלינהו\u0004 \u0005[ונאכל אותם]\u0006 \u0003למחר,\u0004 שהרי מחר בודאי תהיינה מותרות באכילה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אדא: \u0003מאי דעתיך\u0004 \u0005[מה היתה דעתך]\u0006 בשאלה זו, שהיה ברור לך כי במחלוקת \u0003רב ור' יוחנן\u0004 — \u0003הלכה כר' יוחנן,\u0004 והנולד ביום זה מותר בשני. אולם, \u0003אפילו ר' יוחנן לא קא שרי\u0004 \u0005[התיר]\u0006 \u0003אלא לגומעה למחר\u0004 בעודנה חיה, משום שאז אין בה עוד איסור, \u0003אבל ביומיה\u0004 \u0005[בו ביום]\u0006 \u0003לא\u0004 התיר אפילו לטלטלה, וכל שכן לצלותה.","\u0003והתניא\u0004 \u0005[ו\u0006אכן \u0005כן שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחת ביצה שנולדה בשבת ואחת ביצה שנולדה ביום טוב\u0004 — \u0003אין מטלטלין אותה לא לכסות בה את הכלי, ולא לסמוך בה את כרעי המטה.\u0004","כיוצא בזה מסופר: \u0003אושפיזכניה\u0004 \u0005[מארחו]\u0006 של \u0003רב פפא, ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003ההוא גברא דאתא לקמיה\u0004 \u0005[אדם אחד שבא לפני]\u0006 \u0003רב פפא\u0004 לשאול. \u0003הוו ליה הנך\u0004 \u0005[היו לו אותם]\u0006 \u0003ביצים\u0004 שנולדו ב\u0003שבת\u0004 הסמוכה \u0003ליום טוב. אתא לקמיה\u0004 \u0005[בא לפניו]\u0006 לשאול. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מהו למכלינהו\u0004 \u0005[האם\u0006 מותר \u0005לאכול]\u0006 את הביצים הללו \u0003למחר\u0004 בחג? \u0003אמר ליה: זיל האידנא\u0004 \u0005[לך עכשיו,\u0006 היום\u0005]\u0006 ממני \u0003ותא\u0004 \u0005[ובוא]\u0006 \u0003למחר,\u0004 כי \u0003רב לא\u0004 היה \u0003מוקי אמורא עלויה\u0004 \u0005[מעמיד מתורגמן לפניו]\u0006 שיתרגם את דברי דרשתו \u0003מיומא טבא לחבריה\u0004 \u0005[מיום טוב עד חבירו]\u0006 \u0003משום שכרות.\u0004 שבתוך סעודת יום טוב נהגו לשתות יין הרבה, וחשש שמא אין דעתו צלולה למדי כדי לפסוק הלכה לרבים, ואף אני כן.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 אותו אדם \u0003למחר\u0004 לשאול \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב פפא:"],["\u0003איכו השתא\u0004 \u0005[אילו\u0006 הייתי מורה לך \u0005אז],\u0006 \u0003אשתלאי\u0004 \u0005[הייתי שוכח]\u0006 \u0003ואמרי לך\u0004 \u0005[והייתי אומר לך]\u0006 על סמך הכלל המקובל: \u0003רב ור' יוחנן\u0004 — \u0003הלכה כר' יוחנן,\u0004 והייתי מתיר לך. אולם \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר רבא: הלכתא כותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003רב בהני תלת\u0004 \u0005[בשלושה\u0006 דברים \u0005אלה],\u0006 שאמר לענין קדושת ימים טובים שונים ושבת \u0003בין לקולא\u0004 \u0005[להקל]\u0006 \u0003בין לחומרא\u0004 \u0005[להחמיר],\u0006 ואף בזה הלכה למעשה כדעת רב.","\u0003אמר ר' יוחנן: עצים שנשרו מן הדקל בשבת\u0004 — \u0003אסור להסיקן ביום טוב\u0004 שחל להיות אחר השבת. \u0003ואל תשיבני ביצה,\u0004 כלומר, אל תדחה את דברי ותקשה מדוע בביצה מתיר אני לאוכלה למחרת, ו\u0003מאי טעמא\u0004 \u0005[מה\u0006 אכן \u0005טעם\u0006 ההבדל\u0005]?\u0006 \u0003ביצה משום דביומא נמי חזי\u0004 \u0005[ביום\u0006 השבת \u0005עצמו גם כן ראויה היא]\u0006 \u0003לגומעה,\u0004 אילולי נולדה בשבת, \u0003ולא קא שרי לה\u0004 \u0005[ואינו מתיר אותה]\u0006 \u0003עד למחר,\u0004 הרי \u0003מידע ידיע\u0004 \u0005[ידוע]\u0006 אז לאנשים שביצה בת \u0003בת יומא אסורה,\u0004 אולם \u0003עצים דלא חזו ליומייהו\u0004 \u0005[שאינם ראויים ביומם]\u0006 ביום השבת להדלקה, ואם כן, \u0003אי שרי להו\u0004 \u0005[אם יתיר אותם]\u0006 \u0003למחר\u0004 — \u0003אתי למימר\u0004 \u0005[יבוא לומר]:\u0006 \u0003ביומייהו נמי שרו\u0004 \u0005[\u0006ש\u0005ביומם,\u0006 ביום הראשון \u0005גם כן\u0006 \u0005מותרים]\u0006 \u0003ואתמול משום שבת הוא\u0004 שלא השתמשו בהם משום \u0003דלא חזו\u0004 \u0005[שאינם ראויים]\u0006 \u0003להסקה\u0004 משום שאסור להעלות אש בשבת.","\u0003אמר רב מתנה: עצים שנשרו מן הדקל\u0004 ישר \u0003לתוך התנור ביום טוב\u0004 — \u0003מרבה עליהם עצים מוכנים\u0004 שהוכנו מבעוד יום, שמותר להסיק בהם \u0003ומסיקן\u0004 כולם יחד. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 כשמטפל בעצים \u0003קא\u0004 \u0005[הוא]\u0006 \u0003מהפך\u0004 ומנער את העצים \u0003באיסורא\u0004 \u0005[האסורים]!\u0006 ומשיבים: \u0003כיון דרובא דהיתרא נינהו\u0004 \u0005[שרוב\u0006 העצים \u0005של היתר הם],\u0006 \u0003כי קא\u0004 \u0005[כאשר הוא]\u0006 \u0003מהפך — בהיתרא קא\u0004 \u0005[בהיתר הוא]\u0006 \u0003מהפך,\u0004 ובטל האיסור ברוב.","ומקשים: \u0003והא קא\u0004 \u0005[והרי הוא\u0006 נמצא\u0005]\u0006 כ\u0003מבטל איסורא\u0004 \u0005[איסור]\u0006 \u0003לכתחלה,\u0004 שהרי העצים שנפלו לתנור אסורים, והוא מוסיף עליהם עצים מותרים כדי שיתבטלו, \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003אין מבטלין איסור לכתחלה!\u0004 ומשיבים, \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאין מבטלים, נאמרו דווקא \u0003בדאורייתא\u0004 \u0005[\u0006בדברים האסורים \u0005מן התורה]\u0006 \u0003אבל ב\u0004דברים האסורים מ\u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 וכגון במקרה זה שהוא איסור מוקצה ואינו אסור אלא מדבריהם — \u0003מבטלין.\u0004","ושואלים: \u0003ול\u0004דעת \u0003רב אשי\u0004 ש\u0003אמר: כל דבר שיש לו מתירין\u0004 באופן כלשהו לאחר זמן, \u0003אפילו\u0004 אם הוא \u0003בדרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003לא בטיל\u0004 \u0005[אינו בטל],\u0006 אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי משעבר החג מותרים העצים הללו בהסקה! ומשיבים: \u0003הני מילי היכא דאיתיה לאיסורא בעיניה\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005במקום שישנו האיסור בעינו],\u0006 אבל \u0003הכא\u0004 \u0005[כאן]\u0006 הרי \u0003מקלא קלי איסורא\u0004 \u0005[נשרף האיסור],\u0006 שהרי מתי מהפכים בעצים — בזמן שכבר נשרף גופם והפכו להיות גחלים, ונמצא שלא עשה מעשה באיסור כלל.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בענין \u0003שני ימים טובים של גליות\u0004 כיצד דנים בהם לענין זה? \u0003רב אמר:\u0004 ביצה ש\u0003נולדה בזה\u0004 — \u0003מותרת בזה, ורב אסי אמר: נולדה בזה\u0004 — \u0003אסורה בזה.\u0004","ושואלים: \u0003לימא קסבר\u0004 \u0005[האם לומר שסבר]\u0006 \u0003רב אסי\u0004 כי \u0003קדושה אחת היא\u0004 בשני הימים? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב אסי\u0004 עצמו היה \u0003מבדיל מיומא טבא לחבריה\u0004 \u0005[מיום טוב\u0006 אחד של גלויות \u0005לחבירו]!\u0006 הרי שהיה סבור שיום ראשון הוא לבדו יום טוב באמת, והיום השני דינו כחול ולא נהגו בדורות מוקדמים לעשות יום טוב שני של גלויות אלא מפני שלא היו בקיאים בקביעות החודש, אבל אנו שבקיאים בחשבונות הללו, אין לנו לעשות יום טוב שני של גלויות, אלא משום מנהג אבות!","ומשיבים: \u0003רב אסי ספוקי מספקא ליה\u0004 \u0005[מסופק היה לו]\u0006 אם מה שקבעו חכמים שיש לקדש אף את היום השני כחג, קבעו כן אף לדורות ואפילו לכשיידעו ויבינו בקביעות ראשי החודשים, או שמא לא קבעו כן אלא מחמת ספק היום ולפי זה היום השני הוא אכן חול גמור, ולכך \u0003עביד הכא\u0004 \u0005[היה עושה כאן]\u0006 \u0003לחומרא והכא\u0004 \u0005[וכאן]\u0006 \u0003לחומרא.\u0004","\u0003אמר ר' זירא: כותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003רב אסי מסתברא\u0004 \u0005[מסתבר]\u0006 לומר, ששני הימים החשיבום חכמים כיחידה אחת ולא מחמת הספק, \u0003דהאידנא ידעינן בקביעא דירחא\u0004 \u0005[שהרי עכשיו יודעים אנו קביעות החודש]\u0006 משום שנמסר לוח שנה מסודר הגלוי לכל ישראל וידועים התאריכים בדיוק, ואף על פי כן \u0003קא עבדינן תרי יומי\u0004 \u0005[עושים אנו\u0006 עדיין \u0005שני ימים\u0006 טובים של גלויות\u0005]\u0006 משמע שאין אנו חושבים את שני הימים כספק אלא רואים את הכל כתקנה של הארכת החג ביום נוסף.","\u0003אמר אביי:\u0004 להיפך, \u0003כותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003רב מסתברא\u0004 \u0005[מסתבר\u0006 לומר\u0005],\u0006 שלא קבעו חכמים לנהוג יום טוב גם בשני אלא מחמת הספק, \u0003דתנן\u0004 \u0005[שכן שנינו\u0006 במשנה\u0005]:\u0006 \u0003בראשונה,\u0004 לאחר שקידשו בית דין את החודש, \u0003היו משיאין משואות\u0004 (מדליקים מדורות) בראשי ההרים מהר להר עד לגולה לסימן שנתקדש החודש. \u0003משקלקלו הכותים\u0004 (השומרונים) והיו מדליקים משואות שלא בזמנם כדי לבלבל את ישראל, \u0003התקינו שיהו שלוחין יוצאין\u0004 לגולה ומודיעים על קביעות החודש, וכיון שלא יכלו השליחים להגיע לכל מקום בגולה עד החג, לכך תיקנו מספק יום טוב נוסף.","ואם כן \u0003ואילו בטלו\u0004 ה\u0003כותים\u0004 ואינם מפריעים עוד, היו חוזרים לנוהג ראשון ו\u0003עבדינן חד יומא\u0004 \u0005[היינו עושים רק יום אחד\u0006 בלבד\u0005]\u0006 וכן \u0003והיכא דמטו\u0004 \u0005[ובמקום שבאו]\u0006 ה\u0003שלוחין\u0004 מירושלים בזמנם, גם כן \u0003עבדינן חד יומא\u0004 \u0005[היינו עושים\u0006 רק \u0005יום\u0006 טוב \u0005אחד]\u0006 ולא שנים.","ושואלים: אם כן, \u0003והשתא דידעינן בקביעא דירחא מאי טעמא עבדינן תרי יומי\u0004 \u0005[ועכשיו שיודעים אנו בקביעות החודש, מה טעם עושים אנו שני ימים\u0006 טובים של גלויות\u0005]?\u0006 \u0003משום\u0004 ש\u0003שלחו מתם\u0004 \u0005[משם,\u0006 מארץ ישראל\u0005],\u0006 למרות שקבעו את ראשי החדשים לפי לוח מסודר ואין עוד ספק, מכל מקום \u0003הזהרו במנהג אבותיכם בידיכם\u0004 והמשיכו לנהוג בו, כי \u0003זמנין דגזרו שמדא ואתי לאקלקולי\u0004 \u0005[פעמים שתגזור המלכות גזירת\u0006 \u0005שמד\u0006 ותתמעט התורה וישתכח הלוח הקבוע \u0005ויבואו להתקלקל]\u0006 מחדש, על כן שמרו על מנהג האבות. אבל לעיקר הדין ששני ימים טובים נוהגים עתה בהם, הוא רק מחמת ספק וחשש.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בבעיה דומה לזו, ביחס \u0003לשני ימים טובים של ראש השנה. רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 ביצה ש\u0003נולדה בזה\u0004 — \u0003אסורה בזה\u0004 כי שני ימים טובים של ראש השנה יש בהם דין מיוחד, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003בראשונה היו מקבלין עדות החדש,\u0004 כלומר, את עדות העדים שראו את מולד הירח, וקובעים לפי עדותם את ראש החודש וכן נהגו גם לגבי ראש השנה, שהוא ראש חודש תשרי, והיו מקבלים עדות זו \u0003כל היום\u0004 השלושים של חודש אלול \u0003כולו. פעם אחת נשתהו העדים לבא\u0004 עד לשעה מאוחרת."],["\u0003ונתקלקלו הלוים בשיר\u0004 שלא ידעו איזה שיר עליהם לשיר בעת הקרבת תמיד של בין הערבים, אם של חול אם של ראש השנה, שהרי לא היה ברור אם יבואו עדים היום או לא, ומאז \u0003התקינו שלא יהו מקבלים את העדים\u0004 לדיון ולקבוע שראש השנה הוא \u0003אלא עד\u0004 שעת \u0003המנחה\u0004 שהיא שעת הקרבת תמיד של בין הערבים, ועיברו את חודש אלול והיו מחשבים את חשבון קביעות המועדים מיום המחרת,","\u0003ואם באו עדים מן המנחה ולמעלה\u0004 (והלאה), אף על פי שלא עשו את חשבון קביעות המועדים אלא מלמחרת, בכל זאת היו \u0003נוהגין אותו היום\u0004 שבאו בו העדים \u0003קדש\u0004 שהרי סוף סוף ראש חודש הוא, וגם \u0003למחר\u0004 נהגו \u0003קדש,\u0004 שבו היו נוהגים את דיני ראש השנה לגבי הקרבת קרבנות וקביעת שאר המועדים. ואם כן רואים שהנהגת שני ימים טובים בראש השנה לא נעשתה מחמת ספק של גלויות, אלא חכמים תיקנו ששני הימים של ראש השנה יהיו כיחידה אחת, מפני הקושי המהותי שבקביעת ראש השנה.","\u0003אמר רבה: מ\u0004זמן \u0003תקנת רבן יוחנן בן זכאי ואילך, ביצה\u0004 שנולדה בזה — \u0003מותרת\u0004 בזה. ומה עניינה של תקנה זו — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003משחרב בית המקדש, התקין רבן יוחנן בן זכאי שיהו\u0004 חוזרים ו\u0003מקבלין עדות החדש כל היום,\u0004 שהרי שוב אין לחשוש לקלקול השיר והקרבנות במקדש, ואפשר לחזור למנהג העתיק. ולפי תקנה זו, בית הדין שידעו בקביעות החודש מתוך עדות העדים אכן לא קיימו שני ימי ראש השנה, והרחוקים שקיימו כן, הוא רק מתוך הספק ואחד מהם ודאי חול, ולכך ביצה שנולדה בראשון מותרת בשני.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא\u0004 \u0005[והרי]\u0006 \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003ביצה אסורה! אמר ליה\u0004 \u0005[לו]\u0006 רבה: מה מקום לקושיה זו? \u0003אמינא לך אנא\u0004 \u0005[אומר אני לך]\u0006 דבר בשם גדול שבתנאים \u0003רבן יוחנן בן זכאי, ואת אמרת לי\u0004 \u0005[ואתה אומר לי\u0006 מדברי\u0005]\u0006 \u0003רב ושמואל\u0004 האמוראים\u0005]?!\u0006","ושואלים: \u0003ולרב ושמואל\u0004 הלא \u0003קשיא מתניתין\u0004 \u0005[קשה משנתנו],\u0006 שהרי לפי המשנה התבטל כבר דינו המיוחד של ראש השנה! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003הא לן\u0004 \u0005[זו לנו]\u0006 לבני חוץ לארץ שלא שינו את מנהגם ועושים שני ימים טובים, הרי נשאר אצלם מנהג הקדמונים בתוקפו, וראש השנה דינו עדיין כיום אחד וקדושה אחת ארוכה, \u0003והא להו\u0004 \u0005[וזה להם]\u0006 לבני ארץ ישראל, כיון שביטל רבן יוחנן בן זכאי את המנהג לעשות את ראש השנה יומיים, הרי מאז שתי קדושות הן, גם אם נוהגים ראש השנה שני ימים טובים.","\u0003ורב יוסף אמר: אף מתקנת רבן יוחנן בן זכאי ואילך ביצה אסורה,\u0004 שדבר זה לא הותר כלל. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של רב יוסף — משום שאיסור הביצה בראש השנה \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003דבר שבמנין\u0004 כלומר, דבר שנקבע על פי מנין והצבעת הסנהדרין בזמנו, לאחר שלא הגיעו עדים בזמנם לפני המנחה, \u0003וכל דבר שבמנין צריך מנין אחר להתירו,\u0004 שיש צורך בהצבעה אחרת להתיר אותו במפורש, ואיננו מותר מיד כאשר התבטל הטעם לתקנה ראשונה.","\u0003אמר רב יוסף: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 את דעתי זו, שאף שטעם האיסור בטל, כיון שאסרוהו על פי מנין — האיסור עצמו לא בטל עד שיבטלוהו במפורש במנין חדש — \u0003דכתיב\u0004 \u0005[\u0006לפי \u0005שנאמר]:\u0006 \u0003\"לך אמר להם שובו לכם לאהליכם\"\u0004 (דברים ה, כז), כלומר: לנשיכם. \u0003ואומר: \"במשך היבל המה יעלו בהר\"\u0004 (שמות יט, יג). ונאמר עוד: \"היו נכונים לשלושת ימים אל תגשו אל אשה\" (שמות יט, טו). כלומר, אף שהאיסור מראשיתו היה רק מטעם מסויים, מכל מקום היה צורך גם להתירו במפורש, ולא די בכך שטעם האיסור התבטל.","\u0003ו\u0004כן \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 שבה מובע רעיון זה: \u0003כרם רבעי,\u0004 פירות השנה הרביעית של כל נטיעה דינם כדין מעשר שני, ולכן \u0003היה\u0004 בעליהם \u0003עולה לירושלים\u0004 ושם היה אוכלם. ואם אינו יכול להביאם מפני רוחק הדרך או כובד המשא — פודה אותם בכסף במקומם, ומחלל את דמיהם בירושלים על פירות אחרים. אבל תיקנו שאת הפירות שבסביבות ירושלים לא היו פודים, אלא הביאו את פירות הכרם עצמם, וסביבות ירושלים נקבעו בתחום של \u0003מהלך יום אחד לכל צד. וזו היא תחומה: עלת מן הצפון, ועקרבת מן הדרום, לוד מן המערב, וירדן מן המזרח.\u0004","\u0003ואמר עולא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רבה בר בר חנה אמר ר' יוחנן: מה טעם\u0004 קבעו תקנה זו — \u0003כדי לעטר\u0004 את \u0003שוקי ירושלים בפירות,\u0004 שעל ידי תקנה זו נמצאים תמיד בירושלים פירות רבים מוכנים לאכילה.","\u0003ותניא\u0004 \u0005[ושנינו\u0006 עוד בברייתא\u0005]:\u0006 \u0003כרם רבעי היה לו לר' אליעזר\u0004 בן הורקנוס, תלמידו של רבן יוחנן בן זכאי, בין לוד לירושלים, \u0003במזרחה\u0004 של \u0003לוד בצד כפר טבי,\u0004 והיה איפוא בתוך תחום ירושלים לענין זה."],["\u0003ובקש להפקירו לעניים\u0004 שלהם יהא כדאי לטרוח ולהעלות את הפירות לירושלים ולאוכלם שם. \u0003אמרו לו תלמידיו: רבי\u0004 אין אתה צריך לכך, כי \u0003כבר נמנו עליך חבריך והתירוהו\u0004 שכבר נמנו חברי הסנהדרין בענין זה, והתירו לפדות כרם רבעי ולהעלות את דמיו לירושלים אפילו בסמוך לירושלים, משום שאחר חורבן הבית אין עוד טעם לתקנה זו, שהרי מאחר שחרבה שוב אין סיבה לעטר את שווקיה. ומסבירים: \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003חבריך\u0004 אלה — הרי זה כינוי ל\u0003רבן יוחנן בן זכאי.\u0004","ונדקדק בלשון הברייתא: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003נמנו,\u0004 כלומר, שהצביעו במפורש על כך, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא נמנו\u0004 — \u0003לא\u0004 שאף שבטל הטעם אין התקנה בטלה מאליה, ויש צורך שתבוטל בהחלטה מפורשת. ואף כאן, איסור הביצה שנולדה לא בטל שהרי לא הותר במפורש.","לפני שבאים לדון בענין לגופו, רוצים לברר תחילה את דברי רב יוסף, שהביא שני פסוקים להוכיח עקרון זה מן התורה, ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 טעם\u0005]\u0006 \u0003\"ואומר\"\u0004 למה מביא הוא גם פסוק שני, ולא הסתפק בראיה מן הכתוב הראשון? ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 \u0003מכדי כתיב\u0004 \u0005[הלא נאמר]\u0006 \u0003\"היו נכנים לשלשת ימים אל תגשו אל אשה\"\u0004 (שמות יט, טו), אם כן הכתוב \u0003\"לך אמר להם שובו לכם לאהליכם\"\u0004 (דברים ה, כז) \u0003למה לי,\u0004 למה צריך אותו? הלא אחרי שלושה ימים יתבטל האיסור מעצמו! \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003כל דבר שבמנין\u0004 — \u0003צריך מנין אחר להתירו.\u0004","אולם, \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ותפרש אחרת שהציווי \"שובו לכם לאהליכם\" לא נאמר כדי להתיר לאנשים לחזור הביתה לנשיהם, אלא \u0003למצות עונה הוא דאתא\u0004 \u0005[שבא],\u0006 שהיתה כאן מצווה מיוחדת חדשה לישראל שיפקדו את נשיהם כדי לקיים מצות עונה. על כן, כדי להוציא מדיעה זו, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראיה אחרת, והיא מה שנאמר בפסוק השני: \u0003\"במשך היבל המה יעלו בהר\"\u0004 (שמות יט, יג),","\u0003מכדי כתיב\u0004 \u0005[הלא נאמר]:\u0006 \u0003\"גם הצאן והבקר אל ירעו אל מול ההר ההוא\"\u0004 (לד, ג) ונראה משם שאין האיסור חל אלא כשמתגלה כבוד ה' על ההר, ואחר כך — מותר מיד, אם כן \u0003\"במשך היבל\" למה לי,\u0004 ומה טעם בסימן מיוחד לדבר? \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003דבר שבמנין צריך מנין אחר\u0004 כדי \u0003להתירו.\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003הני מילי בדאורייתא\u0004 \u0005[דברים אלה\u0006 אמורים \u0005בדברי תורה]\u0006 שאין להם היתר אלא אם כן הותרו במפורש, \u0003אבל בדרבנן\u0004 \u0005[בדברי סופרים]\u0006 \u0003לא\u0004 — \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 מן הברייתא לענין \u0003כרם רבעי, והא\u0004 \u0005[והרי]\u0006 \u0003כרם רבעי\u0004 תקנה זו שיעלו את פירותיו ולא יחללום \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 היא, \u0003ו\u0004בכל זאת \u0003קאמרי ליה\u0004 \u0005[ואמרו לו]\u0006 לר' אליעזר: \u0003כבר נמנו עליך חבריך והתירוהו.\u0004 משמע, שבלא מנין לא היתה מותרת.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 על איסור \u0003ביצה נמי אמנו עלה\u0004 \u0005[גם כן נמנו עליו]\u0006 \u0003רבן יוחנן בן זכאי ושריוה\u0004 \u0005[והתירוה]\u0006 ומשיבים: \u0003כי אמנו\u0004 \u0005[כאשר נמנו]\u0006 — לענין \u0003עדות\u0004 נמנו, אולם לבטל את דיני \u0003ביצה לא אמנו\u0004 \u0005[נמנו].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003ביצה במנין מי הואי\u0004 \u0005[האם היתה]\u0006 אסורה? וכי עשו הצבעה מיוחדת כדי לאסור ביצה שנולדה ביום טוב של ראש השנה? הלא \u0003ביצה בעדות תליא מלתא\u0004 \u0005[תלוי הדבר];\u0006 כאשר \u0003אתסר\u0004 \u0005[נאסרה]\u0006 ה\u0003עדות\u0004 שלאחר הצהרים — ממילא \u0003אתסר\u0004 \u0005[נאסרה]\u0006 גם אכילת ה\u0003ביצה\u0004 שנולדה בראש השנה, וכאשר \u0003אשתרי\u0004 \u0005[הותרה]\u0006 \u0003עדות\u0004 זו — ממילא \u0003אשתרי\u0004 \u0005[הותרה]\u0006 גם אכילת ה\u0003ביצה,\u0004 ואין מקום לדברי רב יוסף.","\u0003רב אדא ורב שלמן תרוייהו\u0004 \u0005[שניהם]\u0006 \u0003מ\u0004המקום הנקרא \u0003בי כלוחית אמרי\u0004 \u0005[אמרו]:\u0006 \u0003אף מתקנת רבן יוחנן בן זכאי ואילך ביצה אסורה, מאי טעמא\u0004 \u0005[מה הטעם]\u0006 — \u0003מהרה יבנה בית המקדש\u0004 ותחזור התקנה שאין מקבלים עדות העדים אלא עד המנחה, \u0003ויאמרו\u0004 האנשים: \u0003אשתקד\u0004 \u0005[בשנה שעברה]\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא אכלנו ביצה\u0004 שנולדה ביום טוב הראשון של ראש השנה, למחרת \u0003ביום טוב שני\u0004 של ראש השנה? \u0003השתא נמי ניכול\u0004 \u0005[עכשיו גם כן נאכל]\u0006 כמו בשנה שעברה. \u0003ולא ידעי\u0004 \u0005[ואין הם יודעים]\u0006 שיש הבדל גדול בהלכה, משום \u0003דאשתקד\u0004 \u0005[שבשנה שעברה]\u0006 \u0003שתי קדושות הן, והשתא\u0004 \u0005[ועכשיו]\u0006 \u0003קדושה אחת\u0004 ארוכה \u0003היא.\u0004","ומקשים: אם לכך אנו חוששים, \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003עדות נמי\u0004 \u0005[גם כן]\u0006 \u0003לא נקבל\u0004 בזמן הזה, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 — \u0003מהרה יבנה בית המקדש, ויאמרו: אשתקד מי\u0004 \u0005[האם]\u0006 \u0003לא קבלנו עדות החדש כל היום כולו, השתא נמי\u0004 \u0005[עכשיו גם כן]\u0006 \u0003נקבל\u0004 עדות העדים אפילו לאחר זמן המנחה!","את הקושיה הזו דוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 לענין עדות הלא \u0003עדות מסורה לבית דין,\u0004 ובית דין יודעים להבחין בטעמן של תקנות. אבל \u0003ביצה\u0004 הרי \u0003לכל\u0004 היא \u0003מסורה,\u0004 שהרי הדבר נתון בידי כל אדם, ולא כל אחד יבוא לשאול חכם, ויש איפוא מקום לחשוש לטעות.","\u0003רבא אמר: אף מתקנת רבן יוחנן בן זכאי ואילך ביצה אסורה.\u0004 כי \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא מודה רבן יוחנן בן זכאי שאם באו עדים מן המנחה ולמעלה\u0004 אפילו לאחר החורבן \u0003שנוהגין אותו היום קדש ולמחר קדש?\u0004 ולא נשתנה על ידי התקנה אלא שבזמן הבית לא החשיבו כלל את העדות מן היום הראשון, והיו מתחילים למנות את השנה מן היום השני, ואילו בזמנו של רבן יוחנן התחילו למנות מן היום הראשון — אבל לענין קדושת יום טוב נהגו גם ביום השני קודש. ואם כן, כשהיו שני ימי ראש השנה אף בארץ המשיך הדבר להיות קדושה אחת, ולא שנים.","\u0003ואמר רבא\u0004 כסיכום: \u0003הלכתא כותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003רב בהני תלת\u0004 \u0005[בשלוש אלה]\u0006 \u0003בין לקולא בין לחומרא\u0004 \u0005[בין להקל בין להחמיר].\u0006"],["\u0003אמר רבא:\u0004 מי ש\u0003מת ביום טוב ראשון\u0004 — \u0003יתעסקו בו עממים\u0004 (גוים) לקבור אותו. \u0003מת ביום טוב שני\u0004 של גלויות — \u0003יתעסקו בו ישראל, ו\u0004דין זה נוהג \u0003אפילו בשני ימים טובים של ראש השנה, מה שאין כן בביצה,\u0004 שאם נולדה ביום הראשון של ראש השנה — אסורה ביום השני.","\u0003נהרדעי אמרי\u0004 \u0005[\u0006חכמי \u0005נהרדעא היו אומרים]:\u0006 \u0003אף בביצה\u0004 אין ראש השנה שונה משאר שני ימים טובים של גלויות וכשנולדה בראשון — מותרת בשני. ש\u0003מה דעתיך\u0004 \u0005[דעתך],\u0006 כלומר, מה יש לחשוש — \u0003דילמא מעברי ליה\u0004 \u0005[שמא יעברו אותו]\u0006 את חודש \u0003אלול\u0004 ויעשוהו בן שלושים יום, לאחר שנתאחרו העדים לבוא, ומתחילים למנות את ימי השנה החדשה רק מלמחרת, ונמצא שעושים שני ימים יום טוב מלכתחילה, \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003אמר\u0004 על כך \u0003רב חיננא בר כהנא אמר רב: מימות עזרא ואילך לא מצינו\u0004 שיהיה חודש \u0003אלול מעובר,\u0004 כי החכמים דאגו בדרכים שונות שלא יהא צורך לעבר את חודש אלול, וראש השנה יחול תמיד בזמנו.","\u0003אמר מר זוטרא: לא אמרן\u0004 \u0005[אמרנו]\u0006 שישראל יטפלו במת ביום טוב שני של ראש השנה, \u0003אלא דאשתהי\u0004 \u0005[ש\u0006כבר \u0005נשתהה]\u0006 המת מיום טוב ראשון מטעם כלשהו ולא קברוהו, ויש חשש שמא יסריח וצריך לדאוג לכבוד המת. \u0003אבל\u0004 אם \u0003לא אשתהי\u0004 \u0005[נשתהה]\u0006 ואין חשש לכבודו — אין מתעסקים בקבורתו ביום טוב, אלא \u0003משהינן ליה\u0004 \u0005[משהים אנו אותו]\u0006 עד מוצאי יום טוב, ואז קוברים אותו.","\u0003רב אשי אמר: אף על גב דלא אשתהי, נמי לא משהינן ליה\u0004 \u0005[אף על פי שלא השתהה גם כן אין משהים אותו]\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר, \u0003יום טוב שני לגבי מת\u0004 — \u0003כ\u0004יום \u0003חול שויוה רבנן\u0004 \u0005[עשו אותו חכמים],\u0006 ועד כדי כך \u0003אפילו\u0004 כדי \u0003למיגז ליה\u0004 \u0005[לגזור לו]\u0006 \u0003גלימא\u0004 של תכריכים בו ביום, אף שאיננה מעיקרי צורך הקבורה, או \u0003למיגז ליה אסא\u0004 \u0005[לגזוז,\u0006 לחתוך, \u0005עבורו הדסים]\u0006 שהיו נוהגים להניח על מיטת המת משום כבודו.","\u0003אמר רבינא: והאידנא דאיכא חברי\u0004 \u0005[ועכשיו שיש החברים]\u0006 כהני הפרסים בבבל והם היו מנסים למצוא סיבה להעליל על ישראל, ואם יראו שישראל קוברים מתיהם ביום טוב שני יוכיחו מכאן כי אין זה יום קדוש, ויכריחו אותם לעשות בו מלאכה, על כן \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 ואין אנו קוברים מתים ביום זה.","מסופר: \u0003רבינא הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003רב אשי בשני ימים טובים של ראש השנה\u0004 שחלו באותה שנה ביום חמישי ושישי בשבוע, \u0003חזייה דהוה עציב\u0004 \u0005[ראה אותו\u0006 רבינא \u0005שהוא עצוב],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי עציב מר\u0004 \u0005[מדוע עצוב אדוני]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 ש\u0003לא אותיבי\u0004 \u0005[הנחתי]\u0006 \u0003עירובי תבשילין\u0004 ואין אני יכול להכין תבשיל או להדליק נר בראש השנה עבור השבת העתידה לחול למחרתו.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ולותיב מר האידנא\u0004 \u0005[ושיניח אדוני עכשיו]\u0006 ביום הראשון של ראש השנה, שהוא יום חמישי בשבוע, עירוב תבשילין, \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא אמר רבא: מניח אדם עירובי תבשילין מיום טוב\u0004 אחד של גלויות \u0003לחבירו, ומתנה\u0004 תנאי זה: אם היום הוא חול ולמחרת קודש — יהא זה עירוב, ובשלו אוכל לבשל מחר עבור השבת, ואם היום קודש ומחר חול — הרי בלא זה מותר לבשל מחר מלכתחילה, כשאר ימות החול!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר רבא\u0004 הלכה זו לגבי \u0003שני ימים טובים של גליות סתם, \u0004אולם \u0003בשני ימים טובים של ראש השנה מי\u0004 \u0005[האם]\u0006 \u0003אמר?\u0004 שאין שני ימי ראש השנה אלא כיום אחד ארוך ושניהם קודש.","אמר לו רבינא: \u0003והא אמרי נהרדעי\u0004 \u0005[והרי אומרים חכמי נהרדעא]:\u0006 כי \u0003אף ביצה מותרת\u0004 בשני ימים טובים של ראש השנה, שאין כל הבדל ביניהם לבין יום טוב אחד של גלויות, ואם כן אפשר לנהוג בענין עירוב תבשילין גם כן כך. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי:\u0004 לרבינא, אין זה פותר את הקושי של רב אשי, כי \u0003בפרוש אמר לי מר\u0004 \u0005[אדוני],\u0006 כלומר, רב אשי, \u0003דלא סבר להא דנהרדעי\u0004 \u0005[שאיננו סבור\u0006 \u0005כ\u0006שיטה \u0005זו של\u0006 \u0005חכמי נהרדעא]\u0006 ולכן ראש השנה אינו כשאר ימים טובים, ולא היתה תקנה לעירוב שלא נעשה בזמנו.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה זו: \u0003אפרוח שנולד\u0004 (בבקיעת ביצתו) \u0003ביום טוב, רב אמר: אסור. ושמואל, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יוחנן אמר: מותר.\u0004 ומסבירים את טעמי הדיעות: \u0003רב אמר: אסור\u0004 — \u0003מוקצה הוא. ושמואל ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' יוחנן אמר: מותר\u0004 — \u0003הואיל ומתיר עצמו בשחיטה.\u0004 כלומר, מאחר והיתר שחיטת האפרוח והכשרתו לאכילה היא בלידתו, ומאחר שהלידה מתירה את שחיטתו — הריהי מתירה אותו גם מאיסור מוקצה.","\u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 \u0003רב כהנא ורב אסי לרב: וכי מה בין זה לעגל שנולד ביום טוב?\u0004 שמותר לשחטו בו ביום! \u0003אמר להו\u0004 \u0005[להם]:\u0006 אינו דומה, \u0003הואיל\u0004 והעגל בהיותו בתוך מעי אימו, הריהו \u0003מוכן אגב אמו בשחיטה.\u0004 כי הלכה היא שכאשר שוחטים פרה גם העגל שבתוכה מותר (\"בן פקועה\"), ונמצא שלא חל עליו מעולם איסור מוקצה.","מה שאין כן באפרוח שבביצה, שהרי הביצה היתה מוקצה קודם לכן, והקשו: \u0003ומה בין זה לעגל שנולד מן הטריפה,\u0004 שהרי אם היתה אמו טריפה היתה אסורה באכילה ואגב כך גם העגל שבתוכה, ולאחר שנולד הותר! \u0003שתיק\u0004 \u0005[שתק]\u0006 \u0003רב\u0004 ולא ענה, כמי שאין בידו תשובה.","\u0003אמר רבא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב יוסף: מאי טעמא שתיק\u0004 \u0005[מה טעם שתק]\u0006 \u0003רב?\u0004 הרי יכול היה לענות; \u0003לימא להו\u0004 \u0005[שיאמר להם]:\u0006 אף עגל שנולד מן הטריפה איננו נחשב כמוקצה גמור \u0003הואיל ומוכן אגב אמו לכלבים,\u0004 שהרי אפשר לשחוט את הטריפה ולתת אותה לכלבים לאכילה, ועל כן איננה מוקצה גמור קודם לכן, אבל האפרוח, כל עוד הוא בתוך קליפת הביצה, איננו עומד לאכילת הכלבים ולא היה ראוי איפוא בכניסת החג והריהו מוקצה ולפיכך הריהו נחשב כנולד ואסור!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004"],["\u0003השתא\u0004 \u0005[עכשיו\u0006 הרי\u0005]\u0006 יודעים אנו שדבר ש\u0003מוכן לאדם לא הוי\u0004 \u0005[אינו]\u0006 \u0003מוכן לכלבים\u0004 שדבר שהיה ראוי לאכילת אדם ונפסל אין אומרים שממילא מותר לאכילת כלב, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מחתכין את הדלועין לפני הבהמה\u0004 כדי להקל עליה את האכילה, \u0003ואת הנבלה\u0004 אפילו מתה בו ביום חותכים \u0003לפני הכלבים. ר' יהודה אומר: אם לא היתה\u0004 ה\u0003נבלה\u0004 מתה כבר \u0003מערב שבת,\u0004 שאז היתה מוכנה מבעוד יום לכלבים, אלא מתה בו ביום — \u0003אסורה, לפי שאינה מן המוכן.\u0004 הרי שאף שבהמה זו בחייה היתה ראויה לאכילת אדם, אין אנו אומרים שדבר המוכן לאכילת אדם ממילא נחשב כראוי לכלבים, אלא יש להכין עבורם במיוחד. וכי תוכל אם כן לומר כי דבר ה\u0003מוכן לכלבים הוי\u0004 \u0005[הריהו]\u0006 נחשב \u0003מוכן לאדם?!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן]\u0006 הוא הדבר, ואין לתמוה, כי דבר ה\u0003מוכן\u0004 וראוי \u0003לאדם לא הוי\u0004 \u0005[אינו]\u0006 נחשב כראוי ו\u0003מוכן לכלבים — דמאי דחזי ליה לאיניש\u0004 \u0005[שמה שראוי לאדם]\u0006 \u0003לא שדי ליה\u0004 \u0005[איננו זורק אותו]\u0006 \u0003לכלבים,\u0004 ולכן הקצה בהמה זו מדעתו, אולם דבר \u0003המוכן לכלבים\u0004 נחשב ממילא כראוי ו\u0003מוכן לאדם,\u0004 כיון \u0003דדעתיה דאיניש על כל מידי דחזי ליה\u0004 \u0005[שדעתו של אדם על כל דבר שראוי לו\u0006 לאכילה\u0005]\u0006 ואף שהועידו לכלבים אם נמצא שכשר וראוי הוא לאכילת אדם, לא הוקצה לגמרי מדעתו. ולכן עגל שבמעי אמו, אף שהיא עצמה טריפה, ראוי הוא לכשייוולד ודעתו עליו שכאשר יוולד יאכלנו.","ומעירים לגוף המחלוקת, \u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב, תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003שמואל ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שכשיטתו של \u0003ר' יוחנן.\u0004","ומפרטים: \u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב: עגל שנולד ביום טוב\u0004 — \u0003מותר, אפרוח שנולד ביום טוב\u0004 — \u0003אסור, ומה הפרש בין זה לזה? זה\u0004 העגל \u0003מוכן אגב אמו בשחיטה, וזה\u0004 האפרוח \u0003אינו מוכן אגב אמו.\u0004","\u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003שמואל ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיא שיטת \u0003ר' יוחנן: עגל שנולד ביום טוב\u0004 — \u0003מותר, ואפרוח שנולד ביום טוב — מותר, מאי טעמא\u0004 \u0005[מה טעם]\u0006 — \u0003זה\u0004 העגל \u0003מוכן אגב אמו, וזה\u0004 האפרוח \u0003מתיר עצמו בשחיטה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003אפרוח שנולד ביום טוב\u0004 — \u0003אסור. ר' אליעזר בן יעקב אומר: אף בחול אסור\u0004 האפרוח בו ביום \u0003לפי שלא נתפתחו עיניו,\u0004 ואפרוח קטן כל כך איננו נחשב עדיין כעוף הראוי לאכילה אלא כשרץ.","ומעירים: \u0003כמאן אזלא הא דתניא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת\u0006 ברייתא \u0005זו ששנויה]\u0006 על הכתוב: \u0003\"לכל השרץ השרץ על הארץ\u0004 לא תאכלום כי שקץ הם\" (ויקרא יא, מב), שאמרו: הרי זה \u0003לרבות\u0004 ולכלול באיסור אכילת שרצים, אף את ה\u0003אפרוחים שלא נתפתחו עיניהם. כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי\u0006 הוא\u0005]\u0006 — כשיטת \u0003ר' אליעזר בן יעקב.\u0004","\u0003אמר רב הונא אמר רב: ביצה, עם יציאתה נגמרה\u0004 יצירתה, וכל עוד לא נולדה, עדיין אינה נחשבת כביצה. על כלל זה שאמר רב שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 ולאיזה ענין אמר \u0003עם יציאתה נגמרה? אילימא\u0004 \u0005[אם תאמר]\u0006 שכוונתו היא \u0003עם יציאתה נגמרה\u0004 שרק אז היא קרויה ביצה \u0003ומותרת לאכלה בחלב, הא\u0004 \u0005[הרי]\u0006 שמעת מכאן שביצה כשהיא עדיין \u0003במעי אמה\u0004 לפני שנולדה, אפילו שהיתה גמורה \u0003אסורה לאכלה בחלב? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003השוחט את התרנגולת ומצא בה ביצים גמורות\u0004 — \u0003מותרות לאכלן בחלב!\u0004","\u0003אלא\u0004 יש לפרש את דברי רב כך: \u0003עם יציאתה נגמרה\u0004 — ורק אם יצאה כולה בחול \u0003מותרת לאכלה ביום טוב.\u0004 ותוהים: \u0003הא\u0004 \u0005[הרי]\u0006 תסיק מכאן כי ביצה שנמצאת \u0003במעי אמה אסורה לאכלה ביום טוב? והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003השוחט את התרנגולת ומצא בה ביצים גמורות\u0004 — \u0003מותרות לאכלן ביום טוב!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003בברייתא מאי דלא אשמעינן במתניתין\u0004 \u0005[מה שלא השמיע לנו במשנה],\u0006 שאף שהמשנה לא פירשה דבר זה, פירשה אותו הברייתא, וכיוצא בה אומר רב (תוספות), אולם \u0003הא נמי תנינא\u0004 \u0005[זו גם כן שנינו],\u0006 כלומר, דבר זה אפשר להסיק מן המשנה עצמה, שהרי נאמר \u0003ביצה שנולדה ביום טוב, בית שמאי אומרים: תאכל, ובית הלל אומרים: לא תאכל. ועד כאן לא פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בית שמאי ובית הלל אלא\u0004 בביצה שכבר \u0003נולדה, אבל\u0004 בביצים \u0003במעי אמן — דברי הכל שריין\u0004 \u0005[מותרות].\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ותפרש את המשנה להיפך ש\u0003בית הלל אפילו\u0004 ביצים \u0003במעי אמן נמי אסרי\u0004 \u0005[גם כן אוסרים],\u0006 \u0003והאי דקתני\u0004 \u0005[וזו ששנינו]\u0006 במשנה בלשון \u0003\"נולדה\"\u0004 — \u0003להודיעך כחן של בית שמאי\u0004 ש\u0003אפילו\u0004 בביצה ש\u0003נולדה נמי שרו\u0004 \u0005[גם כן התירו],\u0006 \u0003אלא הא דתניא\u0004 \u0005[\u0006ברייתא \u0005זו ששנינו]:\u0006 \u0003השוחט את התרנגולת ומצא בה ביצים גמורות\u0004 — \u0003מותרות לאכלן ביום טוב,\u0004 אם כן \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי]\u0006 תהא ברייתא זו? \u0003לא בית שמאי ולא בית הלל!\u0004","\u0003אלא\u0004 ודאי אין לומר שרב בא לאסור ביום טוב ביצה שטרם נולדה, ועלינו לפרש את דברי רב כך: ביצה \u0003עם יציאתה נגמרה\u0004 — \u0003ומגדלת אפרוחים,\u0004 כלומר, ביצה שנולדה כדרכה, אפשר להדגיר אותה ולקבל ממנה אפרוח, אולם ביצה שנשארה \u0003במעי אמה\u0004 ולא יצאה — \u0003אינה מגדלת אפרוחים.\u0004 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכאן]\u0006 מקביעה זו הלכה למעשה? ומשיבים: \u0003למקח וממכר\u0004 לענין מסחר, ללמדנו שיש הבדל בין ביצה זו לאחרת. וכבר אירע מעשה \u0003כי\u0004 \u0005[כמו]\u0006 \u0003ההוא\u0004 \u0005[אדם אחד]\u0006 \u0003דאמר להו\u0004 \u0005[שהיה אומר\u0006 ומכריז \u0005להם]\u0006 לאנשים: \u0003ביעי\u0004"],["\u0003דפחיא למאן\u0004 \u0005[ביצים של\u0006 תרנגולת \u0005חיה למי]?\u0006 שהיה רוצה לקנות מהן. \u0003יהבו ליה ביעי\u0004 \u0005[נתנו לו ביצים]\u0006 של תרנגולת \u0003שחוטה. אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' אמי\u0004 לטעון על שרימו אותו. \u0003אמר להו\u0004 \u0005[להם]\u0006 ר' אמי למוכרים: \u0003מקח טעות הוא\u0004 זה, \u0003והדר\u0004 \u0005[וחוזר]\u0006 ובטל כולו.","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר שהרי אמר בפירוש מה הוא רוצה! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003האי לאכילה\u0004 \u0005[\u0006אדם \u0005זה]\u0006 \u0003קא בעי להו\u0004 \u0005[רצה אותן]\u0006 את הביצים ולא לאפרוחים, \u0003והאי דקאמר\u0004 \u0005[וזה שאמר]\u0006 שהוא רוצה ביצים \u0003דפחיא\u0004 \u0005[של\u0006 תרנגולת \u0005חיה]\u0006 \u0003משום דצריבן\u0004 \u0005[שהם בשלות\u0006 היטב] ו\u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכאן],\u0006 כלומר, על מה הוא בא לטעון — \u0003למיתבא ליה ביני ביני\u0004 \u0005[שיתנו לו\u0006 רק \u0005את ההפרש\u0006 בערך שיש \u0005בין\u0006 ביצים \u0005אלה לאלה],\u0006 \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין לומר כן, אלא שהיתה זו טעות יסודית שאין ביצי השחוטה יפות לדגירה, ויש כאן איפוא ביטול מקח לגמרי.","כיוצא בזה מסופר: \u0003ההוא דאמר להו\u0004 \u0005[אדם אחד שאמר להם]\u0006 למוכרים: \u0003ביעי דדכרא למאן, ביעי דדכרא למאן\u0004 \u0005[ביצים של\u0006 תרנגולת שהזדווגה עם \u0005זכר למי, ביצים של זכר למי]?\u0006 \u0003יהבו ליה ביעי דספנא מארעא\u0004 \u0005[נתנו לו ביצים ש\u0006התרנגולת קולטת \u0005מן הארץ],\u0006 כלומר, ביצים בלא הפריית זכר. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' אמי\u0004 לטעון על רמאות. \u0003אמר להו\u0004 \u0005[להם]\u0006 ר' אמי: \u0003מקח טעות הוא והדר\u0004 \u0005[וחוזר].\u0006","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא! ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003האי\u0004 \u0005[\u0006אדם \u0005זה]\u0006 \u0003לאכילה קא בעי להו\u0004 \u0005[רצה אותן\u0006 את הביצים\u0005]\u0006 \u0003והאי דקאמר דדכרא\u0004 \u0005[וזה\u0006 \u0005שאמר\u0006 שהוא רוצה של \u0005זכר]\u0006 \u0003משום דשמינן טפי\u0004 \u0005[שהם שמנות יותר]\u0006 ו\u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכאן]\u0006 הלכה למעשה \u0003— למיתבא ליה ביני וביני\u0004 \u0005[לתת\u0006 \u0005לו את ההפרש שבינתיים]\u0006 מבחינת הטיב, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר כן, ויש כאן ביטול מקח.","ועוד בהסבר דברי רב, \u0003ואי בעית אימא\u0004 \u0005[ואם\u0006 \u0005תרצה אמור]\u0006 הסבר אחר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \"ביצה\" \u0003עם יציאתה נגמרה\u0004 — פירושו: \u0003עם יציאת רובה נגמרה, וכ\u0004דברי \u0003ר' יוחנן\u0004 המפורשים. ש\u0003אמר ר' יוחנן: ביצה שיצאה רובה\u0004 מן התרנגולת \u0003מערב יום טוב,\u0004 אבל לא הטילה אותה עדיין התרנגולת, \u0003וחזרה\u0004 הביצה למעיה, ולבסוף הטילתה ביום טוב — \u0003מותרת\u0004 ביצה זו \u0003לאכלה ביום טוב.\u0004 כי כיון שיצא כבר רוב הביצה מבעוד יום, הריהי נחשבת כביצה שהוטלה אתמול.","\u0003ואיכא\u0004 \u0005[ויש]\u0006 מי ש\u0003אמר\u0004 ופירש באופן אחר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003עם יציאתה נגמרה\u0004 — כוונתו דווקא \u0003עם יציאת כולה נגמרה,\u0004 כלומר: \u0003עם יציאת כולה — אין\u0004 \u0005[כן],\u0006 \u0003אבל\u0004 אם יצאה מאתמול רק \u0003רובה — לא. ולאפוקי\u0004 \u0005[ולהוציא]\u0006 \u0003מדברי ר' יוחנן.\u0004 ועל כל פנים אפשר ליחס את דברי רב אל דברי ר' יוחנן אלו.","\u0003גופא\u0004 \u0005[לגופה],\u0006 כיון שהוזכרה שאלת ההלכה לגבי ביצים הנמצאות בתוך תרנגולת שחוטה, דנים בה לגופה. \u0003השוחט את התרנגולת ומצא בה ביצים גמורות\u0004 — \u0003מותרות\u0004 הביצים \u0003לאכלן בחלב. ר' יעקב אומר: אם היו\u0004 הביצים \u0003מעורות\u0004 (מחוברות) עדיין \u0003בגידין\u0004 — \u0003אסורות\u0004 לאוכלן בחלב, לפי שהן נחשבות כבשר.","ושואלים: \u0003מאן תנא להא דתנו רבנן\u0004 \u0005[מי שנה את\u0006 ההלכה \u0005הזו ששנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003האוכל מנבלת עוף טהור, מן השלל של ביצים\u0004 מהביצים שעודן קשורות בגידי התרנגולת, \u0003מן העצמות,\u0004 או \u0003מן הגידין,\u0004 או \u0003מן הבשר שנתלש מן החי\u0004 — הרי זה \u0003טהור.\u0004 כי כל אלה אינם נחשבים כחלק מבשר העוף, ואין בהם טומאת נבילות.","אבל אם אכל \u0003מן האשכול של ביצים\u0004 אשר הביצים שבו עדיין קטנות מאוד ואין להן כל תכונות ביצים, או לקח חתיכה \u0003מן הקורקבן\u0004 או \u0003בני מעיין, או שהמחה\u0004 (המיס) \u0003את החלב\u0004 של העוף המת \u0003וגמעו\u0004 — הרי זה \u0003טמא\u0004 בטומאת נבלת העוף.","\u0003מאן תנא\u0004 \u0005[מיהו\u0006 תנא זה \u0005ששנה]\u0006 ש\u0003מן השלל של ביצים טהור,\u0004 כלומר, שביצים הקשורות עדיין בגידי התרנגולת שוב אינן נחשבות כחלק מבשר העוף? \u0003אמר רב יוסף:\u0004 הלכה זו ש\u0003לא כ\u0004שיטת \u0003ר' יעקב. דאי\u0004 \u0005[שאם\u0006 תאמר\u0005]\u0006 שהוא \u0003כ\u0004שיטת \u0003ר' יעקב — האמר\u0004 \u0005[הרי אמר]:\u0006 \u0003אם היו מעורות בגידין\u0004 — \u0003אסורות\u0004 לאוכלן בחלב, הרי שהוא סובר כי ביצים כאלה עדיין נחשבות כחלק מן התרנגולת!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003ממאי\u0004 \u0005[ממה]\u0006 מוציא אתה מסקנה זו? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו \u0003קאמר\u0004 \u0005[שאמר]\u0006 \u0003ר' יעקב התם\u0004 \u0005[שם]\u0006 בענין אכילת ביצים כאלה בחלב \u0003אלא לענין אסורא\u0004 \u0005[איסור]\u0006 והיתר, שרצה להחמיר ולאסור באכילה אפילו ביצים כאלה, \u0003אבל לענין טומאה לא\u0004 אמר שביצים אלה נחשבות כחלק מן התרנגולת.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003לענין טומאה נמי\u0004 \u0005[גם כן]\u0006 \u0003נגזור\u0004 ונחמיר גם מן הספק, ונדון שביצים מחוברות אלה ייחשבו כחלק מן התרנגולת — הלא \u0003אפושי\u0004 \u0005[תוספת,\u0006 ריבוי\u0005]\u0006 \u0003טומאה הוא\u0004 על ידי כך, \u0003ואפושי\u0004 \u0005[ותוספת]\u0006 \u0003טומאה מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003לא מפשינן\u0004 \u0005[אין אנו מרבים]\u0006 ואין אדם גוזר טומאה על דבר מפני החשש והספק בלבד.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 וגורסים את הדיון בנושא זה באופן שונה. שהיתה השאלה: \u0003מאן תנא\u0004 \u0005[מי הוא\u0006 התנא \u0005ששנה]\u0006 ש\u0003מן האשכול של ביצים טמא? אמר רב יוסף: ר' יעקב היא,\u0004 ש\u0003אמר: אם היו מעורות בגידין — אסורות. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ממאי\u0004 \u0005[ממה],\u0006 מדוע מפרש אתה ש\u0003אשכול\u0004 פירושו: \u0003מהנך דתליא\u0004 \u0005[מן\u0006 הביצים \u0005שתלויות]\u0006 \u0003באשכול? דלמא\u0004 \u0005[שמא]\u0006 מדובר כאן ב\u0003אשכול גופיה\u0004 \u0005[עצמו],\u0006 כלומר, בשחלה, שהיא חלק הבשר שבו הביצים מתפתחות.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003אשכול גופיה\u0004 \u0005[עצמו]\u0006 \u0003מאי למימרא\u0004 \u0005[מה יש לומר]\u0006 שהרי ודאי בשר הוא! יש לענות: \u0003מידי דהוה\u0004 \u0005[כשם שהוא]\u0006 לענין \u0003קורקבן ובני מעיין, דאף על גב דבשר נינהו\u0004 \u0005[שאף על פי\u0006 \u0005ש\u0006לכל הדעות \u0005בשר הם],\u0006 \u0003כיון דאיכא אינשי דלא אכלי\u0004 \u0005[כיון שיש אנשים שאינם אוכלים\u0006 אותם\u0005]\u0006 \u0003איצטריך לאשמועינן\u0004 \u0005[צריך היה להשמיע לנו]\u0006 באלה, שבכל זאת לענין הלכה דינם כבשר, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בענין אשכול הביצים (כלומר, השחלה), \u0003כיון דאיכא אינשי דלא אכלי\u0004 \u0005[שיש אנשים שאינם אוכלים\u0006 אותו\u0005],\u0006 \u0003איצטריך לאשמועינן\u0004 \u0005[צריך היה להשמיע לנו]\u0006 שאסור לאוכלו בחלב, ואין איפוא ראיה גמורה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל\u0004 יצור \u0003שתשמישו\u0004 (הזדווגותו) רק \u0003ב\u0004שעות \u0003יום\u0004 — הרי הוא \u0003נולד\u0004 רק \u0003ביום, כל שתשמישו בלילה\u0004 — \u0003נולד בלילה. כל שתשמישו בין ביום ובין בלילה\u0004 — \u0003נולד בין ביום בין בלילה.\u0004 ומפרטים: \u0003כל שתשמישו ביום נולד ביום\u0004 — \u0003זו תרנגולת. כל שתשמישו בלילה נולד בלילה\u0004 — \u0003זו עטלף, כל שתשמישו בין ביום בין בלילה\u0004 — \u0003אדם וכל דדמי ליה\u0004 \u0005[הדומים לו].\u0006","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003כל שתשמישו ביום נולד ביום\u0004 — \u0003זו תרנגולת.\u0004 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכאן]\u0006 איזו הלכה נלמד מכאן? ומשיבים: יש מכאן מסקנה הלכתית לענין מה ש\u0003אמר רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב כהנא.\u0004 ש\u0003אמר רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב כהנא: בדק בקנה\u0004 (בקן) \u0003של תרנגולין מערב יום טוב ולא מצא בה ביצה, ולמחר השכים ומצא בה ביצה\u0004 ביום טוב — \u0003מותרת\u0004 הביצה, שאין להניח שהביצה הוטלה בלילה.","ושואלים: ו\u0003הלא\u0004 הוא \u0003בדק\u0004 מערב יום טוב ולא מצא, וודאי אם כן שנולדה הביצה ביום טוב עצמו! ומשיבים: \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003לא בדק יפה יפה. ואפילו בדק יפה, אימר\u0004 \u0005[אמור]\u0006 כי ביצה זו \u0003יצתה רובה\u0004 \u0005[רובה]\u0006 בערב יום טוב \u0003וחזרה\u0004 למעי אימה \u0003הואי\u0004 \u0005[היתה]\u0006 ביצה זו, \u0003וכ\u0004דברי \u0003ר' יוחנן.\u0004 ואם כן מדברי הברייתא למדנו שלהלכה אין אנו חוששים כלל שתרנגולת תטיל ביצה בלילה.","ושואלים: \u0003איני\u0004 \u0005[\u0006וכי \u0005כן הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוסי בן שאול אמר רב: בדק בקנה של תרנגולת מערב יום טוב ולא מצא בה ביצה, ולמחר השכים ומצא בה ביצה\u0004 — \u0003אסורה,\u0004 הרי עשויה התרנגולת להטיל ביצתה בלילה! ומשיבים: \u0003התם בדספנא מארעא\u0004 \u0005[שם\u0006 מדובר \u0005ב\u0006ביצה \u0005שקולטת מן העפר],\u0006 שלא נוצרה על ידי הפריית זכר. וביצה כזו שאינה באה מדרך תשמיש יכולה התרנגולת להטיל גם בלילה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 במקרה שאמר \u0003רב מרי נמי אימא מארעא ספנא\u0004 \u0005[גם כן אמור שמהארץ קלטה]\u0006 ואכן הטילתה בליל יום טוב ואיך אם כן התירה באכילה? ומשיבים: מדובר שם \u0003בדאיכא\u0004 \u0005[כשיש]\u0006 \u0003זכר בהדה\u0004 \u0005[עמה].\u0006 ומקשים: \u0003בדאיכא\u0004 \u0005[כשיש]\u0006 \u0003זכר נמי אימא מארעא ספנא\u0004 \u0005[גם כן אמור\u0006 שזו \u0005מן הארץ קלטה]\u0006 ולא מן הזכר! ומשיבים: \u0003אמר רבינא: גמירי\u0004 \u0005[למודים,\u0006 מקובלים אנו\u0005]\u0006 כי \u0003כל היכא דאיכא\u0004 \u0005[בכל מקום שיש]\u0006 \u0003זכר לא ספנא מארעא\u0004 \u0005[איננה קולטת מן הארץ].\u0006","ושואלים: \u0003ועד כמה\u0004 מהו השיעור שנקרא שיש זכר עמה? \u0003אמר רב גמדא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: כל היכא\u0004"],["\u0003דשמעה קליה ביממא\u0004 \u0005[שהיא שומעת\u0006 את \u0005קולו ביום],\u0006 שביום אין הקול נשמע טוב כבלילה, וכל עוד הוא במרחק שעדיין ניתן לשמוע את קריאתו ביום, עדיין נחשב תרנגול זה כנמצא במחיצתה ואינה קולטת מן הארץ אלא ממנו.","ומספרים: \u0003עבד\u0004 \u0005[עשה]\u0006 \u0003רב מרי עובדא\u0004 \u0005[מעשה]\u0006 לסמוך על שיטה זו לאחר שבדק בערב יום טוב בקינה של התרנגולת ולא מצא בה ביצה והשכים ביום טוב ומצא, ובדק \u0003עד\u0004 מרחק של \u0003שתין בתי\u0004 \u0005[ששים בתים]\u0006 מן התרנגולת ולא היה בכל התחום הזה תרנגול, ובכל זאת סמך על הימצאות תרנגול במרחק רב יותר והתיר את הביצה.","ומעירים: \u0003ואי איכא נהרא\u0004 \u0005[ואם\u0006 יש \u0005נהר]\u0006 באמצע, בינה לבין מקום התרנגול \u0003לא עברא\u0004 \u0005[אין\u0006 התרנגולת \u0005עוברת],\u0006 אולם \u0003אי איכא מברא\u0004 \u0005[אם יש מעבורת]\u0006 \u0003— עברא\u0004 \u0005[\u0006הריהי \u0005עוברת]\u0006 על המעבורת, \u0003ואי איכא מיצרא\u0004 \u0005[ואם יש\u0006 רק \u0005מיצר,\u0006 חבל צר המתוח לרוחב הנהר\u0005]\u0006 \u0003— לא עברא\u0004 \u0005[אין\u0006 התרנגולת \u0005עוברת\u0006 עליו\u0005].\u0006 ומעירים: אף על פי כן, \u0003הוה עובדא ועברא אמיצרא\u0004 \u0005[היה מעשה\u0006 שהתרנגולת \u0005עברה על המיצר],\u0006 אלא שאין אנו סומכים על כך.","ועוד שואלים: \u0003במאי אוקימתא\u0004 \u0005[במה מעמיד אתה\u0006 ההלכה \u0005הזו]\u0006 של ר' יוסי בן שאול שאסר את הביצה שנמצאה בקן בבוקר החג לאחר שבדק בערב החג ולא מצא בקן כלום — \u0003בדספנא מארעא\u0004 \u0005[כאשר קלטה\u0006 התרנגולת \u0005מן העפר],\u0006 אם כן \u0003מאי איריא\u0004 \u0005[מה שייך\u0006 דווקא\u0005]\u0006 \u0003בדק? כי\u0004 \u0005[כאשר]\u0006 \u0003לא בדק נמי\u0004 \u0005[גם כן]\u0006 תהא אותה ההלכה!","ומשיבים: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא בדק — אימא\u0004 \u0005[\u0006יכול אתה \u0005לומר]\u0006 ש\u0003מאתמול הואי\u0004 \u0005[היתה,\u0006 נולדה, ביצה זו\u0005],\u0006 ואין כל סיבה לאוסרה. ולכן אמר דווקא כאשר בדק, וברור לו שאינה מערב יום טוב. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003בדק נמי אימא\u0004 \u0005[גם כן אמור]:\u0006 שמא \u0003יצתה רובה וחזרה\u0004 למעי התרנגולת \u0003היא, וכדר' יוחנן!\u0004 ומשיבים: מקרה זה כמו של \u0003ר' יוחנן\u0004 שיוצאת רוב הביצה וחוזרת \u0003לא שכיח\u0004 \u0005[מצוי],\u0006 ואין לתלות בו.","כיון שהוזכרו דברי ר' יוסי בן שאול שמסר בשם רב, מביאים עוד מה ש\u0003אמר ר' יוסי בן שאול אמר רב: האי תומא שחיקא, סכנתא לגלויא\u0004 \u0005[שום שחוק זה, יש בו סכנה\u0006 משום \u0005גילוי],\u0006 שאם לא כיסהו כראוי יש לחשוש שמא טעם ממנו הנחש והטיל בו את ארסו ואסור מחשש סכנת נפשות.","לאחר הדיון בענין ביצה שנולדה ביום טוב ובמה שמתגלגל ממנו, שבים אנו לפירושה של המשנה. נאמר שם ש\u0003בית שמאי אומרים\u0004 כי שיעור ה\u0003שאור\u0004 להתחייב עליו בפסח הוא \u0003בכזית,\u0004 ושיעור החמץ גדול יותר — בככותבת. ולדעת בית הלל שיעורם שוה.","ושואלים: \u0003מאי טעמיהו\u0004 \u0005[מה טעמם]\u0006 של \u0003בית שמאי?\u0004 ומסבירים: \u0003אם כן,\u0004 אם לא היה הבדל בין השיעורים, \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 רק איסור \u0003חמץ, ולא בעי\u0004 \u0005[ואין צריך\u0006 לכתוב\u0005]\u0006 \u0003שאור, ואנא אמינא\u0004 \u0005[ואני אומר]\u0006 קל וחומר בעצמי: \u0003ומה חמץ שאין חמוצו קשה\u0004 כל כך — שיעורו \u0003בכזית, שאור שחמוצו קשה\u0004 — \u0003לא כל שכן.\u0004 אם כן \u0003שאור דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003למה לי\u0004 לכותבו במפורש? אלא על כרחך \u0003לומר לך\u0004 ש\u0003שיעורו של זה\u0004 של החמץ \u0003לא כשיעורו של זה\u0004 השאור, שלשאור שיעור אחר, קטן יותר.","ושואלים: \u0003ובית הלל\u0004 מה אומרים על כך? לדעתם \u0003צריכא\u0004 \u0005[צריכים]\u0006 השיעורים להכתב בכל אחד משני המקרים בנפרד; \u0003דאי כתב רחמנא\u0004 \u0005[שאילו כתבה התורה]\u0006 \u0003שאור\u0004 בלבד \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שהוא נאסר בשיעור זה \u0003משום דחמוצו קשה, אבל חמץ\u0004 ש\u0003אין חמוצו קשה — אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 לכתוב גם חמץ.","אולם \u0003ואי כתב רחמנא\u0004 \u0005[ואילו כתבה התורה]\u0006 \u0003חמץ\u0004 בלבד, הייתי אומר: חמץ נאסר בשיעור זה \u0003משום\u0004 שהוא עצמו \u0003ראוי לאכילה, אבל שאור שאין ראוי\u0004 בעצמו \u0003לאכילה\u0004 אלא רק להחמיץ בו עיסה — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יהיה שיעורו כשיעור החמץ, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 לומר את שיעור האיסור בשניהם.","ושואלים: וכי \u0003בית שמאי לית להו\u0004 \u0005[אין להם,\u0006 אינם סבורים\u0005]\u0006 כדברי \u0003ר' זירא\u0004 המובנים מאוד, ש\u0003אמר ר' זירא\u0004 על הכתוב: \"שבעת ימים שאור לא ימצא בבתיכם כי כל אוכל מחמצת ונכרתה הנפש ההיא\" (שמות יב, יט), \u0003פתח הכתוב ב\"שאור\" וסיים בחמץ\u0004 (\"מחמצת\"), \u0003לומר לך:\u0004 לענין הלכה \u0003זהו שאור זהו חמץ!\u0004 ואיך אם כן מחלקים בית שמאי בשיעוריהם?","ומשיבים: אכן, \u0003לענין\u0004 שיעור לאיסור \u0003אכילה כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שחמץ ושאור שיעורם שווה, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003לענין\u0004 חובת \u0003ביעור\u0004 החמץ מן הבתים. \u0003בית שמאי סברי\u0004 \u0005[סבורים]\u0006 כי \u0003לא ילפינן\u0004 \u0005[אין אנו לומדים]\u0006 דין \u0003ביעור מ\u0004דין \u0003אכילה,\u0004 ובביעור חמץ יש לכל מין שיעור לעצמו, \u0003ובית הלל סברי\u0004 \u0005[סוברים]\u0006 כי \u0003ילפינן\u0004 \u0005[לומדים אנו]\u0006 דין \u0003ביעור מ\u0004איסור \u0003אכילה.\u0004","ומעירים: \u0003אתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 הדבר במפורש על ידי אמוראים, ש\u0003אמר ר' יוסי בר חנינא: מחלוקת\u0004 בית שמאי ובית הלל \u0003לענין\u0004 חובת \u0003ביעור, אבל לענין\u0004 איסור \u0003אכילה\u0004 — \u0003דברי הכל\u0004 שיעורם של \u0003זה וזה בכזית.\u0004","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 נאמר: \u0003\"\u0004ו\u0003לא יראה לך חמץ ולא יראה לך שאר\u0004 בכל גבלך\u0003\"\u0004 (שמות יג, ז) — בדין זה, העוסק בביעור החמץ \u0003זהו\u0004 נושא ה\u0003מחלוקת שבין בית שמאי ו\u0004בין \u0003בית הלל. שבית שמאי אומרים: שאור בכזית וחמץ בככותבת, ובית הלל אומרים: זה וזה בכזית.\u0004 משמע שלענין מצות ביעור נחלקו, ולא לענין איסור אכילה.","ועוד נחלקו בית שמאי ובית הלל במשנה לענין \u0003השוחט חיה ועוף ביום טוב\u0004 אם לא הכינו עפר מבעוד יום כדי לכסות בו את דם השחיטה, אם מותר לחפור ביום טוב עצמו כדי להוציא עפר לכסות בו את הדם.","על לשון המשנה תוהים: \u0003השוחט,\u0004 לשון זה משמעו \u0003דיעבד\u0004 \u0005[כאשר נעשה\u0006 הדבר\u0005]\u0006 לאחר מעשה — \u0003אין\u0004 \u0005[כן],\u0006 אולם לעשות \u0003לכתחלה\u0004 — \u0003לא,\u0004 שאף בית שמאי מודים בכך, שאם לא כן, היה צריך לומר: שוחט אדם חיה ועוף ביום טוב. אולם, \u0003אימא סיפא\u0004 \u0005[אמור את סופה\u0006 של המשנה\u0005],\u0006 נאמר בה: \u0003ובית הלל אומרים: לא ישחוט. מכלל\u0004 \u0005[מכאן]\u0006 אתה למד שה\u0003תנא קמא\u0004 \u0005[הראשון,\u0006 בית שמאי\u0005]\u0006 \u0003סבר ישחוט\u0004 אפילו לכתחילה!","ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 מה שאמרו בית הלל, משמעו: \u0003לא ישחוט ויכסה קאמר\u0004 \u0005[אמר],\u0006 שעיקר ההדגשה היא לומר שגם אם שחט לא יכסה, ואילו בית שמאי אומרים שאם שחט יכסה לכתחילה.","ומקשים על פירוש זה: \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של המשנה, הלא נאמר בה: \u0003ומודים שאם שחט שיחפור בדקר ויכסה.\u0004 ואם כן ענין לכתחילה ובדיעבד לא לענין כיסוי נאמר — \u0003מכלל דרישא\u0004 \u0005[ראש\u0006 תחילת \u0005המשנה]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003דיעבד הוא\u0004 אלא מדובר לכתחילה!","\u0003אמר רבה: הכי קאמר\u0004 \u0005[כך אמר]\u0006 כך צריך להבין את המשנה: \"השוחט\" האמור כאן איננו קביעה כללית מה לעשות, אלא יש להבין: אדם מסויים שהוא \u0003השוחט, שבא לימלך\u0004 — כיצד יעשה, \u0003כיצד אומר לו\u0004 החכם? \u0003בית שמאי אומרים: אומר לו שחוט\u0004 לכתחילה, \u0003חפור וכסה. ובית הלל אומרים: לא ישחוט אלא אם כן היה לו עפר מוכן מבעוד יום.\u0004","\u0003רב יוסף אמר, הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך פירוש הדברים במשנה, בניסוח שונה מעט: \u0003השוחט שבא להמלך\u0004 כיצד יעשה, \u0003כיצד אומר לו\u0004 החכם? \u0003בית שמאי אומרים, אומר לו: לך חפור, שחוט וכסה, ובית הלל אומרים: לא ישחוט אלא אם כן היה לו עפר מוכן מבעוד יום.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003מר\u0004 \u0005[אדוני]\u0006 רב יוסף \u0003ורבה\u0004 חלוקים במה שאמר \u0003ר' זירא אמר רב קא מפלגיתו\u0004 \u0005[נחלקים אתם]?\u0006 ש\u0003אמר ר' זירא אמר רב: השוחט\u0004 חיה ועוף שיש בהם מצוות כיסוי הדם, \u0003צריך שיתן עפר למטה\u0004 מתחת לדם \u0003ועפר למעלה, שנאמר: \"ושפך את דמו וכסהו בעפר\"\u0004 (ויקרא יז, יג) — \"וכסהו \u0003עפר\" לא נאמר, אלא \"בעפר\",\u0004 כלומר: הדם צריך להיות טמון בתוך העפר, \u0003מלמד\u0004 איפוא הכתוב \u0003שהשוחט צריך שיתן עפר למטה ועפר למעלה,\u0004 ואם כן נאמר","\u0003דמר\u0004 \u0005[שאדוני]\u0006 \u0003אית ליה\u0004 \u0005[יש לו,\u0006 מקבל\u0005]\u0006 את דברי \u0003ר' זירא\u0004 ולכן צריך קודם לחפור, ורק לאחר כך, כשיש כבר עפר, לשחוט עליו. \u0003ורבה לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את דברי \u0003ר' זירא?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף לאביי: אין הדבר כן, אלא \u0003בין לדידי\u0004 \u0005[לשיטתי]\u0006 \u0003בין ל\u0004שיטת \u0003רבה אית לן\u0004 \u0005[יש לנו,\u0006 אנו מקבלים\u0005]\u0006 את דברי \u0003ר' זירא. והכא בהא קא מפלגינן\u0004 \u0005[וכאן\u0006 בדבר \u0005זה אנו חלוקים].\u0006 \u0003רבה סבר:\u0004 רק \u0003אי איכא\u0004 \u0005[אם יש]\u0006 \u0003עפר למטה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 ישחוט, \u0003אי לא\u0004 \u0005[אם אין]\u0006 עפר מוכן כבר מלמטה — \u0003לא\u0004 ישחוט כלל, ומדוע — \u0003חיישינן דלמא ממליך ולא שחיט\u0004 \u0005[חוששים אנו שמא ימלך\u0006 בדעתו \u0005ולא ישחוט\u0006 כלל\u0005]\u0006 ונמצא שחפר ועשה גומא ביום טוב שלא לצורך כלל. \u0003ולדידי\u0004 \u0005[ולשיטתי]\u0006 \u0003אדרבה\u0004 (להיפך) — \u0003הא עדיפא\u0004 \u0005[\u0006דבר \u0005זה עדיף]\u0006 שיתירו לו לחפור תחילה, \u0003דאי לא שרית ליה\u0004 \u0005[שאם לא תתיר לו]\u0006 לחפור על מנת לשחוט בכל מקרה — \u0003אתי לאמנועי\u0004 \u0005[יבוא להמנע]\u0006 \u0003משמחת יום טוב\u0004 שבאכילת בשר.","\u0003ג\u0004 שנינו במשנה: \u0003ומודים\u0004 בית הלל \u0003שאם\u0004 עבר ו\u0003שחט\u0004 — \u0003שיחפור בדקר ויכסה. אמר ר' זריקא אמר רב יהודה: והוא שיש לו דקר נעוץ\u0004 כבר באדמה \u0003מבעוד יום.\u0004 ושואלים: ומה יועיל לו אם הדקר נעוץ \u0003והא קא עביד\u0004 \u0005[והרי הוא עושה]\u0006 \u0003כתישה,\u0004 שהרי הוא צריך לכתוש את גושי האדמה כדי לעשות את העפר ראוי לכיסוי! \u0003אמר רב חייא בר אשי אמר רב:\u0004"],["מדובר כאן \u0003בעפר תיחוח\u0004 שאינו צריך עוד כתישה,","ומקשים: גם בעפר תיחוח, \u0003והא קא עביד גומא\u0004 \u0005[והרי הוא עושה גומה]\u0006 על ידי עצם הוצאת העפר או הדקר מן המקום! ומשיבים: יש להסביר זאת כדברי \u0003ר' אבא.\u0004 ש\u0003אמר ר' אבא: החופר גומא בשבת,\u0004 אם \u0003אינו צריך אלא לעפרה\u0004 ואינו מעונין בעשיית בור — \u0003פטור עליה,\u0004 משום שעשיית הגומה לא היתה מתוך רצון וכוונה תחילה לעשותה, אלא היא תוצאה של מעשה אחר, וכיון שאינו מעוניין ביצירת גומא זו אינו אלא כמקלקל והמקלקל אינו חייב במלאכת שבת ויום טוב.","שנינו במשנה \u0003שאפר כירה מוכן הוא.\u0004 על דברים אלה תוהים: \u0003אפר כירה מאן דכר שמיה\u0004 \u0005[מי הזכיר את שמו]?\u0006 כלומר, כיצד מגיעים הם לדבר באפר כירה שלא נזכר כלל קודם לכן, ולא דנו בו? \u0003אמר רבה: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך צריך להבין: \u0003ואפר כירה מוכן הוא.\u0004 כלומר: הכל מודים גם כן שאפר כירה נחשב כמוכן, ומותר לכסות בו, ואין צריך להכינו במיוחד לשם כך מבעוד יום.","\u0003אמר רב יהודה אמר רב: לא שנו\u0004 שאפר כירה נחשב מוכן לכיסוי, \u0003אלא\u0004 כ\u0003שהוסק מערב יום טוב\u0004 וכבר מאז נעשה אפר, \u0003אבל\u0004 אם \u0003הוסק ביום טוב\u0004 עצמו — \u0003אסור. ואם\u0004 האפר עדיין חם ו\u0003ראוי לצלות בו ביצה,\u0004 הרי באותה שעה שהוא ראוי לשימוש איננו מוקצה, וכיון שכך \u0003מותר\u0004 להשתמש בו גם לצורך הכיסוי.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003כשאמרו אפר כירה מוכן הוא\u0004 — \u0003לא אמרו אלא שהוסק מערב יום טוב, אבל הוסק ביום טוב\u0004 — \u0003אסור. ואם\u0004 עדיין הוא חם ו\u0003ראוי לצלות בו ביצה\u0004 — \u0003מותר.\u0004","ועוד אמרו: \u0003הכניס\u0004 אדם \u0003עפר\u0004 מבעוד יום \u0003לגנתו או לחורבתו\u0004 כדי להשתמש בו לצרכים שונים — \u0003מותר\u0004 גם \u0003לכסות בו\u0004 את הדם. וכיוצא בו \u0003אמר רב יהודה: מכניס אדם\u0004 מבעוד יום \u0003מלא קופתו\u0004 (סלו) \u0003עפר ועושה בה\u0004 בקופה זו ובעפר שבה \u0003כל צרכו.\u0004","בהלכה זו הוסיף ו\u0003דרש מר זוטרא\u0004 ברבים \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003מר זוטרא רבה\u0004 \u0005[הגדול]\u0006 והגביל הלכה זו: \u0003והוא שייחד לו\u0004 לעפר זה \u0003קרן זוית,\u0004 שמוכיח שהכניסו כדי להשתמש בו לכל צרכיו, ולא הביאו עפר סתם לפזר על קרקע הבית, שאז נתבטל לקרקע ונעשה שוב מוקצה.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005],\u0006 ממה ששנינו: \u0003כוי\u0004 (בעל חיים שהוא ספק חיה ספק בהמה), \u0003אין שוחטין אותו ביום טוב,\u0004 כי קיים הספק אם הוא חיה וחייבים לכסות את דמו, או לא, \u0003ואם שחטו\u0004 — \u0003אין מכסין את דמו. ואי איתא\u0004 \u0005[ואם יש]\u0006 מקום לדברי רב יהודה שיכול אדם לעשות בקופת העפר שלו מה שירצה, אם כן, אפילו אם הוא ודאי בהמה, \u0003לכסייה\u0004 \u0005[שיכסה אותו]\u0006 \u0003כ\u0004דברי \u0003רב יהודה!\u0004","על קושיה זו תוהים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה מקשה כך, הרי יכולת להקשות באותה מידה גם: \u0003לכסייה\u0004 \u0005[שיכסהו]\u0006 את דמו של הכוי \u0003באפר כירה, או\u0004 שיכסהו \u0003ב\u0004עפר שבא על ידי \u0003דקר נעוץ! אלא\u0004 בהכרח יש להבין שמה שאמרו שלא יכסה את דם הכוי ביום טוב, מדובר \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 עפר מוכן לכסות בו, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לומר שאין לו קופת עפר המוכנה לצרכיו.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמדובר כאשר אין לו עפר מוכן \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 אמר, הורה הלכה זו בכוי, שמצוות כסוי דמו הוא רק \u0003ספק, אפילו\u0004 חיה שחייבים בכיסוי דמה \u0003ודאי נמי\u0004 \u0005[גם כן]\u0006 \u0003לא,\u0004 שהרי הלכה כבית הלל שאין שוחטים!","ומשיבים: \u0003לא מבעיא קאמר\u0004 \u0005[\u0006בלשון \u0005לא נצרכה נאמרה]\u0006 ברייתא זו, וכך יש להבינה: \u0003לא מבעיא\u0004 \u0005[אין צריך]\u0006 לומר בחיה ועוף \u0003ודאי\u0004 שאסור \u0003לשחוט\u0004 אותם, \u0003אבל ספק — אימא\u0004 \u0005[אמור]\u0006 \u0003משום שמחת יום טוב לשחוט ולא לכסייה\u0004 \u0005[שישחטנו ולא יכסה\u0006 את דמו\u0005],\u0006 שהרי יש כאן רק ספק מצוה, ותדחה מפני מצוות שמחה ביום טוב, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלכתחילה לא ישחוט אם אין לו במה לכסות."],["ומקשים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי ממה ששנינו בסופה\u0006 של ברייתא זו\u0005]:\u0006 \u0003ואם שחטו\u0004 — \u0003אין מכסין את דמו, מכלל דרישא בדאית ליה עסקינן\u0004 \u0005[מכאן שבראשה, ב\u0006מקרה \u0005שיש לו\u0006 במה לכסות \u0005עוסקים אנו],\u0006 שהרי אם אין לו במה לכסות — מה טעם לומר שאין מכסים את דמו? ואם אכן יש לו במה לכסות, מדוע אם כן אין מכסים, או כשיטת ר' יהודה, או באפר כירה?","\u0003אלא אמר רבה,\u0004 כך יש לומר: \u0003אפר כירה\u0004 שאמרנו שהוא מוכן — \u0003מוכן\u0004 הוא כדי לכסות בו את ה\u0003ודאי\u0004 אבל \u0003אין מוכן לספק,\u0004 שאף על פי שדעתו היתה לכסות בעפר זה את דמו של מה שישחוט, בין ודאי בין ספק, מכל מקום אינו נחשב כמוכן לגבי הספק.","ותוהים: \u0003לספק מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 נחשב הוא כמוכן; אם תאמר משום \u0003דקא עביד\u0004 \u0005[שהוא עושה]\u0006 \u0003גומא\u0004 בערימת האפר כאשר נוטל משם אפר לכיסוי, הלא לצורך שחיטת ה\u0003ודאי נמי קא עביד\u0004 \u0005[גם כן הוא עושה]\u0006 \u0003גומא,\u0004 ואם יש בכך איסור — הלא האיסור קיים בכל מקרה! \u0003אלא\u0004 על כרחך עליך לומר כדברי \u0003ר' אבא\u0004 שעשיית גומה זו אינה נחשבת למלאכה, מאחר שבכך אינו אלא כמקלקל ופטור, אם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בספק, אין חשש לכך וכדברי \u0003ר' אבא!\u0004","\u0003אלא\u0004 יש לחזור בנו ולומר טעם אחר: \u0003ספק מאי טעמא\u0004 \u0005[מה טעם]\u0006 אסור — \u0003דלמא עביד\u0004 \u0005[שמא\u0006 ישכח \u0005ויעשה]\u0006 בעפר הזה גם \u0003כתישה\u0004 כדי להכשירו שיהיה ראוי לכיסוי, אבל יש להקשות שוב: שאם כן \u0003ודאי נמי\u0004 \u0005[גם כן]\u0006 \u0003נגזור\u0004 לאסור לכסות בו \u0003משום\u0004 שהוא עושה בו \u0003כתישה!\u0004 ומשיבים: אין זו קושיה, כי כשהוא מקיים מצוות כיסוי בדם ה\u0003ודאי,\u0004 גם \u0003כי קא עביד\u0004 \u0005[כאשר הוא עושה]\u0006 \u0003כתישה, אתי\u0004 \u0005[באה]\u0006 מצות \u0003עשה\u0004 של כיסוי הדם \u0003ודחי\u0004 \u0005[ודוחה]\u0006 \u0003את\u0004 מצות \u0003לא תעשה\u0004 של חילול יום טוב.","ומקשים על כך: \u0003אימר דאמרינן\u0004 \u0005[אמור שאנו\u0006 \u0005אומרים]\u0006 את הכלל ש\u0003אתי\u0004 \u0005[באה]\u0006 מצות \u0003עשה ודחי\u0004 \u0005[ודוחה]\u0006 \u0003את\u0004 מצות \u0003לא תעשה\u0004 במקרים \u0003כגון\u0004 שיש \u0003מילה בצרעת.\u0004 שיש מצוות לא תעשה בתורה, האוסרת לחתוך את נגע הצרעת מן הבשר, אולם אם היה נגע הצרעת על ערלתו של תינוק — מותר לחתוך את הערלה בשעת מילת התינוק, \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 מקרה כגון \u0003סדין\u0004 של פשתן שמשתמשים לצרכו \u0003בציצית\u0004 של צמר, אף על פי שפשתן וצמר הם כלאים ואסור לחברם יחד.","שבמקרים כגון אלה \u0003בעידנא דקא מעקר\u0004 \u0005[ב\u0006אותו \u0005זמן\u0006 עצמו \u0005ש\u0006הוא \u0005עוקר]\u0006 את ה\u0003לאו\u0004 \u0005[\u0006מצות \u0005לא תעשה]\u0006 — \u0003קא מוקים\u0004 \u0005[\u0006הריהו \u0005מעמיד,\u0006 מקיים\u0005]\u0006 את מצות ה\u0003עשה\u0004 על ידי אותו מעשה עצמו. אולם \u0003הכא\u0004 \u0005[כאן]\u0006 לענין כיסוי הדם, הרי הם שני מעשים נפרדים, שהרי \u0003בעידנא דקא מעקר\u0004 \u0005[בזמן שהוא עוקר]\u0006 את ה\u0003לאו — לא מוקים\u0004 \u0005[הריהו מעמיד,\u0006 מקיים\u0005]\u0006 את מצות ה\u0003עשה,\u0004 שהרי בתחילה הוא כותש ועובר בכך על לאו, ורק אחר כך הוא מקיים את מצוות העשה בכיסוי הדם! ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זו אינה קשה],\u0006 כי אפשר לומר \u0003דבהדי דכתיש קא מכסי\u0004 \u0005[שבתוך כדי שהוא כותש הוא מכסה]\u0006 את הדם בעפר זה שנכתש, ונמצא מקיים מצות עשה באותה פעולה שבה נעקרה מצות לא תעשה.","ומקשים מצד אחר: \u0003סוף סוף\u0004 הלא \u0003יום טוב\u0004 יש בו גם מצות \u0003עשה\u0004 לשבות בו, \u0003ו\u0004גם מצות \u0003לא תעשה\u0004 שלא לעשות בו מלאכה, \u0003ואין עשה\u0004 בלבד \u0003דוחה את לא תעשה ועשה!\u0004","\u0003אלא,\u0004 יש לדחות את הטעם שאמרנו ולומר כך, \u0003אמר רבא: אפר כירה\u0004 מתחילה \u0003דעתו\u0004 להשתמש בו לדבר שמצוותו \u0003ודאי, ואין דעתו\u0004 לשימוש בו לצורך ה\u0003ספק.\u0004 שכל דבר שלא היה בדעתו מראש להשתמש בו, אסור לעשות בו שימוש ביום טוב.","ומעירים: \u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003רבא\u0004 בענין זה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005];\u0006 ש\u0003אמר רבא: הכניס עפר\u0004 על דעת \u0003לכסות בו צואה,\u0004 שאם יטיל תינוק צואה בבית ביום טוב, יכסה אותה בעפר. שעפר זה \u0003מותר לכסות בו\u0004 גם \u0003דם צפור\u0004 או חיה שהוא שוחט. שכיון שהכין עפר אפילו לצורך הספק, שהרי יתכן שלא יטיל התינוק צואה ולא יצטרך לו כלל, בודאי נתכוון להשתמש בעפר זה כדי לכסות בו גם דם ציפור שהכינה מבעוד יום לשחיטה. אבל אם הכין את העפר מתחילה על מנת לכסות בו \u0003דם צפור\u0004 — \u0003אסור לכסות בו צואה\u0004 כי לא ידע מראש שתהא צואה שיצטרך לכסותה. שאף שהיתה כוונתו מראש להשתמש בעפר, לא היתה כוונתו אלא לשימוש ודאי, ולא לספק כמו כיסוי צואה.","\u0003נהרבלאי אמרי\u0004 \u0005[\u0006חכמי \u0005נהרבלא היו אומרים]:\u0006 \u0003אפילו הכניס עפר לכסות בו דם צפור\u0004 — \u0003מותר לכסות בו צואה\u0004 ואין לומר שלא היתה דעתו לכך.","\u0003אמרי במערבא\u0004 \u0005[אמרו בארץ ישראל]:\u0006 \u0003פליגי בה\u0004 \u0005[נחלקו\u0006 \u0005ב\u0006ענין \u0005זה]\u0006 \u0003ר' יוסי בר חמא ור' זירא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שנחלקו בכך \u0003רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף בר חמא\u0004 (הוא רבא סתם שבתלמוד הבבלי) \u0003ור' זירא. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: כוי\u0004 (שהוא ספק חיה ספק בהמה), \u0003הרי הוא\u0004 לענין זה \u0003כצואה,\u0004 שאם הכניס לביתו עפר כדי לכסות בו את הצואה, מותר להשתמש בו גם לצורך כיסוי דם שחיטת הכוי, שזה וזה ספק. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: כוי אינו כצואה,\u0004 שצואה דעתו עליה, ולכך דינה לענין זה כודאי, אבל כוי אינו אלא בכלל הספיקות ואסור להשתמש לכיסוי דמו בעפר שהוכן לצורך הצואה.","ומעירים: \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 ש\u0003רבא הוא\u0004 ש\u0003אמר\u0004 כי \u0003כוי הרי הוא כצואה,\u0004 שהרי \u0003אמר רבא: הכניס עפר\u0004 כדי \u0003לכסות בו צואה\u0004 — \u0003מותר לכסות בו דם צפור, דם צפור\u0004 — \u0003אסור לכסות בו צואה.\u0004 משמע: שדעתו לודאי ולא לספק, אם כן הוא הדין אף בכוי. ומסכמים: אכן, \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 שכך היתה המחלוקת.","\u0003רמי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב ייבא אמר\u0004 טעם אחר: \u0003כוי היינו טעמא דלא מכסינן\u0004 \u0005[זהו הטעם שאין אנו מכסים\u0006 את דמו\u0005],\u0006 לא מחשש איסור מלאכה שיש בכיסוי כזה אלא \u0003גזירה משום התרת חלבו.\u0004 שאם יכסו את דמו יחשבו הכל שכוי הוא חיה גמורה, וידוע כי חלב חיה (שלא כבהמה) מותר באכילה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כן],\u0006 \u0003אפילו ב\u0004יום \u0003חול נמי\u0004 \u0005[גם כן]\u0006 לא יכסו את דמו מפני חשש זה! ומשיבים: \u0003ב\u0004יום \u0003חול אמרי\u0004 \u0005[אומרים]\u0006 האנשים כי \u0003לנקר\u0004 \u0005[לנקות]\u0006 את \u0003חצרו הוא צריך\u0004 והוא מכסה את הדם מפני נוי החצר ולא מפני מצות הכיסוי.","ושואלים: ואם \u0003שחט באשפה\u0004 במקום המיוחד לזרוק בו גרוטאות ואשפה, שהכל יודעים שאין דואגים לנקיונה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי אז ברור שכוונתו לכיסוי הדם! או אם \u0003בא לימלך\u0004 (לשאול) בחכם מה לעשות, אם לכסות או לא, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 איך נפסוק לו?","\u0003אלא\u0004 כך יש לומר: \u0003ב\u0004יום \u0003חול אי נמי מספקא\u0004 \u0005[אם גם הדבר\u0006 מסופק\u0005]\u0006 בכל זאת \u0003אמרי ליה רבנן\u0004 \u0005[אומרים לו חכמים]:\u0006 \u0003זיל\u0004 \u0005[לך]\u0006 \u0003טרח וכסי\u0004 \u0005[וכסה],\u0006 שהרי יש ספק מצוות כיסוי, אולם \u0003ביום טוב אי מספקא\u0004 \u0005[אם מסתפק\u0006 לו\u0005]\u0006 בכגון זה — \u0003מי אמרי ליה רבנן\u0004 \u0005[האם אומרים לו חכמים]\u0006 \u0003זיל\u0004 \u0005[לך]\u0006 \u0003טרח וכסי\u0004 \u0005[וכסה]?\u0006 ומשום כך אין מכסים את דמו כדי להדגיש על ידי כך שאיננו חיה ממש.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' זירא\u0004 ברייתא זו: \u0003לא כוי בלבד אמרו\u0004 שאין לכסות את דמו ביום טוב, \u0003אלא אפילו שחט בהמה\u0004 שאין דמה צריך כיסוי, וכמו כן שחט גם \u0003חיה ועוף\u0004 שדמם חייב בכיסוי \u0003ונתערבו דמן זה בזה\u0004 — \u0003אסור לכסותו ביום טוב.\u0004","\u0003אמר ר' יוסף בר יאסיניאה: לא שנו\u0004 הלכה זו \u0003אלא\u0004 כ\u0003שאין יכול לכסותו\u0004 את כל דם התערובת \u0003בדקירה אחת, אבל\u0004 אם \u0003יכול לכסותו בדקירה אחת\u0004 — \u0003מותר.\u0004 שכיון שכל הדם ניתן לכיסוי בדקירה אחת, לכך, אף שבאותה פעולה הריהו מכסה גם את דם הבהמה שאינו צריך כיסוי, מכל מקום כיון שאינו עושה אלא פעולת כיסוי אחת, אין לייחס חשיבות לכך שאף דם הבהמה מתכסה.","ומעירים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 מובן מאליו, שכיון שמכסה אותו בבת אחת בודאי מקיים מצוה! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003נגזר\u0004 איסור אפילו על \u0003דקירה אחת אטו\u0004 \u0005[משום]\u0006 שמא יבואו לעשות \u0003שתי דקירות, קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין חוששים.","\u0003אמר רבה:\u0004 מי ש\u0003שחט צפור מערב יום טוב, אין מכסין אותו,\u0004 את דמה, \u0003ביום טוב\u0004 עצמו."],["אם \u0003גלגל\u0004 (לש) \u0003עיסה מערב יום טוב\u0004 — \u0003מפריש ממנה חלתה ביום טוב,\u0004 אף שביום טוב אין מפרישים תרומות ומעשרות, מכל מקום מאחר והותר להכין עיסה ולאפותה ביום טוב לצורך אכילת החג, וכיון שללא הפרשת חלה אסורה הפת באכילה, ודאי אם כן שהיא מהווה צורך הכרחי בהכנת הפת, ולכך לא אסרו. ואומרים, \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל אמר: אפילו גלגל עיסה מערב יום טוב\u0004 — \u0003אין מפריש ממנה חלתה ביום טוב.\u0004 שהיה לו להפריש מבעוד יום.","ומעירים: \u0003לימא פליגא\u0004 \u0005[האם לומר שחולק]\u0006 \u0003שמואל אדאבוה\u0004 \u0005[על\u0006 דברי \u0005אביו]?\u0006 שהרי \u0003אמר שמואל: חלת חוצה לארץ,\u0004 כלומר, עיסה בחוץ לארץ שאין חובת הפרשת חלה ממנה מדין תורה אלא מתקנת חכמים, \u0003אוכל והולך\u0004 מן העיסה \u0003ואחר כך מפריש\u0004 את החלה ממה שנותר. ולכאורה נובע מדבריו שהפרשת חלה בחוץ לארץ אין דינה כהפרשת תרומות, ואם מפריש ביום טוב אינו מתקן בכך כלום ואין בכך משום מעשה אסור, ולא כדברי אבי שמואל!","\u0003אמר רבא:\u0004 אין הכרח לומר כן, שהרי \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא מודה שמואל שאם קרא עליה\u0004 על עיסת חוץ לארץ \u0003שם\u0004 חלה לאחר שהפריש ממנה \u0003שאסורה לזרים?\u0004 משמע: שגם שמואל מודה שחלה קדושה מסויימת על החלה, ויתכן שהוא מודה לדברי אביו שאסור להפריש אפילו חלת חוץ לארץ ביום טוב.","\u0003בית שמאי אומרים: אין מוליכין את הסולם\u0004 שעולה בו לקחת יונים \u0003משובך לשובך, אבל\u0004 מותר להזיזו מעט, והוא \u0003מטהו מחלון לחלון\u0004 באותו שובך. \u0003ובית הלל מתירין\u0004 אף להוליכו משובך לשובך.","\u0003אמר רב חנן בר אמי: מחלוקת\u0004 זו היא דווקא כשמזיז את הסולם \u0003ברשות הרבים,\u0004 ש\u0003בית שמאי סברי\u0004 \u0005[סבורים]\u0006 כי \u0003הרואה\u0004 אותו מטלטל את סולמו \u0003אומר\u0004 לעצמו: ודאי \u0003להטיח\u0004 (למרוח טיח) על \u0003גגו\u0004 כדי למנוע את חלחול מי הגשמים דרכו לתוך הבית \u0003הוא צריך,\u0004 וחושד שעושה מלאכה אסורה בחג, \u0003ובית הלל סברי\u0004 \u0005[סבורים]\u0006 כי \u0003שובכו מוכיח עליו,\u0004 שהרי רואים מיד שהוא מניח את הסולם סמוך לשובך השני, ומבינים את כוונת מעשהו. \u0003אבל ברשות היחיד\u0004 שאין זרים רואים אותו — \u0003דברי הכל מותר.\u0004","ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב יהודה אמר רב: כל מקום שאסרו חכמים\u0004 לעשות דבר \u0003מפני מראית העין, אפילו\u0004 עושה אותו \u0003בחדרי חדרים\u0004 הרי זה \u0003אסור!\u0004 ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 שנחלקו בעיקרון זה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מי שנפלו בגדיו בשבת או בחג לתוך מים — \u0003שוטחן\u0004 להתייבש \u0003בחמה, אבל לא\u0004 ישטחם \u0003כנגד העם,\u0004 כלומר, במקום שאנשים רואים, שמא יחשדו בו שהוא מכבס בשבת. ואילו \u0003ר' אלעזר ור' שמעון אוסרין\u0004 אף לעשות כן בצנעה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 סוגיה זו בגירסה אחרת, \u0003אמר רב חנן בר אמי: מחלוקת\u0004 היא \u0003ברשות היחיד,\u0004 ש\u0003בית שמאי אית להו\u0004 \u0005[יש להם,\u0006 מקבלים הם\u0005]\u0006 את דברי \u0003רב יהודה אמר רב\u0004 ולכן גזרו אף ברשות היחיד, \u0003ובית הלל לית להו\u0004 \u0005[אין להם,\u0006 אינם מקבלים\u0005]\u0006 את דברי \u0003רב יהודה אמר רב, אבל ברשות הרבים\u0004 — \u0003דברי הכל אסור.\u0004","ומקשים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 כי לרב חנן בר אמי האומר כי לבית הלל יש להתיר את העברת הסולם משובך לשובך בצינעה, ולבית שמאי אף בצינעה אסור, אם כן \u0003רב\u0004 האומר כי כל דבר שאסרו חכמים משום מראית העין אף בצינעה אסור לעשותו הוא ש\u0003אמר\u0004 את דבריו \u0003כ\u0004שיטת \u0003בית שמאי\u0004 הדחויים מן ההלכה?","ודוחים: לא, \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בהלכה זו, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 בגדים שנרטבו בגדיו במים בשבת או בחג — \u0003שוטחן בחמה, אבל לא כנגד העם, ר' אלעזר ור' שמעון אוסרין.\u0004"],["לגוף דברי המשנה מעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003דלא כי האי תנא\u0004 \u0005[שלא כ\u0006שיטת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' שמעון בן אלעזר: מודים בית שמאי ובית הלל שמוליכין את הסולם משובך לשובך\u0004 כדי ליטול יונים, \u0003לא נחלקו אלא\u0004 לאחר שעשה כרצונו בשובך השני, האם מותר \u0003להחזיר\u0004 את הסולם לשובך הראשון שהיה עומד שם מתחילה. \u0003שבית שמאי אומרים: אין מחזירין, ובית הלל אומרים: אף מחזירין.\u0004","\u0003אמר ר' יהודה: במה דברים אמורים\u0004 — \u0003בסולם של שובך\u0004 שהכל יודעים שהוא מיוחד לכך, \u0003אבל בסולם של עליה\u0004 המשמש לצרכים שונים — \u0003דברי הכל אסור,\u0004 מפני החשד. \u0003ר' דוסא אומר: מטהו מחלון לחלון\u0004 באותו שובך עצמו. \u0003אחרים אומרים משום\u0004 (בשם) \u0003ר' דוסא: אף מדדין בו.\u0004 כלומר, מוליכים מעט מעט את רגליו של הסולם.","מסופר: \u0003בני ר' חייא נפוק לקרייתא\u0004 \u0005[יצאו אל הכפרים]\u0006 לעסוק בעסקיהם. \u0003כי אתו\u0004 \u0005[כאשר באו]\u0006 חזרה למקומם \u0003אמר להו אבוהון\u0004 \u0005[להם אביהם]\u0006 ר' חייא: \u0003כלום מעשה\u0004 כלשהו \u0003בא לידכם\u0004 שהייתם צריכים לפסוק הלכה בעניינו? \u0003אמרו לו:\u0004 ענין הולכת \u0003סולם\u0004 של עלייה לשובך \u0003בא לידנו, והתרנוהו. אמר להם: צאו ואסרו מה שהתרתם.\u0004","ומסבירים, \u0003אינהו סבור\u0004 \u0005[הם סברו]:\u0006 \u0003מדקא\u0004 \u0005[מכיון]\u0006 ש\u0003אמר ר' יהודה\u0004 כי \u0003בסולם של עליה לא פליגי\u0004 \u0005[אין חלוקים]\u0006 בית הלל ובית שמאי, \u0003מכלל\u0004 \u0005[מכאן]\u0006 שה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003סבר פליגי\u0004 \u0005[שחלוקים\u0006 הם\u0005],\u0006 וכיון שכך, לשיטת תנא קמא התירו בית הלל אף בסולם של עליה, ופסקו הם לשיטתם כתנא קמא. \u0003ולא היא\u0004 ואין הדבר כן, כי \u0003ר' יהודה טעמיה\u0004 \u0005[\u0006את \u0005טעמו]\u0006 של ה\u0003תנא קמא קא\u0004 \u0005[הוא]\u0006 \u0003מפרש\u0004 ולא בא לחלוק עליו, אלא לפרט ולפרש את דבריו.","\u0003ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה זאת, \u0003מדקתני\u0004 \u0005[ממה ששנה]\u0006 התנא הראשון: \u0003מוליכין את הסולם משובך לשובך, ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003בסולם של עליה פליגי\u0004 \u0005[נחלקו],\u0006 אם כן \u0003האי\u0004 \u0005[\u0006לשון \u0005זו]\u0006 \u0003\"מוליכין את הסולם משובך לשובך\"\u0004 איננה מדוייקת, ולשון \u0003\"מוליכין את הסולם לשובך\" מבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר]. \u0003אלא לאו הכי קאמר\u0004 \u0005[האם לא כך אמר],\u0006 כך היתה כוונת דבריו: בסולם \u0003של שובך\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אולם \u0003של עליה\u0004 — \u0003לא.\u0004","\u0003ושואלים: ואידך\u0004 \u0005[והאחרים]\u0006 בני ר' חייא, מה היה טעמם? ומשיבים: \u0003מי קתני\u0004 \u0005[האם שנה]\u0006 שם \u0003\"סולם של שובך\"? \"משובך לשובך\" קתני\u0004 \u0005[שנה]\u0006 ובא הדבר ללמדנו ש\u0003אפילו לכמה שובכים\u0004 מותר.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 לא כך היה המעשה אלא בשינוי מעט. \u0003אמרו לו: הטוי סולם של עליה בא לידנו והתרנוהו.\u0004 כלומר, נשאלנו בענין סולם של עליה שהוצב סמוך לשובך מבעוד יום, האם מותר להסיטו מחלון לחלון אחר באותו שובך עצמו, והתרנוהו. \u0003אמר להם: צאו ואסרו מה שהתרתם.\u0004 ומסבירים, \u0003אינהו סבור\u0004 \u0005[הם סברו]:\u0006 \u0003מאי דקא אסר תנא קמא\u0004 \u0005[מה שאסר התנא הראשון],\u0006 \u0003קא שרי\u0004 \u0005[התיר]\u0006 \u0003ר' דוסא,\u0004 שהתנא קמא אסר לטלטל סולם של עלייה כלל, ור' דוסא התיר להטותו מחלון לחלון. \u0003ולא היא,\u0004 כי \u0003מאי דקא שרי\u0004 \u0005[מה שמתיר]\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 לטלטל סולם \u0003קא אסר\u0004 \u0005[אסר]\u0006 \u0003ר' דוסא,\u0004 שלדעתו אפילו סולם של שובך מותר לטלטלו רק בדרך היטוי ולא בדרך הולכה.","שנינו במשנה: \u0003אבל מטהו\u0004 לסולם השובך \u0003מחלון לחלון\u0004 באותו שובך עצמו, לדעת הכל. ומבררים: \u0003אלמא\u0004 \u0005[מכאן\u0006 יוצא\u0005]\u0006 כי \u0003גבי שמחת יום טוב\u0004 דעת \u0003בית שמאי\u0004 היא \u0003לחומרא\u0004 \u0005[להחמיר],\u0006 \u0003ו\u0004דעת \u0003בית הלל לקולא\u0004 \u0005[להקל].\u0006","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו לעיל (ביצה דף ב, א): \u0003השוחט חיה\u0004 או \u0003עוף ביום טוב, בית שמאי אומרים: יחפור\u0004 באדמה \u0003ב\u0004אמצעות \u0003דקר ויכסה\u0004 בעפר זה את דם השחיטה, \u0003ובית הלל אומרים: לא ישחוט אלא אם כן היה לו עפר מוכן\u0004 לצורך זה \u0003מבעוד יום.\u0004 הרי שבית שמאי הם החוששים לכבוד ולשמחת יום טוב ולכך מקילים הם בענין כיסוי הדם, ובית הלל אינם חוששים לכך ולכך מחמירים הם בכיסוי הדם, אף שהדבר עלול למנוע משמחת יום טוב!","\u0003אמר ר' יוחנן: מוחלפת השיטה,\u0004 שיש להחליף את שיטות התנאים והשיטה האמורה בשם בית הלל היא שיטת בית שמאי, ולהיפך. את דברי ר' יוחנן דוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מוכרח אתה להגיע למסקנה קיצונית זו, הרי אפשר לפרש באופן אחר: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי\u0004 \u0005[שאמרו]\u0006 \u0003בית שמאי התם\u0004 \u0005[שם]\u0006 להתיר בכיסוי הדם \u0003אלא היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 בו כבר \u0003דקר נעוץ\u0004 ומוכן לצורך זה, שיש טעם להיתר זה, \u0003אבל היכא דליכא\u0004 \u0005[במקום שאין]\u0006 \u0003דקר נעוץ\u0004 — \u0003לא\u0004 התירו.","\u0003ואי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר כך: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי\u0004 \u0005[שאמרו]\u0006 \u0003בית הלל הכא\u0004 \u0005[כאן]\u0006 להתיר בשמחת יום טוב \u0003אלא\u0004 משום ש\u0003שובכו\u0004 שעליו הוא מציב בסופו של דבר את הסולם \u0003מוכיח עליו\u0004 שהוא מתכוין לדבר המותר, \u0003אבל התם\u0004 \u0005[שם]\u0006 \u0003לא,\u0004 ואם כן אין זו סתירה ברורה כל כך.","\u0003אלא,\u0004 חייבים אנו לחזור בנו מנוסחה זו, ולומר שדברי ר' יוחנן נאמרו לענין אחר. \u0003אי קשיא\u0004 \u0005[\u0006ו\u0005אם קשה]\u0006 בענין פירוש שיטת בית שמאי ובית הלל שבשל כך הוצרך ר' יוחנן לומר כי יש להחליף את השיטות — \u0003הא קשיא\u0004 \u0005[זה קשה],\u0006 ממשנה אחרת, שאמרו בה: \u0003בית שמאי אומרים: לא יטול\u0004 ביום טוב גוזלות יונים \u0003אלא אם כן נענע\u0004 אותם גוזלות והכין אותם \u0003מבעוד יום, ובית הלל אומרים:\u0004 אכן אין ליטול גוזלות ביום טוב אלא אם עשה הכנה מסויימת לכך מבעוד יום, אבל אין צורך בהכנה כנענוע אלא די במה ש\u0003עומד\u0004 מבעוד יום \u0003ואומר: זה וזה אני נוטל.\u0004","\u0003אלמא\u0004 \u0005[מכאן]\u0006 של \u0003גבי שמחת יום טוב\u0004 דעת \u0003בית שמאי לחומרא\u0004 \u0005[להחמיר]\u0006 \u0003ו\u0004דעת \u0003בית הלל לקולא\u0004 \u0005[להקל],\u0006 \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005],\u0006 ממה ששנינו: \u0003השוחט חיה ועוף ביום טוב,\u0004 שלדעת בית שמאי יש להקל ולחפור בדקר ולכסות את הדם, משום שמחת יום טוב, ואילו לבית הלל יש להחמיר ואין לשחוט כלל אלא אם כן היה דקר מוכן מבעוד יום! ועל כך \u0003אמר ר' יוחנן: מוחלפת השיטה.\u0004","ומקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003לא היא\u0004 (אינו כן) ואפשר ליישב באופן אחר: \u0003עד כאן לא\u0004 שמענו כי \u0003אמרי\u0004 \u0005[\u0006ש\u0005אמרו]\u0006 \u0003בית שמאי\u0004 להקל ולהתיר את כיסוי הדם ביום טוב, \u0003אלא היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 \u0003דקר נעוץ\u0004"],["\u0003אבל היכא דליכא\u0004 \u0005[במקום שאין]\u0006 \u0003דקר נעוץ\u0004 — \u0003לא\u0004 התירו אף הם. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר כך: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי\u0004 \u0005[\u0006ש\u0005אמרו]\u0006 \u0003בית הלל הכא\u0004 \u0005[כאן]\u0006 \u0003אלא כיון\u0004 ש\u0003מוקצה הוא\u0004 בלבד, ואין איסורו אלא מדברי סופרים, \u0003בעומד ואומר זה וזה אני נוטל, סגי\u0004 \u0005[די].\u0006 \u0003אבל התם\u0004 \u0005[שם]\u0006 במקום שיש איסור מן התורה \u0003לא\u0004 אמרו.","\u0003אלא, אי קשיא\u0004 \u0005[אם קשה היה]\u0006 בסתירת הדברים — \u0003הא קשיא\u0004 \u0005[זה קשה],\u0006 ממשנה אחרת: \u0003בית שמאי אומרים: אין נוטלין את העלי\u0004 (מדוך כבד שבו כרגיל כותשים את החיטים לעשות מהן דייסה) לצורך אחר ביום טוב, כגון \u0003לקצב עליו\u0004 (לחתוך עליו) את ה\u0003בשר\u0004 שיש בידו, \u0003ובית הלל מתירין. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003גבי שמחת יום טוב\u0004 שיטת \u0003בית שמאי לחומרא\u0004 \u0005[להחמיר]\u0006 \u0003ו\u0004שיטת \u0003בית הלל לקולא\u0004 \u0005[להקל],\u0006 \u0003ורמינהו\u0004 \u0005[\u0006ומקשים, \u0005משליכים על כך]\u0006 מ\u0003השוחט חיה ועוף, בית שמאי וכו'!\u0004 ועל כך \u0003אמר ר' יוחנן: מוחלפת השיטה.\u0004","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מוכיח אתה? \u0003דלמא לא היא\u0004 \u0005[שמא אינו כן]:\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי\u0004 \u0005[\u0006ש\u0005אמרו]\u0006 \u0003בית שמאי התם\u0004 \u0005[שם]\u0006 \u0003אלא היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 \u0003דקר נעוץ\u0004 ומוכן מבעוד יום, \u0003אבל היכא דליכא\u0004 \u0005[במקום שאין]\u0006 \u0003דקר נעוץ\u0004 — \u0003לא, אי נמי\u0004 \u0005[או גם כן]\u0006 כך: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי\u0004 \u0005[\u0006ש\u0005אמרו]\u0006 \u0003בית הלל הכא\u0004 \u0005[כאן]\u0006 \u0003אלא\u0004 בעלי, \u0003דאיכא\u0004 \u0005[שיש]\u0006 על כל פנים \u0003תורת כלי עליו\u0004 וכיון שכך, אין בו אף איסור מוקצה גמור, \u0003אבל התם\u0004 \u0005[שם\u0006 בענין שחיטה\u0005]\u0006 \u0003לא\u0004 אמרו כן.","\u0003אלא, אי קשיא\u0004 \u0005[אם קשה]\u0006 — \u0003הא קשיא\u0004 \u0005[זה קשה]\u0006 שבמשנה אחרת שנינו: \u0003בית שמאי אומרים: אין נותנין את העור\u0004 טרם עיבודו \u0003לפני הדורסן\u0004 (אלה שדורסים עליו), שיש בכך חשש עיבוד ביום טוב, \u0003ולא יגביהנו\u0004 את העור ממקומו, שהרי הוא לעצמו מוקצה, \u0003אלא אם כן יש עליו כזית בשר\u0004 ויטלטלהו אגב הבשר. \u0003ובית הלל מתירין.\u0004","\u0003אלמא\u0004 \u0005[מכאן]\u0006 של \u0003גבי שמחת יום טוב\u0004 שיטת \u0003בית שמאי לחומרא\u0004 \u0005[להחמיר]\u0006 \u0003ו\u0004שיטת \u0003בית הלל לקולא\u0004 \u0005[להקל],\u0006 \u0003ורמינהו\u0004 \u0005[\u0006ומקשים, \u0005משליכים על כך]\u0006 ממה ששנינו: \u0003השוחט חיה ועוף ביום טוב וכו'!\u0004 ועל כך \u0003אמר ר' יוחנן: מוחלפת השיטה.\u0004","ואף כאן דוחים: \u0003ממאי? דלמא לא היא\u0004 (אינו כן): \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי\u0004 \u0005[\u0006ש\u0005אמרו]\u0006 \u0003בית שמאי התם\u0004 \u0005[שם]\u0006 להתיר \u0003אלא היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 כבר \u0003דקר נעוץ\u0004 מבעוד יום, \u0003אבל היכא דליכא\u0004 \u0005[במקום שאין]\u0006 \u0003דקר נעוץ\u0004 — \u0003לא. אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי\u0004 \u0005[\u0006ש\u0005אמרו]\u0006 \u0003בית הלל הכא\u0004 \u0005[כאן]\u0006 \u0003אלא\u0004 בעור \u0003דחזי למזגא עלויה\u0004 \u0005[שראוי לשכב עליו]\u0006 וכיון שכך אינו מוקצה גמור, ולכך התירו, \u0003אבל התם\u0004 \u0005[שם]\u0006 בשחיטה \u0003לא\u0004 הקלו.","\u0003אלא, אי קשיא\u0004 \u0005[אם קשה]\u0006 — \u0003הא קשיא\u0004 \u0005[זה קשה]:\u0006 ששנינו, \u0003בית שמאי אומרים: אין מסלקין את התריסין\u0004 של החנויות \u0003ביום טוב\u0004 כדי לפותחן, מחשש בניה וסתירה בחג, \u0003ובית הלל מתירין\u0004 לא רק לפתוח את התריסים אלא \u0003אף להחזיר\u0004 אותם למקומם, \u0003אלמא\u0004 \u0005[מכאן]\u0006 של \u0003גבי שמחת יום טוב\u0004 שיטת \u0003בית שמאי לחומרא\u0004 \u0005[להחמיר]\u0006 \u0003ו\u0004שיטת \u0003בית הלל לקולא\u0004 \u0005[להקל],\u0006 \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003השוחט חיה ועוף ביום טוב וכו'.\u0004","\u0003בשלמא\u0004 \u0005[נניח]\u0006 כי דברי \u0003בית שמאי\u0004 על דברי \u0003בית שמאי לא קשיא\u0004 \u0005[אינם קשים],\u0006 ואפשר לתרץ: \u0003התם\u0004 \u0005[שם]\u0006 \u0003דאיכא\u0004 \u0005[שיש]\u0006 כבר \u0003דקר נעוץ\u0004 ומוכן מבעוד יום, אבל \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ליכא\u0004 \u0005[אין]\u0006 \u0003דקר נעוץ\u0004 ובאופן כזה יש לדעתם להחמיר. \u0003אלא\u0004 מדברי \u0003בית הלל\u0004 על דברי \u0003בית הלל קשיא\u0004 \u0005[קשה]!\u0006","ועל כך \u0003אמר ר' יוחנן: מוחלפת השיטה.\u0004 ומעירים: \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יכול אתה לומר תירוץ אחר, ולא להזקק לחילוף השיטות: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי\u0004 \u0005[\u0006ש\u0005אמרו]\u0006 \u0003בית הלל הכא\u0004 \u0005[כאן]\u0006 להתיר להחזיר את התריסים, \u0003אלא משום\u0004 שלדעתם \u0003אין בנין בכלים ואין סתירה בכלים,\u0004 ואם כן אין בכך איסור תורה כלל. \u0003אבל התם\u0004 \u0005[שם]\u0006 בשחיטה שאין סיבות מקילות — \u0003לא\u0004 התירו, ואין איפוא סתירה המחייבת היפוך השיטות.","\u0003בית שמאי אומרים: לא יטול\u0004 גוזלים מן השובך ביום טוב \u0003אלא אם כן נענע\u0004 את אלה שהוא רוצה לקחת \u0003מבעוד יום,\u0004 ובכך הכינם. \u0003ובית הלל אומרים:\u0004 אין צורך שינענע, אלא די שהוא \u0003עומד\u0004 מבעוד יום \u0003ואומר: \"זה וזה\u0004 מן הגוזלים \u0003אני נוטל\".\u0004","\u0003אמר רב חנן בר אמי: מחלוקת\u0004 בית שמאי ובית הלל היא \u0003בבריכה ראשונה\u0004 בזוג הגוזלים הראשון שבקע מן הביצים בחודש הראשון בשנה לזוג יונים, שאותו נוהגים המגדלים כרגיל להשאיר בשובך כדי שיהיו צוות להוריהם ולא השתמשו בהם, ש\u0003בית שמאי סברי\u0004 \u0005[סבורים]:\u0006 \u0003גזרינן דלמא אתי לאמלוכי\u0004 \u0005[גוזרים אנו\u0006 לאסור \u0005שמא יבוא\u0006 ביום טוב \u0005להמלך]\u0006 בדעתו לחוס עליהם ויחליט להשאיר אותם במקומם, ונמצא שטלטלם שלא לצורך. אבל לאחר שכבר נענעם ולא חס עליהם, שוב אין לחשוש שמא ביום טוב תשתנה דעתו.","\u0003ובית הלל סברי\u0004 \u0005[סבורים]:\u0006 \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים]\u0006 ואין חוששים שיתחרט, ולכך די באמירה בלבד. \u0003אבל בבריכה שניה,\u0004 כלומר, בגוזלים שבקעו מן המחזור השני של הביצים, בחודש הבא — \u0003דברי הכל בעומד ואומר \"זה וזה אני נוטל\" סגיא\u0004 \u0005[די].\u0006","ושואלים: \u0003ו\u0004לדעת \u0003בית הלל למה ליה למימר\u0004 \u0005[למה לו לומר]\u0006 \u0003\"זה וזה אני נוטל\"? לימא\u0004 \u0005[שיאמר]:\u0006 \u0003\"מכאן,\u0004 משובך זה, \u0003אני נוטל למחר\",\u0004 ולשם מה עליו לפרט איזה גוזלים בדיוק יטול מתוך השובך?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003בית הלל לית להו\u0004 \u0005[אין להם,\u0006 אינם מקבלים\u0005]\u0006 את מושג ה\u0003ברירה,\u0004 כלומר, אין הם מקבלים את ההנחה שלאחר מעשה נתברר למפרע מה היתה דעתו של אדם מתחילה, ולכך, אותם גוזלים שנוטל למחרת, אין אומרים שעליהם היתה דעתו מערב יום טוב, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 היה \u0003המת\u0004 מונח \u0003בבית, ולו\u0004 (לבית) \u0003פתחים הרבה,\u0004 בין סגורים בין פתוחים — לא רק חלל הבית נטמא (כאהל המת), אלא כל הפתחים \u0003כולן טמאים\u0004 ומטמאים אף את הכלים השוהים בחללם, שהרי עשוי שיוציאו את המת מכל אחד מאותם הפתחים, וכל אחד מהם הוא בכלל הסבירות שיטמא.","\u0003נפתח אחד מהן\u0004 מן הפתחים לאחר שמת, מאחר שודאי יוציאו את המת מפתח זה, הרי רק \u0003הוא\u0004 (אותו פתח) — \u0003טמא, וכולן,\u0004 שאר הפתחים — \u0003טהורין.\u0004 וכן אם \u0003חשב\u0004 לכתחילה \u0003להוציאו\u0004 את המת \u0003באחד מהן, או\u0004 להוציאו \u0003בחלון שיש בו ארבעה על ארבעה\u0004 טפחים (שיש בו מקום כדי להוציא דרכו את המת) הרי מחשבה זו \u0003מצלת על כל הפתחים כולן\u0004 לבל יטמאו, לפי שהדבר ברור שלא יוצא המת דרכם.","ולענין זה, \u0003בית שמאי אומרים: והוא שחשב להוציאו\u0004 משם \u0003עד שלא ימות המת,\u0004 שעדיין לא חלה טומאה על שאר הפתחים, \u0003ובית הלל אומרים: אף משימות המת.\u0004 שמשעה שנתברר הדבר באיזה פתח מוציאים אותו הרי נתברר שאותו פתח הוא העשוי להוציאו. ואם כן רואים שלדעת בית הלל יש ברירה!","את ההוכחה הזו דוחים: \u0003הא אתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה]\u0006 על משנה זו, בפירושה על ידי האמוראים, \u0003אמר רבה:\u0004 דברי בית הלל הם רק כדי \u0003לטהר את הפתחים מכאן ולהבא,\u0004 מאותה שעה בה החליט על הדבר, שאותם כלים שיבואו בחללו מכאן ולהבא — לא יטמאו, אבל הכלים ששהו בחללו קודם לכן — טמאים, ואם כן אין כאן כלל ענין של ברירה למפרע. \u0003וכן אמר ר' אושעיא: לטהר את הפתחים מכאן ולהבא.\u0004 ודיוקו: \u0003מכאן ולהבא — אין\u0004 \u0005[כן],\u0006 \u0003למפרע\u0004 — \u0003לא.\u0004","\u0003רבא אמר:\u0004 את הסתירה שהעלינו בשיטות בית הלל יש לישב בצורה אחרת. ו\u0003לעולם\u0004 במשנה העוסקת בטומאת פתחי בית המת, הכוונה שבית הלל מטהרים את כל הפתחים \u0003למפרע, והכא\u0004 \u0005[וכאן]\u0006 בענין הגוזלים טעם אחר הוא: \u0003היינו טעמא\u0004 \u0005[זה הטעם]:\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003מטלטל ושביק\u0004 \u0005[ומניח],\u0006 \u0003מטלטל ושביק\u0004 \u0005[ומניח],\u0006 עד שימצא את זוג הגוזלים שהוא רוצה בהם, ונמצא \u0003קא מטלטל מידי דלא חזי ליה\u0004 \u0005[שמטלטל דבר שאינו ראוי לו]\u0006 והוא מוקצה.","ומקשים: אם לכך יש לחשוש \u0003והא אמרת\u0004 \u0005[והרי\u0006 כבר \u0005אמרת]\u0006 כי מדובר \u0003בעומד ואומר \"זה וזה אני נוטל\" סגיא\u0004 \u0005[די\u0006 לו\u0005]\u0006 והרי יתכן שימצא שטעה ובחר בגוזלים שאינם ראויים ויתחרט! ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 נאמרו כשהוא עושה את הבחירה \u0003מערב יום טוב,\u0004 שכיון שיודע שאינו יכול לשנות על פי דין מהחלטתו ביום טוב עצמו, אף אם לא ימצאו אלה שבחר חן בעיניו, ולכך הריהו קובע דעתו בוודאות מה יטול, ואינו בא ליטול אחרים,"],["\u0003אבל ביום טוב אסור, דזימנין דמשתכחי\u0004 \u0005[שפעמים שנמצאים]\u0006 אלה שהיו בעיניו \u0003שמנים\u0004 — \u0003כחושים\u0004 (רזים), \u0003ו\u0004ה\u0003כחושים\u0004 נמצאים \u0003שמנים, וקמטלטל מידי דלא חזי ליה\u0004 \u0005[ו\u0006נמצא \u0005שהוא מטלטל דבר שאינו ראוי לו]\u0006 לשימושו, ועובר על טלטול מוקצה. ועוד: \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003זמנין דמשתכחי כלהו\u0004 \u0005[פעמים שנמצאים כולם]\u0006 \u0003כחושים ושביק להו\u0004 \u0005[ומניח אותם]\u0006 כולם, \u0003ואתי לאמנועי\u0004 \u0005[ויבוא להמנע]\u0006 \u0003משמחת יום טוב,\u0004 אבל כשאומר מבעוד יום: \"זה וזה אני נוטל\", הרי הוא לוקח אותם, ונמצא שמח בשמחת יום טוב.","אדם שמבעוד יום, בערב יום טוב \u0003זמן\u0004 לעצמו ליטול ביום טוב גוזלים \u0003שחורים, ומצא\u0004 למחר ביום טוב באותו שובך לא את אלה שזימן כי אם \u0003לבנים,\u0004 או שזימן \u0003לבנים ומצא שחורים,\u0004 או שזימן \u0003שנים ומצא שלשה\u0004 — הרי אלה \u0003אסורים.\u0004 שנראה כי הגוזלים הנמצאים עתה במקום הם גוזלים שלא היו שם קודם, ולא הם אלה שזימן מראש. אולם אם הוא זימן \u0003שלשה ומצא\u0004 רק \u0003שנים\u0004 — \u0003מותרים,\u0004 שאנו תולים את הדבר בבריחת אחד הגוזלים.","זימן אותם \u0003בתוך הקן\u0004 ולא מצאם, \u0003ומצא\u0004 גוזלים \u0003לפני הקן\u0004 — הרי אלו \u0003אסורין\u0004 שאנו חוששים שאחרים הם אלה, ולא אלה שזימן והניח בפנים, \u0003ואם אין שם\u0004 בסביבה הקרובה \u0003אלא הם\u0004 — \u0003הרי אלו מותרים,\u0004 שסביר להניח שהם אכן אלה שזימן והניח בתוך הקן, אלא שודאי יצאו.","\u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן\u0005]\u0006 שאם זימן שחורים ומצא לבנים ודאי שאין אלו אותם שזימן! \u0003אמר רבה: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים],\u0006 במקרה, \u0003כגון שזמן\u0004 גם \u0003שחורים ו\u0004גם \u0003לבנים, והשכים ומצא שחורים במקום\u0004 שהיו קודם ה\u0003לבנים, ולבנים במקום שחורים. מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הני אינהו נינהו\u0004 \u0005[הללו אלה הם]\u0006 הגוזלים \u0003ואתהפוכי אתהפוך\u0004 \u0005[ונהפכו\u0006 במקומותיהם\u0005],\u0006 לכך \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין אנו אומרים כן, אלא אומרים: \u0003הנך אזדו לעלמא\u0004 \u0005[אלו\u0006 שזימן \u0005הלכו לעולם,\u0006 לחוץ\u0005],\u0006 \u0003והני — אחריני נינהו\u0004 \u0005[ואלו\u0006 שמצא — \u0005אחרים הם]\u0006 שהגיעו ממקום אחר.","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[\u0006האם \u0005לומר כי מסייע לו\u0006 הדבר\u0005]\u0006 \u0003ל\u0004דעת \u0003ר' חנינא.\u0004 ש\u0003אמר ר' חנינא\u0004 (במסכת בבא בתרא דף כג, א) שאם יש בשיקול הדעת להכריע בין רוב וקרוב, שמצד אחד יש שיקול להטות כפי הרוב, והשיקול הנגדי הוא להטות כדברים הקרובים, כמו כאן, שמצד אחד רוב הגוזלים אסורים — שהרי לא זימן אותם, ומצד שני הגוזלים הקרובים — הם אלה שזימן, האם לומר שמכאן זו הוכחה לשיטתו ש\u0003רוב וקרוב — הלך\u0004 \u0005[לך]\u0006 \u0003אחר הרוב!\u0004","ודוחים: \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003אביי\u0004 לענין אחר שמדובר כאן שהגוזלים נמצאים \u0003בדף\u0004 שהיא חתיכת עץ הבולטת מן השובך, ובאות לשם תדיר יונים אחרות. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003בדף,\u0004 כיון שמצויות שם יונים אחרות הרי אין לנו שיקולי רוב וקרוב, אלא שניהם נחשבים כקרובים וכרוב, וכולן אסורות.","שנינו במשנה כי אם זימן \u0003שנים ומצא שלשה\u0004 — \u0003אסורין.\u0004 ומסבירים: \u0003מה נפשך\u0004 \u0005[מה רצונך],\u0006 כלומר, בכל אופן שתדון בכך הריהם אסורים; כי \u0003אי אחריני נינהו\u0004 \u0005[אם\u0006 אלה \u0005אחרים הם]\u0006 \u0003הא אחריני נינהו\u0004 \u0005[הרי אחרים הם]\u0006 ולא זומנו, \u0003ואי לא אחריני נינהו\u0004 \u0005[ואם לא אחרים הם]\u0006 והשנים שזימן נמצאים במקומם, מכל מקום \u0003הא איכא חד דמערב בהו\u0004 \u0005[הרי יש אחד שמעורב בהם]\u0006 שבודאי לא זומן מראש, ואסורים האחרים מפני תערובת האיסור.","\u0003ד\u0004שנינו במשנה שאם זימן \u0003שלשה ומצא שנים מותרין.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 ומסבירים: \u0003הני אינהו נינהו\u0004 \u0005[הללו אלה הם]\u0006 \u0003וחד מנייהו אזל לעלמא\u0004 \u0005[ואחד מהם הלך לעולם,\u0006 לחוץ\u0005]\u0006 ושני האחרים נשארו במקומם.","ומציעים: \u0003לימא מתניתין\u0004 \u0005[\u0006האם \u0005לומר\u0006 כי \u0005משנתנו\u0006 זו\u0005]\u0006 כשיטת \u0003רבי היא ולא רבנן\u0004 \u0005[חכמים]?\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הניח\u0004 אדם \u0003מנה\u0004 (מאה דינרים) של מעשר במקום שמור, \u0003ומצא\u0004 במקומו \u0003מאתים,\u0004 אומרים כי \u0003חולין ומעשר שני מעורבין זה בזה\u0004 שהמעשר שהניח ודאי נשאר מונח במקומו, ובא מישהו והניח שם מנה נוסף של חולין. ולכך, נוטל את היפה שביניהם ואומר: אם זהו המנה של המעשר — הרי טוב הדבר, ואם זהו המנה של החולין, הרי המנה האחר שהוא של המעשר יהא מחולל עליו ויהא זה קדוש בקדושת מעשר תמורתו, אלו \u0003דברי רבי. וחכמים אומרים: הכל חולין\u0004 שכיון שלא נשאר הדבר כפי שהיה, אולי נטל מישהו את המנה, ואותו אדם או אחר הניח במקומו מאתים אחרים, שהם חולין.","ולהיפך, \u0003הניח מאתים ומצא מנה,\u0004 הרי להלכה \u0003מנה מונח,\u0004 כלומר, אחד מן המנים הללו נחשב מונח במקומו, והוא מנה המעשר, \u0003ומנה מוטל,\u0004 כלומר, ומנה אחד, שהוא מנה החולין, הלך ממקומו, אלו \u0003דברי רבי. וחכמים אומרים: הכל חולין,\u0004 שאין אנו אומרים שהלוקח נטל רק מנה אחד בלבד, אלא ודאי לקח את שני המנים, והמנה שנמצא — אחר הביאו לשם, ואין לו קשר עם מה שהיה קודם. ואם כן ההלכה בגוזלים היא כשיטת רבי בענין המעשר!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003הא אתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה]\u0006 על משנתנו שגם \u0003ר' יוחנן ור' אלעזר דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003שאני\u0004 \u0005[שונים]\u0006 ה\u0003גוזלות הואיל ועשויין לדדות\u0004 (לקפץ ממקומם), וכיון שהם מקפצים ייתכן שאחד מהם יברח, מה שאין כן בכיס של כסף שאיננו הולך מעצמו, אלא ודאי אדם היה שם ונטלו.","ושואלים: \u0003ולמה לי לשנויי עלה\u0004 \u0005[ומדוע היה צריך\u0006 בעצם \u0005לתרץ עליה,\u0006 אותה\u0005]\u0006 כי \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003גוזלות הואיל ועשויין לדדות? והא אתמר עלה דההיא\u0004 \u0005[והרי\u0006 כבר \u0005נאמר עליה\u0006 על המשנה ההיא\u0005]\u0006 לגבי כיס הכסף, שנחלקו בה \u0003ר' יוחנן ור' אלעזר, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: בשני כיסין מחלוקת;\u0004 דווקא כשהיה כל מנה מונח בכיס (שק, ארנק) לעצמו, שעל זה בלבד נסובה המחלוקת, \u0003אבל\u0004 אם היה \u0003בכיס אחד\u0004 — \u0003דברי הכל\u0004 כסף זה \u0003חולין\u0004 הוא, שלא מסתבר שרק חצי מן הכסף ניטל וחציו נשאר. \u0003וחד\u0004 \u0005[ואחד,\u0006 האחר\u0005]\u0006 \u0003אמר: בכיס אחד\u0004 דווקא \u0003מחלוקת, אבל בשני כיסין\u0004 — \u0003דברי הכל מנה מונח\u0004 והוא מנה המעשר \u0003ומנה מוטל.\u0004","ומסבירים את הדברים: \u0003בשלמא למאן\u0004 \u0005[נניח ל\u0006שיטת \u0005מי]\u0006 ש\u0003אמר\u0004 כי \u0003בשני כיסין מחלוקת — היינו דאיצטריך לשנויי הכא\u0004 \u0005[זהו\u0006 הטעם \u0005שהיה צריך לתרץ כאן]\u0006 \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003גוזלות הואיל ועשויין לדדות. אלא למאן\u0004 \u0005[ל\u0006שיטת \u0005מי]\u0006 ש\u0003אמר\u0004 כי \u0003בכיס אחד מחלוקת, אבל בשני כיסין דברי הכל מנה מונח ומנה מוטל, השתא\u0004 \u0005[עכשיו]\u0006 \u0003למה לי לשנויי עלה\u0004 \u0005[לתרץ על כך]\u0006 תירוץ זה לחלק בין הדברים? \u0003הא אמרת\u0004 \u0005[הרי\u0006 כבר \u0005אמרת]\u0006 ש\u0003בשני כיסין לא פליגי\u0004 \u0005[נחלקו]\u0006 מעיקרו של דבר, וכל שכן בגוזלים!","\u0003אמר רב אשי: הכא\u0004 \u0005[כאן]\u0006 מדובר \u0003בגוזלות מקושרים וכיסין\u0004 של כסף \u0003מקושרים\u0004 יחד \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 וטעם ההבדל ביניהם הוא: \u0003גוזלות\u0004 — \u0003מנתחי אהדדי\u0004 \u0005[מתירים\u0006 את עצמם \u0005זה מזה]\u0006 ויתכן אם כן שרק אחד מהם אכן הלך, אולם \u0003כיסין\u0004 — \u0003לא מנתחי אהדדי\u0004 \u0005[אינם מתירים\u0006 עצמם \u0005זה מזה]\u0006 וברור שבא אדם ונטלם ומתוך שהם קשורים, ודאי נטל את שניהם.","ושואלים: אם כך היו הדברים, וברור שמישהו בא ונטל, והכיסים היו קשורים זה בזה, מה אם כן טעמו של רבי? ומסבירים: \u0003ורבי אמר\u0004 \u0005[היה יכול לומר]\u0006 \u0003לך: כיסין נמי, זמנין\u0004"],["\u0003שמתעכל\u0004 וניתר \u0003קטרייהו\u0004 \u0005[הקשר שלהם]\u0006 ויתכן שאדם נטל רק כיס אחד, ולא לקח את הכיס השני.","שנינו במשנה שאם זימנן \u0003בתוך הקן ומצא לפני הקן\u0004 — \u0003אסורין.\u0004 ומעירים: \u0003לימא מסייע ליה\u0004 \u0005[\u0006האם \u0005לומר שמסייע לו]\u0006 דבר זה לכלל \u0003לר' חנינא\u0004 ש\u0003אמר ר' חנינא: רוב וקרוב\u0004 — \u0003הלך\u0004 \u0005[לך]\u0006 \u0003אחר הרוב!\u0004 וכאן, מכיון שרוב היונים הם אלה הבאות מן העולם ולא מאלה שזימן, יש ללכת אחר הרוב ולאוסרם.","\u0003אמר אביי\u0004 לדחות: כאן מדובר \u0003בדף,\u0004 לוח עץ בולט המונח לפני כל הקינים, ושם נמצאות כל היונים, ולכן אין כאן ענין לרוב וקרוב. \u0003רבא אמר:\u0004 כאן \u0003בשני קנין זו למעלה מזו עסקינן\u0004 \u0005[עוסקים אנו].\u0006 כלומר, לא בקינים סתם, אלא דווקא באלה הנמצאות סמוכות זה לזה, \u0003ולא מבעיא\u0004 \u0005[נצרכה]\u0006 לומר אם \u0003זמן\u0004 את הגוזלים שבקן \u0003התחתונה ולא זמן\u0004 את היונים ש\u0003בעליונה ומצא\u0004 גוזלים \u0003בתחתונה ולא מצא בעליונה, דאסירן\u0004 \u0005[ש\u0006כולן \u0005אסורין],\u0006 \u0003דאמרינן\u0004 \u0005[שאנו אומרים]:\u0006 \u0003הנך\u0004 \u0005[אלה]\u0006 שהיו בקן התחתון \u0003אזלו לעלמא\u0004 \u0005[הלכו לעולם,\u0006 לחוץ\u0005]\u0006 \u0003והנך אשתרבובי אשתרבוב ונחות\u0004 \u0005[ואלה\u0006 שנמצאים שם \u0005השתרבבו וירדו]\u0006 למטה,","\u0003אלא אפילו זמן בעליונה ולא זמן בתחתונה, ובא ומצא\u0004 גוזלים \u0003בעליונה ולא מצא בתחתונה — הנך נמי אסירי\u0004 \u0005[אלה\u0006 שבעליונה \u0005גם כן אסורים],\u0006 \u0003דאמרינן\u0004 \u0005[שאנו אומרים]:\u0006 \u0003הנך אזלו לעלמא\u0004 \u0005[אלה\u0006 שזימן מתחילה \u0005הלכו לעולם]\u0006 \u0003והנך סרוכי סריך וסליקו\u0004 \u0005[ואלה\u0006 שבתחתונה \u0005נאחזו וטיפסו ועלו]\u0006 למעלה, לכן יש לחשוש לכולם.","\u0003ב\u0004שנינו במשנה ש\u0003אם אין שם אלא הן\u0004 — \u0003הרי אלו מותרין.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 \u0003במפורחין\u0004 (בגוזלים היכולים כבר לפרוח), הלא \u0003איכא למימר\u0004 \u0005[יש מקום לומר]:\u0006 \u0003הנך אזלו לעלמא, והני אחריני נינהו\u0004 \u0005[אלה\u0006 שזימן \u0005הלכו לעולם,\u0006 לחוץ, \u0005ואלה\u0006 שנמצאים עכשיו \u0005אחרים הם].\u0006","\u0003אלא\u0004 על כרחך מדובר כאן בגוזלים שהם רק \u0003מדדין\u0004 (מקפצים) ממקום למקום. ומעתה לפי הכלל שבידינו \u0003אי דאיכא\u0004 \u0005[אם\u0006 מדובר \u0005שיש]\u0006 \u0003קן\u0004 יונים אחר \u0003בתוך חמשים אמה\u0004 — ודאי \u0003אדדויי אדדו\u0004 \u0005[קיפצו\u0006 והלכו\u0005]\u0006 מאותו קן, \u0003ואי דליכא\u0004 \u0005[ואם אין]\u0006 \u0003קן בתוך חמשים אמה — פשיטא\u0004 \u0005[פשוט\u0006 ומובן מאליו\u0005]\u0006 שהם \u0003מותרין,\u0004 כי מהיכן באו? ש\u0003אמר מר עוקבא בר חמא: כל המדדה\u0004 — \u0003אין מדדה יותר מחמשים אמה.\u0004","ומשיבים: \u0003לעולם דאיכא\u0004 \u0005[שיש]\u0006 \u0003קן\u0004 אחר \u0003בתוך חמשים אמה, וכגון דקיימא\u0004 \u0005[שעומד]\u0006 הקן הנוסף \u0003בקרן זוית\u0004 ולא בקו ישר עם הקן הראשון. \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003אדדויי אדדו\u0004 \u0005[קיפצו\u0006 והלכו\u0005]\u0006 הגוזלים מקן אל קן, לכך \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי \u0003כל היכא\u0004 \u0005[מקום]\u0006 ש\u0003מדדה\u0004 הגוזל \u0003והדר חזי לקניה\u0004 \u0005[וחוזר ורואה את קינו]\u0006 — עדיין הוא \u0003מדדה ואי\u0004 \u0005[ואם]\u0006 \u0003לא,\u0004 שכשמתרחק שוב אינו יכול לראות עוד את קינו — \u0003לא מדדה\u0004 הרחק מזה.","\u0003בית שמאי אומרים: אין נוטלים את העלי\u0004 (מדוך כבד שבו כרגיל כותשים את החיטים לעשות מהן דייסה) לצורך אחר ביום טוב כגון \u0003לקצב עליו\u0004 (לחתוך עליו) את \u0003הבשר\u0004 שיש בידו, \u0003ובית הלל מתירין.\u0004 וכן, \u0003בית שמאי אומרים: אין נותנין את העור\u0004 שהפשיטו מבהמה ששחטו היום \u0003לפני הדורסן\u0004 לפני אלה הדורסים עליו בהליכתם, שהרי על ידי כך הם כמעבדים אותו. וכן \u0003לא יגביהנו\u0004 את העור מתחילה ביום טוב, שהרי אינו ראוי ליום טוב ומשום כך הריהו מוקצה, \u0003אלא אם כן יש עמו כזית בשר,\u0004 שאגב טלטול הבשר יכול לטלטל גם את העור, \u0003ובית הלל מתירין\u0004 בשני המקרים.","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא: \u0003ושוין\u0004 בית שמאי ובית הלל \u0003שאם\u0004 כבר \u0003קצב עליו,\u0004 על העלי, את ה\u0003בשר\u0004 שהיה צריך ליום טוב — \u0003שאסור לטלטלו\u0004 עוד ביום טוב, שהרי כלי זה מוקצה למלאכת איסור, ולא הותר לו לטלטלו לפי שעה אלא לצרכו.","\u0003אמר אביי: מחלוקת\u0004 זו היא דווקא \u0003בעלי, אבל בתברא גרמי\u0004 \u0005[ב\u0006סדן עץ העשוי \u0005לשבור\u0006 עליו \u0005עצמות]\u0006 — \u0003דברי הכל מותר.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הלא \u0003עלי תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 ומדוע נבוא לאסור דבר שלא נזכר בה?","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003הוא הדין\u0004 ש\u0003אפילו תברא גרמי נמי\u0004 \u0005[\u0006בסדן העשוי \u0005לשבור\u0006 עליו \u0005עצמות גם כן]\u0006 נחלקו, \u0003והאי דקתני\u0004 \u0005[וזה ששנינו\u0006 במשנה\u0005]\u0006 \u0003עלי\u0004 דווקא, הרי הוא כדי \u0003להודיעך כחן של בית הלל,\u0004 ש\u0003אפילו דבר שמלאכתו לאיסור נמי שרו\u0004 \u0005[גם כן התירו]\u0006 לטלטלו, על כן — \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שב\"תברא גרמי\" לא נחלקו כלל בית שמאי ובית הלל.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בנוסח אחר; \u0003אמר אביי: לא נצרכה אלא אפילו תברא גרמי חדתי\u0004 \u0005[\u0006בסדן העשוי \u0005לשבור עצמות\u0006 שהוא \u0005חדש],\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ממלך\u0004 \u0005[\u0006שמא \u0005ימלך\u0006 בדעתו\u0005]\u0006 \u0003ולא תבר עלה\u0004 \u0005[ישבור עליו\u0006 עצמות\u0005]\u0006 ויקצנו לצורך אחר, ואם כן אסור אף לטלטלו — על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין חוששים לזה.","ושואלים: האמנם כן הוא, \u0003ובית שמאי לא חיישי לאמלוכי\u0004 \u0005[אינם חוששים\u0006 לאפשרות \u0005שימלך\u0006 אדם בדעתו\u0005]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בתוספתא\u0005],\u0006 \u0003בית שמאי אומרים: אין מוליכין\u0004 ביום טוב \u0003טבח וסכין\u0004 בידו \u0003אצל בהמה\u0004 הרחוקה ממקומו כדי לשוחטה, \u0003ולא בהמה אצל טבח וסכין\u0004 — שמא ימלך בדעתו ונמצא שהיה מטלטל שלא לצורך. \u0003ובית הלל אומרים: מוליכין זה אצל זה.\u0004","וכן, \u0003בית שמאי אומרים\u0004 לשיטתם כי \u0003אין מוליכין תבלין ומדוך\u0004 (העלי שכותשים בו) \u0003אצל\u0004 ה\u0003מדוכה, ולא מדוכה אצל תבלין ומדוך,\u0004 כי חוששים שבסופו של דבר יתחרט ונמצא מטלטל בחג שלא לצורך. \u0003ובית הלל אומרים: מוליכין זה אצל זה\u0004 ואין חוששים לחרטה. הרי שבית שמאי חוששים שמא ימלך אדם בדעתו, ואוסרים עליו לטלטל דברים מחשש זה!","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משוה]?!\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 לגבי \u0003בהמה אתי לאמלוכי\u0004 \u0005[יבוא,\u0006 עשוי \u0005להמלך]\u0006 וטעמו, ש\u0003אמר: נשבק האי\u0004 \u0005[נניח,\u0006 נעזוב את \u0005זאת]\u0006 ה\u0003בהמה\u0004 שהיא \u0003כחושה ומייתינא\u0004 \u0005[ונביא]\u0006 \u0003בהמה אחריתי\u0004 \u0005[אחרת]\u0006 ה\u0003שמינה מינה\u0004 \u0005[ממנה].\u0006 וב\u0003קדרה נמי אתי לאמלוכי\u0004 \u0005[גם כן\u0006 \u0005יבוא,\u0006 עשוי \u0005להמלך\u0006 בדעתו\u0005],\u0006 ש\u0003אמר: נשבק האי\u0004 \u0005[נניח,\u0006 נעזוב את \u0005זאת]\u0006 ה\u0003קדרה,\u0004 התבשיל, \u0003דבעיא\u0004 \u0005[ש\u0006היא \u0005צריכה]\u0006 \u0003תבלין\u0004 ורבה בה הטירחה, \u0003ומייתינא אחריתי\u0004 \u0005[ואביא אחרת]\u0006 \u0003דלא בעיא\u0004 \u0005[שאינה צריכה]\u0006 \u0003תבלין\u0004 ואפשר לבשלה כמות שהיא. אולם \u0003הכא\u0004 \u0005[כאן]\u0006 בתברא גרמי \u0003מאי איכא למימר\u0004 \u0005[מה יש\u0006 מקום \u0005לומר]?\u0006 \u0003ממלך ולא תבר\u0004 \u0005[שימלך בדעתו ולא ישבור\u0006 את העצמות\u0005]?\u0006 הרי \u0003כיון\u0004 ש\u0003שחטה\u0004 את הבהמה \u0003— לתבירא קיימא\u0004 \u0005[לשבירת\u0006 עצמותיה היא \u0005עומדת],\u0006 שהרי אי אפשר לאכלה ללא שבירת עצמותיה.","שנינו במשנה ש\u0003בית שמאי אומרים: אין נותנין את העור\u0004 לפני הדורסן. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בתוספתא: \u0003ושוין\u0004 בית שמאי ובית הלל \u0003שמולחין עליו\u0004 על עור זה \u0003בשר לצלי,\u0004 ואין אומרים שבתוך כך נופל עליו מעט מלח ונמצא כמעבדו במליחה. \u0003אמר אביי: לא שנו אלא\u0004 במליחה \u0003לצלי\u0004 שאין מולחים אותו הרבה, \u0003אבל\u0004 כשמולח \u0003לקדרה,\u0004 כלומר, לצורך בישול הבשר בקדרה — \u0003לא\u0004 אמרו, שבשר העומד לבישול צריך למולחו היטב מכל צד, והרבה מלח נשפך על העור.","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הלא במפורש \u0003\"לצלי\" תנן\u0004 \u0005[שנינו\u0006 בתוספתא\u0005]\u0006 ולא לבישול?! ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 ש\u0003אפילו\u0004 ההיתר למלוח עליו \u0003לצלי\u0004 הוא דווקא כשמולח כדרך מליחה לצלי, אולם אם מולחו \u0003כעין קדרה\u0004 שהוא יותר מן ההכרחי לפי הדין למליחת בשר — \u0003אסור.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מולחין\u0004 ביום טוב \u0003את החלבים\u0004 של הבהמה שנשחטה אפילו ביום טוב כדי שלא יסריחו \u0003ואין מהפכין בהן\u0004 משום שאינם ראויים לשימוש ביום טוב, והרי הם מוקצה. \u0003משום\u0004 \u0005[משמו]\u0006 של \u0003ר' יהושע אמרו: שוטחן\u0004 את החלבים \u0003ברוח על גבי יתדות\u0004 שלא יסריחו.","\u0003אמר רב מתנה: הלכה כר' יהושע. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך היתה הגירסה, \u0003אמר רב מתנה: אין הלכה כר' יהושע.\u0004 על גירסה זו שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003למאן\u0004 \u0005[ל\u0006דעת \u0005מי]\u0006 ש\u0003אמר\u0004 ש\u0003הלכה כר' יהושע — אצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להשמיענו, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כיון שבמחלוקת זו חולקים \u0003יחיד ורבים\u0004 וכרגיל \u0003הלכה כרבים,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 רב מתנה שבענין זה \u0003הלכה כיחיד.\u0004","\u0003אלא למאן\u0004 \u0005[ל\u0006דעת \u0005מי]\u0006 ש\u0003אמר\u0004 ש\u0003אין הלכה\u0004 כר' יהושע \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 הרי \u0003יחיד ורבים הלכה כרבים!\u0004 ומסבירים, \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003מסתבר טעמיה\u0004 \u0005[טעמו]\u0006 של \u0003ר' יהושע דאי לא שרית ליה\u0004 \u0005[שאם לא תתיר לו]\u0006 לאוורר את החלבים \u0003ממנע ולא שחיט\u0004 \u0005[\u0006\u0005ימנע ולא ישחוט],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין אנו חוששים לכך.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 הדבר \u0003מ\u0004נתינת ה\u0003עור לפני הדורסן\u0004 שנעשה מאותם הטעמים, ומותר לדעת בית הלל שהלכה כמותם?"],["ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בשטיחת העור \u0003לא מוכחא מלתא\u0004 \u0005[אין הדבר מוכח]\u0006 כל כך ששטיחתו לצורך עיבודו נעשתה, \u0003משום דחזי\u0004 \u0005[שראוי]\u0006 העור כמות שהוא \u0003למזגא עליה\u0004 \u0005[לשכב עליו]\u0006 ולכן אפשר לומר שמניחו לצורך זה. אולם \u0003הכא אתי למימר\u0004 \u0005[כאן\u0006 בענין החלבים \u0005יבוא\u0006 אדם \u0005לומר]:\u0006 \u0003מאי טעמא שרו לי רבנן\u0004 \u0005[מה טעם התירו לי חכמים]\u0006 \u0003— כי היכי דלא לסרח\u0004 \u0005[כדי שלא יסריח],\u0006 אם כן \u0003מה לי\u0004 ההבדל אם \u0003למשטחינהו\u0004 \u0005[לשטוח אותם],\u0006 \u0003מה לי\u0004 אם \u0003לממלחינהו\u0004 \u0005[למלוח אותם],\u0006 ויבוא כתוצאה ממחשבה זו למלחם, ומליחה זו אסורה משום מלאכה.","\u0003אמר רב יהודה אמר שמואל: מולח אדם\u0004 ביום טוב \u0003כמה חתיכות בשר בבת אחת, אף על פי שאינו צריך אלא לחתיכה אחת\u0004 בלבד, שהרי פעולת המליחה אחת היא לכולן. \u0003רב אדא בר אהבה\u0004 היה \u0003מערים ומלח\u0004 \u0005[והיה מולח]\u0006 \u0003גרמא גרמא\u0004 \u0005[עצם עצם].\u0006 שהיה מולח עצם אחת, ואחר כך היה אומר: לא בזו אני רוצה אלא באחרת, ועל ידי כך היה מולח את כל הבשר שבידו.","\u0003בית שמאי אומרים: אין מסלקין\u0004 (מסירים) \u0003את התריסין\u0004 (כעין דלתות הניתנות לפירוק) \u0003ביום טוב, ובית הלל מתירין\u0004 לא רק לסלק אלא \u0003אף להחזיר.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003תריסין\u0004 אלה? \u0003אמר עולא:\u0004 מדובר כאן ב\u0003תריסי חניות\u0004 (שהן עגלות גדולות כעין בית קטן, שבהן מוצגים דברים למכירה), שיש אנשים שלא הספיקו להכין כל צורכם לצורך יום טוב, וביום טוב באים ולוקחים צרכיהם בחנות ועושים חשבון עם החנווני לאחר החג. ועל כך נחלקו אם מותר לפתוח ולסלק את תריסי החנויות הללו ביום טוב.","\u0003ואמר עולא: שלשה דברים התירו סופן\u0004 שאינו לצורך יום טוב \u0003משום תחלתן\u0004 שהוא לצורך יום טוב. והטעם, משום שאם לא תתיר את סופם, ימנע מלעשות אף את תחילתם שהוא צורך יום טוב. \u0003ואלו הן:\u0004 הותרה שטיחת \u0003עור\u0004 בהמה שנשחטה ביום טוב \u0003לפני הדורסן\u0004 (אנשים הדורסים על העור כחלק מתהליך עיבודו), מתוך שהותרה שחיטתה. \u0003ו\u0004הותרה החזרת \u0003תריסי חניות\u0004 למקומם ביום טוב, מתוך שהותרה הסרתם לצורך הספקת צרכי החג לאלו הרוצים בכך (בהקפה),","\u0003ו\u0004הותרה \u0003החזרת רטיה\u0004 (תחבושת) \u0003במקדש,\u0004 שכהן שנפצע בידו ונחבשה בתחבושת, כיון שבתוך זמן עבודת הקודש אסור שתהיה כל חציצה בין ידו לבין העבודה, הריהו מסיר את התחבושת, ולאחר סיום עבודתו הריהו חוזר וחובשה אף בשבת, אף על פי שלשאר אדם הדבר אסור. וכולם מפני הטעם שאם לא יתירו — ימנעו אנשים מלהתחיל באותה מצווה.","\u0003ורחבא\u0004 בשם \u0003ר' יהודה\u0004 אמר: \u0003אף\u0004 חבר הנזהר בטומאה \u0003הפותח חביתו\u0004 של יין כדי למוכרה לעולי הרגל, או חבר ה\u0003מתחיל ב\u0004מכירת \u0003עיסתו על גב הרגל\u0004 (לצורך הרגל)","\u0003ואליבא\u0004 \u0005[ולדעת]\u0006 התנא \u0003ר' יהודה\u0004 ש\u0003אמר יגמור.\u0004 שהעיסה והיין הללו נחשבים כטהורים בכל ימות הרגל ונקנים אף על ידי חברים הנזהרים בטומאה, אף שכרגיל המוכר יין או עיסה לכל, כיון שיד הכל ממשמשת בהם — יש לפיכך לחשוש למגע של טמאים (כגון עמי ארצות שאינם מדקדקים בהלכות טומאה) ולטמא את המאכל והמשקה מספק, מכל מקום אמרו חכמים שברגל עצמו אין לחשוש לכך והכל נחשב כטהור. וזאת כדי שלא לבייש את עמי הארצות. והוסיף ר' יהודה שאם רק התחיל למכור ברגל ולאחריו נותרה בחביתו כמות של יין — יכול לסיים ולמכור יין זה אף לחבר הנזהר בטומאה ועדיין נחשב היין כטהור.","על דבריו של עולא שואלים: הלכה זו של \u0003עור לפני הדורסן\u0004 הלא כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 ומה טעם הוצרך עולא לומר דברים המפורשים במשנה? ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003טעמייהו\u0004 \u0005[טעמם]\u0006 של \u0003בית הלל משום דחזי למזגא עלייהו\u0004 \u0005[שראוי\u0006 העור \u0005לשכב עליו]\u0006 \u0003ואפילו\u0004 אם נשחטה הבהמה \u0003מערב יום טוב נמי\u0004 \u0005[גם כן]\u0006 מותר לשטוח את עורה ביום טוב עצמו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 עולא שהטעם הוא משום ש\u0003התירו סופן משום תחלתן,\u0004 ומשום כך רק בהמה שנשחטה ב\u0003יום טוב — אין\u0004 \u0005[כן],\u0006 אולם זו שנשחטה ב\u0003ערב יום טוב\u0004 — \u0003לא.\u0004","ועוד שואלים: \u0003תריסי חנויות נמי תנינא\u0004 \u0005[גם כן שנינו],\u0006 שהרי נאמר במשנתנו בענין זה: \u0003ובית הלל מתירין אף להחזיר!\u0004 ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003טעמייהו\u0004 \u0005[טעמם]\u0006 של \u0003בית הלל\u0004 הוא \u0003משום\u0004 שלשיטתם \u0003אין\u0004 איסור \u0003בנין בכלים ואין סתירה בכלים\u0004 וכיון שהחנויות הללו שהם בעצם עגלות גדולות, אינן נחשבות כבתים, אלא ככלים הם — אין איסור בכך. ואם כן פירוק והחזרת תריסי כלים גדולים \u0003אפילו\u0004 של אלו הנמצאים בתוך ה\u0003בתים נמי\u0004 \u0005[גם כן]\u0006 יהא מותר לפרק ולהחזיר, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהטעם הוא כי \u0003התירו סופן משום תחלתן,\u0004 ולכן תריסים של \u0003חנויות — אין\u0004 \u0005[כן],\u0006 ושל \u0003בתים\u0004 — \u0003לא.\u0004","ומוסיפים לשאול: \u0003חזרת רטיה במקדש\u0004 הלא \u0003נמי תנינא\u0004 \u0005[גם כן שנינו]\u0006 במפורש במסכת עירובין (קב, ב): \u0003מחזירין רטיה במקדש אבל לא במדינה!\u0004 ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003טעמא מאי\u0004 \u0005[טעמו\u0006 של דבר שמחזירים רטיה \u0005מהו]\u0006 — \u0003משום\u0004 ש\u0003אין\u0004 איסור \u0003שבות במקדש\u0004 והרי איסור הנחת הרטיה אינו אלא גזירת חכמים משום שבות, והם לא גזרו במקדש ו\u0003אפילו כהן דלאו בר\u0004 \u0005[שאינו בן]\u0006 שאינו מסוגל לעשות \u0003עבודה הוא\u0004 ואינו צריך לכך, גם כן יהיה מותר לו להחזיר רטיה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003התירו סופן משום תחלתן;\u0004 לומר: \u0003דבר\u0004 \u0005[\u0006זה \u0005שהוא בן,\u0006 ראוי\u0005]\u0006 \u0003עבודה — אין\u0004 \u0005[כן],\u0006 אבל \u0003דלאו בר\u0004 \u0005[\u0006זה \u0005שאינו בן,\u0006 שאינו ראוי\u0005]\u0006 ל\u0003עבודה\u0004 — \u0003לא.\u0004","ושואלים גם על רחבא: \u0003פותח את חביתו\u0004 הרי \u0003נמי תנינא\u0004 \u0005[גם כן שנינו],\u0006 שכן שנינו: \u0003הפותח את חביתו\u0004 כדי למכור את היין שבתוכה, וכן חבר ה\u0003מתחיל\u0004 בעשיית \u0003עיסתו\u0004 ובמכירתה \u0003על גב\u0004 \u0005[לצורך]\u0006 \u0003הרגל,\u0004 שאמרו חכמים שאף על פי שיש חשש שימשמשו עמי הארצות את הדברים הללו ויטמאום, מכל מקום, כדי שלא לבייש את עמי הארצות לא גזרו טומאה זו ברגל והתירו אף לחברים לקנות מהם במהלך החג. ונחלקו אם נותר מהם אף לאחר החג, האם מותר לסיים את המכירה לאחר החג אף לחברים, או לא. \u0003ר' יהודה אומר: יגמור. וחכמים אומרים: לא יגמור.\u0004 ואם כן, הרי שכבר נאמרו הדברים במפורש!","ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שטעמו של ההיתר הוא כי \u0003טומאת עם הארץ ברגל כטהרה שויוה רבנן\u0004 \u0005[עשו אותה חכמים]\u0006 ואמרו שלא תחשב זו כטומאה כל עיקר, \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003לא התחיל\u0004 למכור ברגל אלא קודם לכן \u0003נמי\u0004 \u0005[גם כן]\u0006 יהיה מותר לו לסיים, שכן ברגל לא קיבלו הדברים טומאה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהטעם הוא \u0003שהתירו סופן משום תחלתן;\u0004 לומר: \u0003התחיל — אין\u0004 \u0005[כן],\u0006 \u0003לא התחיל\u0004 — \u0003לא.\u0004","ושואלים: \u0003ועולא מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר הא\u0004 הלכה \u0005זו]\u0006 בין שאר הדברים שמנה? ומשיבים: \u0003בפלוגתא לא קא מיירי\u0004 \u0005[ב\u0006מקום \u0005מחלוקת אין הוא עוסק]\u0006 שמנה רק נושאים שהם לדעת הכל ולא דבר השנוי במחלוקת. ומקשים: \u0003הנך נמי פלוגתא נינהו\u0004 \u0005[אלה גם כן מחלוקות הן],\u0006 שהרי כולם הם ממחלוקות בית שמאי ובית הלל! ומשיבים: שיטת \u0003בית שמאי במקום\u0004 שיטת \u0003בית הלל, אינה משנה.\u0004 שהכל יודעים שדברי בית שמאי נדחו מההלכה מכל וכל ואין לחשוש להם, ולכן אינם נדונים כמחלוקת.","מעירים: \u0003מתניתין דלא כהאי תנא\u0004 \u0005[משנתנו אינה כ\u0006שיטת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בתוספתא\u0005],\u0006 \u0003אמר ר' שמעון בן אלעזר: מודים בית שמאי ובית הלל שמסלקין את התריסין ביום טוב, לא נחלקו אלא\u0004 בשאלה האם מותר אף \u0003להחזיר. שבית שמאי אומרים: אין מחזירין, ובית הלל אומרים: אף מחזירין. ובמה דברים אמורים\u0004 — \u0003בשיש להן\u0004 לתריסים אלה \u0003ציר\u0004 הנכנס לתוך מקום העשוי בדופן, \u0003אבל\u0004 אם \u0003אין להן ציר\u0004 — \u0003דברי הכל מותר,\u0004 שאין כאן חשש בניה כלל אלא הכנסת קרש למקומו.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003במה דברים אמורים\u0004 שנחלקו — \u0003בשאין להם ציר, אבל יש להן ציר\u0004 — \u0003דברי הכל אסור! אמר אביי:\u0004 יש ליישב — \u0003בשיש להן ציר מן הצד\u0004 — \u0003דברי הכל אסור\u0004 שהעמדת הציר מן הצד הריהי פעולה מורכבת ודומה כמעשה בנין. ואם \u0003אין להן ציר כל עיקר\u0004 — \u0003דברי הכל מותר,\u0004 שאין פה אלא הכנסת קרש למקומו. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003בשיש להן ציר באמצע\u0004 ולא בצד"],["\u0003מר\u0004 \u0005[חכם זה,\u0006 בית שמאי\u0005]\u0006 \u0003סבר\u0004 כי \u0003גזרינן\u0004 \u0005[גוזרים אנו]\u0006 איסור על \u0003ציר באמצע אטו\u0004 \u0005[משום]\u0006 \u0003ציר מן הצד, ומר\u0004 \u0005[וחכם זה,\u0006 בית הלל\u0005]\u0006 \u0003סבר: לא גזרינן\u0004 \u0005[אין אנו גוזרים],\u0006 וכיון שאין בכך מלאכת בניה — מותר.","\u0003בית שמאי אומרים: אין מוציאין\u0004 ביום טוב \u0003לא את\u0004 הילד \u0003הקטן, ולא את הלולב, ולא את ספר\u0004 ה\u0003תורה לרשות הרבים,\u0004 כיון שאינם צרכי אוכל נפש, \u0003ובית הלל מתירין.\u0004","\u0003תני תנא קמיה\u0004 \u0005[שנה התנא,\u0006 חוזר המשניות, \u0005לפני]\u0006 \u0003ר' יצחק בר אבדימי: השוחט עולת נדבה ביום טוב\u0004 — הרי זה \u0003לוקה\u0004 משום \"כל מלאכה לא ייעשה בהם\" (שמות יב, טז)\u0003.\u0004 שכיון ששחיטה זו לא היתה לצורך אכילה, נמצא שעשה מלאכה אסורה ביום טוב.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יצחק בר אבדימי לאותו תנא: מי ש\u0003אמר לך\u0004 ברייתא זו \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי\u0006 אמרה\u0005]\u0006 — כדעת \u0003בית שמאי היא, דאמרי\u0004 \u0005[שהם אומרים]:\u0006 \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 בכלל \u0003מתוך שהותרה\u0004 ביום טוב \u0003הוצאה לצורך\u0004 אוכל נפש המותר ביום טוב — \u0003הותרה נמי\u0004 \u0005[גם כן]\u0006 הוצאה \u0003שלא לצורך, דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003בית הלל\u0004 היא, \u0003הא אמרי\u0004 \u0005[הרי אומרים הם]:\u0006 \u0003מתוך שהותרה הוצאה לצורך — הותרה נמי\u0004 \u0005[גם כן]\u0006 \u0003שלא לצורך. הכא נמי\u0004 \u0005[כאן גם כן]\u0006 במלאכת שחיטה, \u0003מתוך שהותרה שחיטה לצורך\u0004 אוכל נפש — \u0003הותרה נמי\u0004 \u0005[גם כן]\u0006 \u0003שלא לצורך\u0004 זה, אלא לכל מה שיש בו הנאת אדם במישרין או בעקיפין.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 על הסברה זו \u0003רבה: ממאי\u0004 \u0005[ממה\u0006 מסיק אתה\u0005]\u0006 ש\u0003בית שמאי ובית הלל בהא פליגי\u0004 \u0005[ב\u0006בעיה \u0005זו נחלקו]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 בשאלה אחרת נחלקו, בשאלה העקרונית האם כשם שאסורה ההוצאה מרשות אחת לרשות אחרת בשבת, כך אסורה גם ביום טוב, או שמא יש \u0003ערוב ו\u0004איסור \u0003הוצאה לשבת ואין ערוב והוצאה ליום טוב קא מיפלגי\u0004 \u0005[נחלקו].\u0006","ש\u0003מר\u0004 \u0005[שחכם זה,\u0006 בית שמאי, \u0005סבורים]\u0006 \u0003סבר\u0004 כי יש \u0003ערוב\u0004 ו\u0003הוצאה לשבת ו\u0004כמו כן יש \u0003ערוב\u0004 ו\u0003הוצאה ליום טוב,\u0004 אלא שביום טוב (כמלאכות אחרות) הותר לצורך אוכל נפש.","\u0003ומר\u0004 \u0005[וחכם זה,\u0006 בית הלל\u0005]\u0006 \u0003סבר\u0004 כי יש \u0003ערוב\u0004 ו\u0003הוצאה לשבת ואין\u0004 כלל \u0003ערוב\u0004 ואיסור \u0003הוצאה ליום טוב, כדכתיב\u0004 \u0005[כפי שנאמר]:\u0006 \u0003\"ולא תוציאו משא מבתיכם ביום השבת\"\u0004 (ירמיה יז, כב) ונדייק מכאן: \u0003בשבת — אין\u0004 \u0005[כן],\u0006 נאסרה הוצאה מרשות לרשות, אבל \u0003ביום טוב\u0004 — \u0003לא\u0004 נאסרה. ולפי הסבר זה לא נחלקו בית שמאי ובית הלל בשאלה אם מלאכה שהותרה לצורך מסויים בחג הותרה כולה, אף שלא לצורך מיוחד זה.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב יוסף\u0004 על דעת רבה: \u0003אלא מעתה,\u0004 לשיטתך שהמחלוקת היא בעיקר איסור ההוצאה ביום טוב, אם כך שלשיטת בית הלל אין איסור הוצאה ביום טוב, אם כן לשיטתם מותר אף איסור טלטול (שמקורו באיסור הוצאה), ואם כן \u0003ליפלגו\u0004 \u0005[שיחלקו]\u0006 \u0003ב\u0004הוצאת \u0003אבנים,\u0004 אם מותר או אסור להוציאן ביום טוב! \u0003אלא מדלא מפלגי\u0004 \u0005[כיון שאינם נחלקים]\u0006 \u0003באבנים\u0004 כי אם בדברים שיש בהם צורך מסויים, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי לדעת כולם נאסרה הוצאה ביום טוב אלא שהתירתה התורה לצורך, ובשאלה של","\u0003הוצאה שלא לצורך\u0004 מלאכת אוכל נפש \u0003פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 שלדעת בית הלל, כיון שהותרה לצורך — הותרה לגמרי, אלא שגזרו חכמים לאסור את ההוצאה בדברים שיש בהם טירחה יתירה ואין בהם משום צורך החג וכגון באבנים, אבל בשאר דברים, כגון בקטן וספר תורה התירו. ולדעת בית שמאי לא התירו אלא דבר שיש בו משום צורך אכילה בלבד.","ומעירים: \u0003ואף ר' יוחנן סבר:\u0004 כי \u0003במתוך שהותרה הוצאה לצורך הותרה נמי\u0004 \u0005[גם כן]\u0006 \u0003שלא לצורך פליגי\u0004 \u0005[חלוקים\u0006 הם\u0005]\u0006 וזו היתה אף לדעתו הבעיה ביסוד משנתנו. \u0003דתני תנא קמיה\u0004 \u0005[ששנה התנא,\u0006 חוזר המשניות, \u0005לפני]\u0006 \u0003ר' יוחנן,\u0004 ברייתא זו: \u0003המבשל גיד הנשה בחלב ביום טוב ואכלו\u0004 הרי זה \u0003לוקה בחמש\u0004 מלקיות על מעשה אחד זה. כיצד?","\u0003לוקה משום מבשל גיד,\u0004 שהרי עשה מלאכת בישול בדבר שאינו ראוי לאכילה כלל, ונמצא עובר משום מבשל ביום טוב, \u0003ולוקה משום אוכל גיד\u0004 שנאסר במפורש בתורה, \u0003ולוקה משום מבשל בשר בחלב\u0004 שבאיסור זה נענשים גם על הבישול בלבד, \u0003ולוקה משום אוכל בשר בחלב, ולוקה\u0004"],["\u0003משום הבערה,\u0004 שהרי עשה אף מלאכת הבערה ביום טוב שלא לצורך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לאותו תנא: \u0003פוק תני לברא\u0004 \u0005[צא\u0006 ו\u0005שנה בחוץ],\u0006 כלומר: ברייתא זו אין לשנותה בבית המדרש משום שאינה מוסמכת, כי השיטה הסוברת שיש איסור מיוחד ביום טוב משום \u0003הבערה\u0004 או \u0003בשול\u0004 — \u0003אינה משנה\u0004 הראויה לדיון רציני. \u0003ואם תמצא לומר משנה היא\u0004 ואינה טעות — אין כן הלכה, אלא לדעת \u0003בית שמאי היא, דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]:\u0006 \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003מתוך שהותרה הוצאה לצורך — הותרה נמי\u0004 \u0005[גם כן]\u0006 \u0003שלא לצורך. הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אין אנו אומרים \u0003מתוך שהותרה הבערה\u0004 ביום טוב \u0003לצורך\u0004 אוכל נפש, \u0003הותרה נמי\u0004 \u0005[גם כן]\u0006 \u0003שלא לצורך. דאי\u0004 \u0005[שאם]\u0006 תרצה לומר כי ברייתא זו כשיטת","\u0003בית הלל\u0004 היא — אינך יכול לומר כן, \u0003כיון דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]\u0006 \u0003מתוך שהותרה הוצאה לצורך — הותרה נמי\u0004 \u0005[גם כן]\u0006 \u0003שלא לצורך, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003מתוך שהותרה הבערה לצורך — הותרה נמי\u0004 \u0005[גם כן]\u0006 \u0003שלא לצורך\u0004 ואין לחייבו בין שאר האיסורים אף משום הבערה.","\u0003בית שמאי אומרים:\u0004 אף שהותרה הפרשת חלה ביום טוב (שהרי מותר לו להכין עיסה ולאפותה ביום טוב, ובלא הפרשת חלה הרי לא יוכל לאוכלה), מכל מקום \u0003אין מוליכין\u0004 את ה\u0003חלה\u0004 שהופרשה, וכן אף שהותרה הרמת מתנות כהונה (זרוע לחיים וקיבה) מבהמה שנשחטה ביום טוב, מכל מקום אין מוליכים \u0003מתנות\u0004 אלו \u0003לכהן ביום טוב, בין שהורמו\u0004 המתנות \u0003מאמש,\u0004 מערב יום טוב, \u0003בין שהורמו מהיום. ובית הלל מתירין.\u0004","\u0003אמרו להם בית שמאי:\u0004 הבה נלמד \u0003גזרה שוה: חלה ומתנות\u0004 שתיהן, \u0003מתנה\u0004 הם \u0003לכהן, ו\u0004כן \u0003תרומה\u0004 שמפרישים מן התבואה אף היא \u0003מתנה לכהן, כשם\u0004 שאתם מודים \u0003שאין מוליכין את התרומה\u0004 לכהן בחג, \u0003כך\u0004 גם \u0003אין מוליכין את המתנות.\u0004","\u0003אמרו להם בית הלל:\u0004 אין מקום להשוואה זאת; \u0003לא, אם אמרתם בתרומה\u0004 שאסור להוליכה לכהן ביום טוב — משום \u0003שאינו זכאי בהרמתה\u0004 (בהפרשתה), שאין רשות להפריש תרומה ביום טוב עצמו, \u0003תאמרו במתנות\u0004 הבהמה או בחלה \u0003שזכאי בהרמתן\u0004 אף ביום טוב עצמו, וכיון שאין איסור בהפרשתן — מותר גם להוליכן לכהן.","\u0003קא סלקא דעתך\u0004 \u0005[עלה על הדעת]\u0006 של התלמידים בבית המדרש לומר בפירוש דברי המשנה כי \u0003שהורמו מהיום\u0004 הכוונה מבהמות \u0003שנשחטו מהיום, ו\u0004מתנות \u0003שהורמו מאמש\u0004 הכוונה היא מבהמות \u0003שנשחטו מאמש.\u0004 ושואלים: אם כך \u0003מני מתניתין\u0004 \u0005[\u0006כשיטת \u0005מי היא משנתנו]?\u0006 \u0003לא\u0004 כשיטת \u0003ר' יוסי ולא\u0004 כשיטת \u0003ר' יהודה, אלא\u0004 כשיטת \u0003אחרים. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003אמר ר' יהודה: לא נחלקו בית שמאי ובית הלל על המתנות שהורמו מערב יום טוב שמוליכין\u0004 אותם לכהן ביום טוב עצמו \u0003עם המתנות שהורמו מהיום ושנשחטו מהיום. לא נחלקו, אלא להוליכן\u0004 למתנות הורמו אמש \u0003בפני עצמן, שבית שמאי אומרים: אין מוליכין, ובית הלל אומרים: מוליכין.\u0004","\u0003וכך היו בית שמאי דנין: חלה ומתנות\u0004 — \u0003מתנה לכהן, ותרומה\u0004 — \u0003מתנה לכהן, כשם שאין מוליכין את התרומה\u0004 לכהן ביום טוב — \u0003כך אין מוליכין את המתנות. אמרו להם בית הלל: לא אם אמרתם בתרומה\u0004 — \u0003שאינו זכאי\u0004 (רשאי) \u0003בהרמתה\u0004 ביום טוב, \u0003תאמרו במתנות שזכאי בהרמתן\u0004 אף ביום טוב עצמו ולכך אף הותרה הולכתן. זו היא שיטת ר' יהודה. ולפי מה שהובן ממהלך הדברים במשנתנו, אוסרים בית שמאי גם הולכת מתנות שהורמו היום.","\u0003אמר ר' יוסי:\u0004 לא כך היה הדבר אלא \u0003לא נחלקו בית שמאי ובית הלל על המתנות\u0004 מן הבהמה \u0003שמוליכין\u0004 אותם ביום טוב לכהן בכל מקרה, \u0003לא נחלקו אלא על התרומה, שבית שמאי אומרים: אין מוליכין, ובית הלל אומרים: מוליכין. וכך היו בית הלל דנין: חלה ומתנות\u0004 — \u0003מתנה לכהן, ותרומה\u0004 — \u0003מתנה לכהן, כשם שמוליכין את המתנות\u0004 אף ביום טוב, \u0003כך מוליכין\u0004 אף \u0003את התרומה. אמרו להם בית שמאי: לא אם אמרתם במתנות שזכאי בהרמתן\u0004 ביום טוב עצמו — \u0003תאמרו בתרומה שאין זכאי בהרמתה!\u0004","\u0003אחרים אומרים\u0004 כך היתה המחלוקת: \u0003לא נחלקו בית שמאי ובית הלל על התרומה שאין מוליכין\u0004 אותה ביום טוב לכהן, \u0003לא נחלקו אלא על המתנות, שבית שמאי אומרים אין מוליכין, ובית הלל אומרים מוליכין.\u0004 אם כן \u0003לימא\u0004 \u0005[האם נאמר]\u0006 כי משנתנו היא רק כשיטת \u0003אחרים היא ולא כ\u0004שיטת \u0003ר' יהודה?\u0004 (כי ברור שמשנתנו רחוקה משיטת ר' יוסי).","\u0003אמר רבא: מי קתני\u0004 \u0005[האם שנינו\u0006 במשנה\u0005]\u0006 \u0003\"שהורמו מהיום ושנשחטו מהיום\"?\u0004 לא, כי אם לשון \u0003\"שהורמו\"\u0004 בלבד \u0003קתני\u0004 \u0005[שנה]\u0006 \u0003ולעולם\u0004 יש לפרש: \u0003שחיטתן מאמש\u0004 והרמתן מהיום, והם הם דברי ר' יהודה. ושואלים: אם כך, \u0003לימא\u0004 \u0005[נאמר]\u0006 שמשנתנו כשיטת \u0003ר' יהודה היא ולא\u0004 כשיטת \u0003אחרים!\u0004 ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 ותפרש כי משנתנו כשיטת \u0003אחרים\u0004 היא, \u0003ובהנך\u0004 \u0005[ובאלה]\u0006 ש\u0003נשחטו מאמש\u0004 נחלקו, ולא באלה שנשחטו מהיום.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש \u0003היינו\u0004 \u0005[הרי\u0006 אלו \u0005הם]\u0006 דברי \u0003ר' יהודה,\u0004 ומה ההבדל בין דברי ר' יהודה ואחרים? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל לענין \u0003טפלה.\u0004 אם מתנות שהופרשו מאמש ואינו רשאי להפרישם היום, האם מותר לו לטופלם ולצרפם אל המתנות שהפריש אותן בו ביום ולהוליכם ביחד לכהן. שלדעת ר' יהודה מוליכים אותן, ולדעת אחרים אין מוליכים.","באותה מחלוקת שהובאה מן התוספתא, \u0003אמר רב יהודה אמר שמואל: הלכה כ\u0004שיטת \u0003ר' יוסי,\u0004 ולא כשאר שיטות. מסופר: \u0003רב טובי בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' נחמיה הוה ליה גרבא דחמרא\u0004 \u0005[היה לו קנקן יין]\u0006 של \u0003תרומה, אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב יוסף, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מהו לאמטויי\u0004 \u0005[להביאו]\u0006 \u0003לכהן האידנא\u0004 \u0005[עכשיו]\u0006 ביום טוב? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב יהודה אמר שמואל: הלכה כ\u0004שיטת \u0003ר' יוסי,\u0004 ולשיטת ר' יוסי בית הלל (שהלכה כמותם) מתירים להביא תרומה לכהן ביום טוב.","מסופר: \u0003אושפזיכניה\u0004 \u0005[מארחו]\u0006 של \u0003רבא בר רב חנן הוה ליה אסורייתא דחרדלא \u0004[\u0005היו לו חבילות חרדל\u0006] שלא עובדו כלל, והיה הזרע נתון עדיין בגבעולי החרדל, \u0003אמר ליה\u0004 \u0005[לו]\u0006 לאורחו החכם: \u0003מהו לפרוכי ומיכל מנייהו\u0004 \u0005[\u0006האם מותר \u0005לפרוך את\u0006 שרביטי החרדל \u0005ולאכול מהם]\u0006 \u0003ביום טוב? לא הוה בידיה\u0004 \u0005[היתה בידו\u0006 תשובה\u0005],\u0006 \u0003אתא לקמיה\u0004 \u0005[הלך\u0006 רבא בר חנן \u0005לפני]\u0006 \u0003רבא\u0004 לשאול אותו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 שנינו: \u0003מוללין מלילות ומפרכין קטניות ביום טוב\u0004 ואם כן מותר.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי:\u0004 הלא שנינו: \u0003המולל מלילות\u0004 שמולל ומקלף חיטים רכות \u0003מערב שבת, למחר,\u0004 ביום השבת עצמו, \u0003מנפח,\u0004 כלומר: מעביר ומנפה את המוץ בדרך שונה משאר ימות החול, על ידי זה שמעביר את המלילות \u0003מיד ליד,\u0004 שבכך המוץ נופל מאליו, \u0003ואוכל\u0004 את גרעיני החיטה. \u0003אבל לא\u0004 יעשה זאת לא \u0003בקנון\u0004 שהוא כלי כעין משפך, שבו היו עושים לעיתים את עבודות הזרייה והבירור, \u0003ולא בתמחוי\u0004 (קערה גדולה),","\u0003והמולל מלילות מערב יום טוב למחר\u0004 — \u0003מנפח על יד על יד,\u0004 כלומר, מעט מעט \u0003ואוכל, אפילו בקנון ואפילו בתמחוי, אבל לא\u0004 יעשה זאת \u0003בטבלא ולא בנפה ולא בכברה\u0004 שהם כלים המיוחדים לצורך ניפוי, ואין עושים בהם אלא כמויות גדולות, ונראה כאילו עושה לצורך הימים שלאחר החג ודבר זה ודאי אסור. על כל פנים, מלשון הברייתא נדייק: \u0003מערב יום טוב — אין\u0004 \u0005[כן]\u0006 אבל \u0003ביום טוב\u0004 עצמו \u0003לא,\u0004 ומכאן שאסור לעשות כל מלילות או לפרוך קטניות ביום טוב!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמותר הדבר \u0003ביום טוב,\u0004 ובכל זאת אין לדייק דבר מלשון הברייתא \u0003ואיידי דתנא רישא\u0004 \u0005[ומתוך ששנה\u0006 ב\u0005ראשה\u0006 של הברייתא\u0005]\u0006 \u0003\"מערב שבת\",\u0004 שודאי דבר זה אסור לעשותו ביום השבת עצמו מחשש מלאכה אסורה בשבת, \u0003תנא סיפא נמי\u0004 \u0005[שנה בסופה גם כן]\u0006 \u0003\"מערב יום טוב\",\u0004 ולא משום שאסור הדבר ביום טוב עצמו.","הקשה לו אביי מצד אחר: \u0003אם כן\u0004 אתה אומר הרי \u0003מצינו תרומה שזכאי בהרמתה\u0004 ביום טוב עצמו, שכן לפני שהיו החטים מלילות ודאי לא היו מוכנות לאכילה, ולא היו חייבות בתרומה. ועתה שמללן והכינן לאכילה נתחייבו בתרומה, ואם מותר לאוכלן — בהכרח שמותר גם להפריש תרומה כדי להתירן! \u0003ותנן\u0004 \u0005[ושנינו]\u0006 במפורש במשנתנו: \u0003לא, אם אמרתם בתרומה שאינו זכאי בהרמתה,\u0004 משמע שאפילו בית הלל מסכימים שאינו רשאי להרים כל תרומה ביום טוב!","את הקושיה הזאת דוחים: \u0003לא קשיא\u0004 \u0005[אין זה קשה],\u0006 כי"],["\u0003הא\u0004 \u0005[זו]\u0006 כשיטת \u0003רבי\u0004 היא, ולדעתו שיש חיוב תרומה במלילות יש אכן אף אפשרות של הרמת תרומות בחג עצמו, \u0003הא\u0004 \u0005[וזו]\u0006 משנתנו \u0003כר' יוסי בר' יהודה\u0004 היא, שלדעתו אין תרומה במלילות. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בענין זה: \u0003הכניס\u0004 אדם \u0003שבלין\u0004 לביתו כדי לטוחנם לקמח ו\u0003לעשות מהן עיסה\u0004 — \u0003אוכל מהן\u0004 לפי שעה בדרך \u0003עראי\u0004 לפני שנטחנו \u0003ופטור\u0004 מן התרומה. כי כל עוד לא נגמרה מלאכת התבואה, עדיין לא חל עליה חיוב הפרשת תרומה.","אולם אם הכניס את השבלים מתחילה לא לטחינה אלא כדי \u0003למוללן במלילות\u0004 ולאוכלן מעט מעט — \u0003רבי מחייב\u0004 בהפרשת תרומה מהן וכל עוד לא הפריש אסור לו לאוכלן \u0003ור' יוסי בר' יהודה פוטר\u0004 אותן מהפרשה\u0003.\u0004 שלדעתו אף כוונה זו אינה מחייבת עדיין בתרומה, ואין חובת תרומה אלא בדגן גמור שנאסף כראוי.","ומקשים: \u0003ולר' יוסי בר' יהודה נמי משכחת לה\u0004 \u0005[גם כן\u0006 יכול אתה \u0005למצוא\u0006 \u0005אותה]\u0006 אפשרות שיצטרך להפריש תרומה מן המלילות, כיצד — \u0003כגון שהכניס שבלין לעשות מהן עיסה\u0004 ושבלים אלה נתחייבו איפוא כבר בתרומה, \u0003ונמלך עליהן למוללן ביום טוב, דטבלא ביומיה\u0004 \u0005[ש\u0006חל איסור \u0005הטבל ביומו]\u0006 בשעתו, וחייב אז להפריש ומשהפריש מותר לו לאוכלו!","\u0003אלא\u0004 כך יש לומר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003תרומה\u0004 שמסכימים בית שמאי ובית הלל שאין מפרישים — הכוונה היא שאין רשאי להרים את \u0003רוב תרומה,\u0004 וכגון אלא שעשו בהם דישה ומירוח מערב יום טוב. אבל מודים הם שיש מקרים יוצאי דופן שבהם מותר להפריש תרומה ביום טוב.","\u0003אמר אביי: מחלוקת\u0004 זו ממתי חלה חובת תרומה ואיסור טבל על גידולי שדה היא דווקא \u0003בשבלין,\u0004 שדרכן להביאן לגורן, ושם יש להן דרך עיבוד קבועה. \u0003אבל בקטניות — דברי הכל אסורייתא טבלא\u0004 \u0005[החבילות,\u0006 האגודות, נעשות \u0005טבל]\u0006 ומאז חייבים להפריש מהם תרומה.","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שאפשר \u0005לסייע לו]\u0006 מן המשנה הבאה, ששנינו: \u0003מי שהיו לו חבילי תלתן\u0004 (שהוא מין קטניות) \u0003של טבל\u0004 — \u0003הרי זה כותש\u0004 את החבילות הללו, שזו הדרך להוציא את הגרגירים מתוך החבילות, \u0003ומחשב כמה זרע יש בהן\u0004 בכל החבילות, \u0003ומפריש תרומה על הזרע ואינו מפריש על העץ.\u0004 שאף שמשתמשים גם בגבעולים ובעלים לצורך בישול, מכל מקום אין צריך להפריש עליהם תרומה. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 שהלכה זו כשיטת \u0003ר' יוסי בר יהודה היא,\u0004 ש\u0003אמר\u0004 כי \u0003התם\u0004 \u0005[שם]\u0006 בשבלים הנמללות \u0003לא טבלא\u0004 \u0005[אינו\u0006 עושה \u0005טבל]\u0006 \u0003הכא טבלא\u0004 \u0005[כאן\u0006 הוא \u0005טבל]\u0006 ולכן החידוש שבדבר!","ודוחים: \u0003לא\u0004 אין מכאן ראיה, כי אפשר לומר שמשנה זו העוסקת בתלתן, כשיטת \u0003רבי היא\u0004 המחייב בכגון זה בהפרשה. ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003רבי היא\u0004 מה אם כן החידוש בכך? \u0003מאי אריא\u0004 \u0005[מה שייך],\u0006 מדוע דווקא אמר הלכה זו ב\u0003תלתן, אפילו שבלין נמי\u0004 \u0005[גם כן]\u0006 כך דינן לשיטתו, ומה טעם אמר בתלתן דווקא?","ודוחים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 אומר אתה כי משנה זו כשיטת \u0003ר' יוסי בר' יהודה\u0004 היא — אם כן \u0003לשמעינן\u0004 \u0005[שישמיע לנו]\u0006 הלכה זו ב\u0003שאר מיני קטניות\u0004 שנעשים טבל בחבילותיהן, \u0003וכל שכן תלתן\u0004 שהוא מין הנאכל רק בכמויות קטנות ואין עושים ממנו פרי כדגן.","\u0003אלא תלתן אצטריכא ליה\u0004 \u0005[הוצרך לו]\u0006 לאמרו מפני טעם אחר, ואין במשנה הוכחה לא כשיטת רבי ולא כר' יוסי בר' יהודה. כי \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]:\u0006 \u0003הואיל\u0004 והתלתן \u0003טעם עצו ופריו שוה,\u0004 שאף ענפי התלתן יש בהם בנותן טעם בקדרה, ואם כן \u0003לפרוש נמי אעצו\u0004 \u0005[שיפריש גם כן\u0006 תרומה \u0005על העץ]\u0006 של התלתן, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין חובה לעשות זאת, וזהו חידושה של המשנה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שלא כך אמר אביי את דבריו, אלא בגירסה אחרת נאמרו, וכך \u0003אמר אביי: מחלוקת\u0004 זו של רבי ור' יוסי בר' יהודה היא לגבי \u0003שבלין, אבל בקטניות — דברי הכל אסורייתא לא טבלא\u0004 \u0005[החבילות עצמן אינן טבל]\u0006 אף אם יתחיל לתקנן לאכילה. \u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005];\u0006 \u0003מי שהיו לו חבילי תלתן של טבל — הרי זה כותש, ומחשב כמה זרע יש בהן, ומפריש על הזרע ואינו מפריש על העץ. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן במקרה מיוחד ב\u0003טבל טבול של תרומה,\u0004 ובתיקון טבל לאכילת ישראל על ידי הרמת תרומה גדולה!","ודוחים: \u0003לא,\u0004 כאן מדובר במקרה אחר, ב\u0003טבל טבול של תרומת מעשר\u0004 שאין החבילות מתחייבות בהפרשה של תרומה גדולה, אלא רק בתרומה של מעשר מן המעשר, שנותן הלוי לכהן, וטרם ההפרשה אסור הלוי באכילת המעשר ראשון שהוא שלו.","\u0003וכ\u0004שיטת \u0003ר' אבהו אמר ר' שמעון בן לקיש.\u0004 ש\u0003אמר ר' אבהו אמר ר' שמעון בן לקיש: מעשר ראשון שהקדימו\u0004 הלוי לכהן ונטלו \u0003בשבלין\u0004 שאף שהדרך הראויה היא לתקן את התבואה בגורן ולהפריש ממנה בתחילה תרומה גדולה לכהן ורק אחר כך מעשר ראשון מן הנותר הניתן ללוי, מכל מקום, אם לא עשה כדין, והקדים הלוי ונטל את המעשר מן התבואה בעודה בשבלין","\u0003שמו\u0004 העובדה שכינהו מעשר הוא \u0003טובלו,\u0004 עושה אותו טבל ואסור באכילה לענין \u0003תרומת מעשר,\u0004 שאסור ללוי לאכול ממנו מיד עד שיפריש ממנו תרומת מעשר לכהן. ואם כן מצאנו דוגמה של הפרשת תרומה (תרומת מעשר) עוד טרם גמר מלאכה, וזהו ההסבר של אותה משנה.","ומקשים: אם כך, כיון שכבר שמו טובלו, \u0003כותש למה לי? לימא ליה\u0004 \u0005[שיאמר לו]\u0006 הלוי לכהן: \u0003כי היכי דיהבו לי, הכי יהיבנא לך\u0004 \u0005[כפי שנתנו לי\u0006 שבלים, או חבילות בלתי מתוקנות, \u0005כך אני נותן לך]\u0006 באותו מצב! \u0003אמר רבא: קנסא\u0004 \u0005[קנס]\u0006 הוא. כלומר: כך אכן היה צריך להיות, אבל מאחר שעשה הלוי שלא כהוגן שנטל את המעשר לפני זמנו — גזרו עליו שלא יפריש ממנו מעשר לכהן כצורתו, אלא יטרח בו ויתקננו, ורק אז יפריש ממנו מעשר מן המעשר.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 שאמרו: \u0003בן לוי שנתנו לו שבלין במעשרותיו\u0004 — \u0003עושה אותן גורן,\u0004 כלומר, דש ומתקן אותם כרגיל, וכן אם נתנו לו \u0003ענבים\u0004 — \u0003עושה אותן יין, זיתים\u0004 — \u0003עושה אותן שמן, ומפריש עליהם תרומת מעשר, ונותנן\u0004 אז \u0003לכהן. שכשם שתרומה גדולה אינה ניטלת\u0004"],["\u0003אלא מן הגורן ומן היקב\u0004 ולא מן התבואה שלא עובדה כלל, \u0003כך תרומת מעשר אינה ניטלת אלא מן הגורן ומן היקב.\u0004","ותוהים: אם נאמר שמדובר בטבול לישראל ומשום שעדיין לא הורמה ממנו תרומה גדולה, אכן שייך לומר לשון \"מחשב\" שנאמרה במשנה, אולם מאחר ולדבריך מדובר פה בטבול ללוי ומשום שעדיין לא הורמה תרומת המעשר, אם כן מדוע נאמר שם במשנה במסכת תרומות לשון \u0003\"מחשב\"? הא\u0004 \u0005[זה]\u0006 לשון \u0003\"מדידה\" בעי\u0004 \u0005[הוא צריך]!\u0006 כי כאשר מדובר בתרומה גדולה יכול הנותן לחשב ולהעריך בלבד, שהרי אין שיעור מן התורה לתרומה זו. אבל מעשר מן המעשר, כיון שקצבה לכך התורה שיעור מסויים ומוגדר הרי צריך לדייק ולמדוד!","ומסבירים: \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 כשיטת \u0003אבא אלעזר בן גימל היא דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אבא אלעזר בן גימל אומר\u0004 על הפסוק \u0003\"ונחשב לכם תרומתכם\u0004 כדגן מן הגורן וכמלאה מן היקב\" (במדבר יח, כז) — \u0003בשתי תרומות הכתוב מדבר, אחת תרומה גדולה ואחת תרומת מעשר.\u0004 ומכאן למדים: \u0003כשם שתרומה גדולה ניטלת באומד\u0004 שאינו צריך למדוד במדוייק \u0003ו\u0004כן די לה שתינטל \u0003במחשבה\u0004 בלבד שאינו צריך להפריש בפועל אלא די שיחשוב בלבו להפריש חלק מסויים, ומיד נעשה השאר מתוקן לאכילה — \u0003כך תרומת מעשר\u0004 גם היא \u0003ניטלת באומד ובמחשבה.\u0004","כיון שהוזכרו הדברים דנים בהלכה זו לגופה: \u0003אמר ר' אבהו אמר ר' שמעון בן לקיש: מעשר ראשון שהקדימו בשבלין\u0004 — \u0003שמו טובלו,\u0004 עד שיפריש \u0003לתרומת מעשר.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמה]\u0006 של הלכה זו? \u0003אמר רבא: הואיל ויצא עליו שם מעשר,\u0004 שהרי זה קרוי מעשר, ולכן חלה עליו החובה גם ל\"מעשר מן המעשר\".","אגב דברים אלה מביאים הלכה דומה שגם אותה \u0003אמר ר' שמעון בן לקיש: מעשר ראשון שהקדימו\u0004 הלוי לכהן ונטלו עוד \u0003בשבלין,\u0004 לפני שדשו אותן ועשו אותן ערימה (כרי) ולפני שהורמה תרומה גדולה לכהן — \u0003פטור\u0004 חלק זה של המעשר \u0003מתרומה גדולה.\u0004","שאף שצריך להפריש תחילה מן התבואה תרומה גדולה לכהן והיה צריך ליטול תרומה גדולה גם מן התבואה שהיא במעשר זה, מכל מקום נפטר הלוי מהפרשה זו, \u0003שנאמר\u0004 בכתוב: \u0003\"והרמתם ממנו תרומת ה' מעשר מן המעשר\"\u0004 (במדבר יח, כו) ומלשון הכתוב נסיק: \u0003מעשר מן המעשר\u0004 בלבד \u0003אמרתי לך\u0004 להפריש מן המעשר ראשון, \u0003ולא תרומה גדולה ותרומת מעשר מן המעשר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: אי הכי\u0004 \u0005[אם כך]\u0006 שנלמד הדבר מן הכתוב, \u0003אפילו הקדימו\u0004 הלוי לכהן \u0003בכרי נמי\u0004 \u0005[גם כן]\u0006 יהיה כן הדין, ולא יצטרך הלוי להפריש מהחלק שנטל תרומה גדולה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי לרב פפא: \u0003עליך,\u0004 כלומר כנגד דברים אלה, \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 ללויים: \u0003\"מכל מתנתיכם תרימו את כל תרומת ה'\"\u0004 (במדבר יח, כט) ללמד שאת תרומת ה', התרומה הגדולה, צריך להרים מכל מתנה ומתנה ובכלל זה אף ממעשר ראשון שהוקדם וניטל על ידי הלוי לפני שנטל הכהן את התרומה הגדולה.","ושואלים: \u0003ומה ראית\u0004 לחלק בצורה זו ולומר שכשנטל הלוי שבלים יפריש רק תרומת מעשר, וכשנטל מן הכרי יפריש את כל התרומות כולם? ומשיבים: \u0003האי אדגן\u0004 \u0005[זה\u0006 שהיה בכרי כבר \u0005נעשה דגן]\u0006 שאינו נקרא עוד שבולת ושמו דגן, ובתרומה נאמר במפורש \"ראשית דגנך\". \u0003והאי לא אדגן\u0004 \u0005[וזה\u0006 בשבלים עדיין \u0005לא נעשה דגן]\u0006 ולא חלה עליו עוד חובת תרומה.","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת מעשרות: \u0003המקלף שעורין\u0004 כדי לאוכלן חיות כמות שהן, \u0003מקלף אחת אחת ואוכלן\u0004 מיד ואינו חייב במעשר, לפי שזו היא אכילת עראי. \u0003ואם קלף ונתן לתוך ידו\u0004 הרבה מן המקולפות יחד — \u0003חייב\u0004 להפריש מעשרות. \u0003אמר ר' אלעזר: וכן\u0004 ההלכה \u0003לשבת,\u0004 שאם מקלף אחת אחת אין בכך משום איסור מלאכה (של דישה) ומותר. ואם מקלף כדי יד שלימה, יש בזה משום מלאכת דישה.","ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב מקלפא ליה דביתהו כסי כסי\u0004 \u0005[היתה מקלפת לו אשתו\u0006 בשבת \u0005כוסות כוסות\u0006 של שעורים קלופות\u0005]!\u0006 וכן \u0003ר' חייא מקלפא ליה דביתהו כסי כסי\u0004 \u0005[היתה מקלפת לו אשתו כוסות כוסות]!\u0006 \u0003אלא\u0004 יש לשנות את הגירסה ולומר כי \u0003אי אתמר אסיפא אתמר\u0004 \u0005[אם נאמר\u0006 דבר בענין זה \u0005על סופה\u0006 של אותה משנה \u0005נאמר]\u0006 ששנינו שם: \u0003המולל מלילות של חטים\u0004 שממעך את החטים בידו עד שקליפתן החיצונה נופלת, \u0003מנפח\u0004 (נופח ברוח פיו על המוץ שיתפזר) \u0003על יד על יד\u0004 (מעט מעט), \u0003ואוכל\u0004 בלי לעשר. \u0003ואם נפח ונתן לתוך חיקו\u0004 כמות גדולה — הרי זה \u0003חייב\u0004 במעשר. ועל כך \u0003אמר ר' אלעזר: וכן לשבת.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' אבא בר מלל:\u0004 וכי רוצה אתה לפרש ש\u0003רישא\u0004 \u0005[\u0006ש\u0005תחילת\u0006 המשנה\u0005]\u0006 בשעורים לענין \u0003מעשר — אין\u0004 \u0005[כן]\u0006 נחשב זה לגמר מלאכה \u0003ולשבת לא? ומי איכא מידי\u0004 \u0005[האם יש דבר]\u0006 ש\u0003לענין שבת לא הוי\u0004 \u0005[אינו,\u0006 איננו נחשב\u0005]\u0006 ל\u0003גמר מלאכה\u0004 ומותר לעשותו, \u0003ולמעשר הוי\u0004 \u0005[הריהו\u0006 נחשב\u0005]\u0006 ל\u0003גמר מלאכה?\u0004 והרי איסור מלאכה בשבת חמור הרבה בכלליו ובפרטיו!","\u0003מתקיף לה\u0004 \u0005[מקשה\u0006 על קושיה זו\u0005]\u0006 \u0003רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: ו\u0004כי \u0003לא\u0004 מצאנו דוגמה כזו? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003גרנן למעשר\u0004 הוא מקרה כזה, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003איזהו\u0004 דבר נחשב כ\u0003גרנן\u0004 של מינים שונים של ירקות וזהו גמר מלאכתם, שהוא זמן חיובן ב\u0003מעשר? הקשואין והדלועין\u0004 — \u0003משיפקסו,\u0004 כלומר, משעה שמסיר מהם את השיער הדק שעליהם. ואלה \u0003שלא פקסו\u0004 שלא הסירו מהם את השיער — \u0003משיעמיד ערימה\u0004 זהו גמר מלאכתן ומאז חייבים הם במעשר. \u0003ותנן נמי\u0004 \u0005[ושנינו גם כן\u0006 במשנה\u0005]\u0006 \u0003לגבי בצלים,\u0004 שגמר מלאכתם למעשר \u0003משיעמיד ערמה. ואילו לגבי שבת\u0004 — \u0003העמדת ערמה פטור,\u0004 שאין בכך משום מלאכה בשבת.","\u0003אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר],\u0006 מדוע פטור בשבת בהעמדת ערימה — כי \u0003\"מלאכת מחשבת\" אסרה תורה\u0004 בשבת, מלאכה שיש בה מעשה יצירה של דבר חדש, והעמדת ערימה אינה נקראת מלאכת מחשבת לענין שבת, אם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין קלוף השעורה \u0003מלאכת מחשבת אסרה תורה,\u0004 ואף שהדבר נחשב לגמר מלאכה לענין מעשר, איננו נחשב כמלאכה בשבת.","כיון שהזכרנו ענין זה של מלילה בשבת שואלים: \u0003כיצד מולל\u0004 ביום טוב? \u0003אביי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב יוסף אמר:\u0004 אצבע \u0003חדא אחדא\u0004 \u0005[אחת על אחת],\u0006 כלומר מניח בין שתי האצבעות ומולל. \u0003ורב אויא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב יוסף אמר:\u0004 אפילו \u0003חדא אתרתי\u0004 \u0005[אחת על שתים]\u0006 בין האגודל לשתי האצבעות. \u0003רבא אמר: כיון דמשני\u0004 \u0005[שהוא משנה]\u0006 ואיננו עושה כרגיל — \u0003אפילו חדא אכולהו נמי\u0004 \u0005[אחת על כולם גם כן],\u0006 שאם מועך מלילות המצויות על כל האצבעות כולן — גם כן מותר, כיון שבכל אופן הוא שינוי מן הרגיל.","ועוד שואלים: \u0003כיצד מנפח\u0004 בשבת באופן המותר? \u0003אמר רב אדא בר אהבה אמר רב: מנפח\u0004"]]};
